((window.CARDS_BY_LANG = window.CARDS_BY_LANG || {}).el = window.CARDS_BY_LANG.el || {}).series = [{"name":"Game of Thrones","emoji":"🐉","meta":["δράμα, φαντασίας","2011–2019","ΗΠΑ"],"description":"Επική μεταφορά των μυθιστορημάτων του Τζορτζ Μάρτιν για τον πόλεμο των αρχοντικών οίκων γύρω από τον Σιδερένιο Θρόνο του Ουέστερος. Το HBO έδεσε πολιτικές ίντριγκες, τεράστιες μάχες και μυθολογία με δράκους και την απειλή πέρα από το Τείχος. Στην ακμή της η σειρά μάζευε δεκάδες εκατομμύρια θεατές παγκοσμίως.","fact":"Η τελευταία σεζόν προκάλεσε κύμα αιτημάτων από απογοητευμένους θεατές, που ζητούσαν να ξαναγυριστεί το φινάλε από την αρχή.","wiki_en":"Game of Thrones"},{"name":"Breaking Bad","emoji":"🧪","meta":["δράμα, αστυνομικό","2008–2013","ΗΠΑ"],"description":"Ένας καθηγητής χημείας, μετά τη διάγνωση καρκίνου, αρχίζει να φτιάχνει μεθαμφεταμίνη για να εξασφαλίσει την οικογένειά του και σιγά σιγά μετατρέπεται σε αδίστακτο βαρόνο του εγκλήματος. Η σειρά ξεχωρίζει για τη δουλεμένη δραματουργία και τη βαθμιαία μεταμόρφωση του ήρωα.","fact":"Ο δημιουργός Βινς Γκίλιγκαν περιέγραφε την ιδέα ως τη μετατροπή του κυρίου Τσιπς σε Σκαρφέις.","wiki_en":"Breaking Bad"},{"name":"Friends","emoji":"☕","meta":["σιτκόμ","1994–2004","ΗΠΑ"],"description":"Έξι φίλοι ζουν στην ίδια γειτονιά της Νέας Υόρκης και περνούν μαζί δουλειές, σχέσεις και ενηλικίωση. Το μεγαλύτερο μέρος της δράσης εξελίσσεται στα σπίτια τους και στην καφετέρια Central Perk, που έγινε ένα από τα πιο αναγνωρίσιμα σκηνικά της τηλεόρασης.","fact":"Οι ηθοποιοί επέμειναν σε ίσες αμοιβές και στις τελευταίες σεζόν έπαιρναν ένα εκατομμύριο δολάρια ο καθένας ανά επεισόδιο.","wiki_en":"Friends"},{"name":"The Office","emoji":"📎","meta":["ψευδοντοκιμαντέρ, κομεντί","2005–2013","ΗΠΑ"],"description":"Η αμερικανική εκδοχή της βρετανικής σειράς, γυρισμένη σαν ψεύτικο ντοκιμαντέρ για την καθημερινότητα των υπαλλήλων της Dunder Mifflin, μιας εταιρείας χαρτιού σε μια επαρχιακή πόλη. Υποτίθεται ότι τους καταγράφει συνεργείο, και οι ήρωες μιλούν συνεχώς στην κάμερα.","fact":"Ξεκίνησε ως σχεδόν κατά λέξη ριμέικ του βρετανικού πρωτότυπου, αλλά από τη δεύτερη σεζόν βρήκε δικό της τόνο και έγινε αυτοτελές φαινόμενο.","wiki_en":"The Office (American TV series)"},{"name":"The Simpsons","emoji":"🍩","meta":["κινούμενα σχέδια, κομεντί","από το 1989","ΗΠΑ"],"description":"Σειρά κινουμένων σχεδίων για μια κιτρινοπρόσωπη οικογένεια από τη φανταστική πόλη Σπρίνγκφιλντ, που σατιρίζει την αμερικανική καθημερινότητα, την ποπ κουλτούρα και την πολιτική. Παίζει περισσότερα χρόνια από κάθε άλλη σειρά πρώτης ζώνης στην ιστορία της αμερικανικής τηλεόρασης.","fact":"Πολλές ανατροπές της σειράς βγήκαν αργότερα αληθινές, κι έτσι γεννήθηκε ένας ολόκληρος διαδικτυακός μύθος για τις προβλέψεις της.","wiki_en":"The Simpsons"},{"name":"South Park","emoji":"🏔️","meta":["κινούμενα σχέδια, κομεντί","από το 1997","ΗΠΑ"],"description":"Σκανδαλιστική σειρά κινουμένων σχεδίων για τέσσερα αγόρια σε μια μικρή ορεινή πόλη του Κολοράντο, που σατιρίζει την επικαιρότητα και τα κοινωνικά ταμπού σχεδόν χωρίς φίλτρα. Τα επεισόδια συχνά γράφονται και μοντάρονται μέρες πριν από τη μετάδοση, για να προλάβουν την ειδησεογραφία.","fact":"Ο Κένι, ένας από τους τέσσερις πρωταγωνιστές, πεθαίνει σχεδόν σε κάθε επεισόδιο των πρώτων σεζόν και επιστρέφει σώος στο επόμενο.","wiki_en":"South Park"},{"name":"Family Guy","emoji":"🐶","meta":["κινούμενα σχέδια, κομεντί","από το 1999","ΗΠΑ"],"description":"Σειρά κινουμένων σχεδίων για την παράλογη οικογένεια Γκρίφιν στη φανταστική πόλη Κουάχογκ, όπου η δράση διακόπτεται διαρκώς από παράλογες παρεκβάσεις και παρωδιακά φλάσμπακ. Ο δημιουργός Σεθ ΜακΦάρλαν δανείζει τη φωνή του σε πολλούς βασικούς ήρωες, ανάμεσά τους και στον σκύλο Μπράιαν που μιλάει.","fact":"Αφού κόπηκε στις αρχές των 2000 λόγω χαμηλών ποσοστών, επέστρεψε στον αέρα χάρη στην τρελή επιτυχία των επαναλήψεων και των πωλήσεων DVD.","wiki_en":"Family Guy"},{"name":"Rick and Morty","emoji":"🌀","meta":["κινούμενα σχέδια, επιστημονική φαντασία","από το 2013","ΗΠΑ"],"description":"Σειρά κινουμένων σχεδίων για τον Ρικ, έναν ιδιοφυή, κυνικό και αλκοολικό επιστήμονα, και τον αγχώδη εγγονό του Μόρτι, που ταξιδεύουν σε αμέτρητες διαστάσεις και κόσμους. Κάτω από το τρελό χιούμορ και την επιστημονική φαντασία κρύβονται σκέψεις για το νόημα της ύπαρξης και για την οικογένεια.","fact":"Την πολεμική κραυγή του Ρικ «Wubba lubba dub dub» ο φίλος του Birdperson τη μεταφράζει πολύ πιο θλιβερά: «πονάω πάρα πολύ, βοηθήστε με».","wiki_en":"Rick and Morty"},{"name":"Futurama","emoji":"🚀","meta":["κινούμενα σχέδια, επιστημονική φαντασία","από το 1999, με διακοπές","ΗΠΑ"],"description":"Σειρά του Ματ Γκρέινινγκ, δημιουργού των Simpsons, για τον διανομέα Φράι, που παγώνει σε κρυογονική κάψουλα το 1999 και ξυπνά χίλια χρόνια μετά σε ένα παράξενο μέλλον. Μαζί με το πλήρωμα ενός διαστημόπλοιου κούριερ μπλέκει σε περιπέτειες σε όλο τον γαλαξία.","fact":"Παρά τις αρκετές ακυρώσεις και τα λουκέτα, η σειρά επέστρεψε ξανά και ξανά με ταινίες, νέες σεζόν και αναβιώσεις στις πλατφόρμες.","wiki_en":"Futurama"},{"name":"Stranger Things","emoji":"💡","meta":["επιστημονική φαντασία, τρόμου","από το 2016","ΗΠΑ"],"description":"Νοσταλγική ιστορία με άρωμα δεκαετίας του 1980 για μια παρέα εφήβων στη μικρή πόλη Χόκινς, όπου μετά την εξαφάνιση ενός παιδιού αρχίζουν υπερφυσικά γεγονότα. Η σειρά πλέκει την εφηβική φιλία με τη μυθολογία ενός παράλληλου κόσμου, του Ανάστροφου.","fact":"Έκανε αστέρια παιδιά ηθοποιούς σχεδόν άγνωστα ως τότε και επανέφερε στο προσκήνιο τη Γουινόνα Ράιντερ, σταρ του κινηματογράφου της δεκαετίας του 1990.","wiki_en":"Stranger Things"},{"name":"The Sopranos","emoji":"🍝","meta":["δράμα, αστυνομικό","1999–2007","ΗΠΑ"],"description":"Δράμα για έναν ιταλοαμερικανό αρχηγό της μαφίας στο Νιου Τζέρσεϊ, που παράλληλα με τις εγκληματικές του δουλειές πηγαίνει σε ψυχοθεραπεύτρια για να αντιμετωπίσει τις κρίσεις πανικού. Η σειρά έθεσε σε μεγάλο βαθμό τον κανόνα για το σύγχρονο «πρεστίζ» τηλεοπτικό δράμα.","fact":"Η τελευταία σκηνή στο εστιατόριο, που κόβεται σε απότομο μαύρο πάνω στο τραγούδι, συζητιέται ακόμη.","wiki_en":"The Sopranos"},{"name":"The Wire","emoji":"🎧","meta":["δράμα, αστυνομικό","2002–2008","ΗΠΑ"],"description":"Πολυεπίπεδο δράμα για τη Βαλτιμόρη, που ξεκινά από τις τηλεφωνικές υποκλοπές σε εμπόρους ναρκωτικών και δείχνει την πόλη από κάθε πλευρά: αστυνομία, λιμενεργάτες, σχολεία, πολιτικούς, Τύπο. Κάθε σεζόν μετατοπίζει το βλέμμα σε άλλον θεσμό της αστικής ζωής.","fact":"Στην αρχική της προβολή δεν πήρε ούτε ένα Έμι, παρότι οι κριτικοί τη βάζουν τακτικά στις καλύτερες σειρές όλων των εποχών.","wiki_en":"The Wire"},{"name":"Sherlock","emoji":"🔍","meta":["αστυνομικό, δράμα","2010–2017","Ηνωμένο Βασίλειο"],"description":"Σύγχρονη βρετανική ανάγνωση των ιστοριών του Άρθουρ Κόναν Ντόιλ, με τον Σέρλοκ Χολμς και τον δόκτορα Γουάτσον να δρουν στο σημερινό Λονδίνο, με κινητά και σόσιαλ μίντια στη θέση των τηλεγραφημάτων. Ξεχωρίζει για τον ιλιγγιώδη ρυθμό και για τη σκέψη του ντετέκτιβ που ξετυλίγεται πάνω στην οθόνη.","fact":"Λόγω των φορτωμένων προγραμμάτων των ηθοποιών, οι σεζόν έχουν μόλις τρία επεισόδια σε μήκος ταινίας, και τα διαλείμματα ανάμεσά τους κράτησαν χρόνια.","wiki_en":"Sherlock (TV series)"},{"name":"House","emoji":"🩺","meta":["δράμα","2004–2012","ΗΠΑ"],"description":"Ιατρικό δράμα για τον δόκτορα Χάουζ, έναν λαμπρό αλλά εντελώς ανυπόφορο διαγνωστή, που μαζί με την ομάδα του ξεμπερδεύει τα πιο αινιγματικά και σπάνια περιστατικά. Ο ήρωας φημίζεται για τις κυνικές ατάκες του και για τον κανόνα ότι οι ασθενείς πάντα λένε ψέματα.","fact":"Οι δημιουργοί εμπνεύστηκαν τον Χάουζ ανοιχτά από τον Σέρλοκ Χολμς, μέχρι και τον αριθμό του διαμερίσματος και τον πιστό φίλο-βοηθό.","wiki_en":"House (TV series)"},{"name":"Lost","emoji":"🏝️","meta":["δράμα, επιστημονική φαντασία","2004–2010","ΗΠΑ"],"description":"Μετά τη συντριβή ενός αεροπλάνου, μια ομάδα επιζώντων βρίσκεται σε ένα μυστηριώδες τροπικό νησί όπου συμβαίνουν ανεξήγητα πράγματα. Η σειρά συνδυάζει το δράμα των σχέσεων των ηρώων με τη μυθολογία του νησιού, που αποκαλύπτεται μέσα από φλάσμπακ.","fact":"Ήταν από τις πρώτες σειρές που έκαναν τα μη γραμμικά φλάσμπακ και φλασφόργουορντ βασικό εργαλείο αφήγησης στην τηλεόραση.","wiki_en":"Lost (TV series)"},{"name":"Prison Break","emoji":"⛓️","meta":["δράμα, θρίλερ","2005–2009","ΗΠΑ"],"description":"Ο μηχανικός Μάικλ Σκοφίλντ διαπράττει επίτηδες ένα έγκλημα για να μπει στη φυλακή όπου κρατείται άδικα καταδικασμένος ο αδελφός του, με το σχέδιο απόδρασης τατουάζ στο σώμα του. Η σειρά στήνεται γύρω από την αγωνιώδη προετοιμασία και εκτέλεση μιας τολμηρής απόδρασης.","fact":"Το τεράστιο τατουάζ-χάρτη δεν το χτύπησαν στον ηθοποιό: οι μακιγιέρ το περνούσαν με χαλκομανίες, διαδικασία που κρατούσε ώρες.","wiki_en":"Prison Break"},{"name":"Dexter","emoji":"🔪","meta":["δράμα, θρίλερ","2006–2013","ΗΠΑ"],"description":"Ο Ντέξτερ Μόργκαν, αναλυτής αίματος της αστυνομίας του Μαϊάμι, τη μέρα βοηθά στην εξιχνίαση φόνων και τη νύχτα σκοτώνει ο ίδιος εγκληματίες, ακολουθώντας τον αυστηρό «κώδικα» του θετού πατέρα του. Η σειρά στηρίζεται στις εσωτερικές σκέψεις του ήρωα για τη διπλή ζωή του.","fact":"Τον πρωταγωνιστή υποδύεται ο Μάικλ Σι Χολ, γνωστός ως τότε από μια άλλη ιδιότυπη σειρά για τον θάνατο, το Six Feet Under.","wiki_en":"Dexter (TV series)"},{"name":"The Walking Dead","emoji":"🧟","meta":["τρόμου, δράμα","2010–2022","ΗΠΑ"],"description":"Μεταφορά των κόμικς για τον σερίφη Ρικ Γκράιμς, που συνέρχεται από κώμα σε έναν κόσμο κατακλυσμένο από επιδημία ζόμπι και συγκεντρώνει γύρω του μια ομάδα επιζώντων. Στην πορεία το βάρος μετατοπίζεται από τα ζόμπι στη σύγκρουση ανάμεσα σε ανθρώπινες ομάδες.","fact":"Για χρόνια ήταν η πιο δημοφιλής σειρά της αμερικανικής καλωδιακής τηλεόρασης στους θεατές κάτω των 49 ετών.","wiki_en":"The Walking Dead (TV series)"},{"name":"The Big Bang Theory","emoji":"🤓","meta":["σιτκόμ","2007–2019","ΗΠΑ"],"description":"Σιτκόμ για μια παρέα φυσικών του Κάλτεκ, που ζουν για την επιστήμη, τα κόμικς και τα βιντεοπαιχνίδια, ώσπου στο απέναντι διαμέρισμα μετακομίζει η συμπαθητική σερβιτόρα Πένι. Το χιούμορ βγαίνει από την αντίθεση ανάμεσα στη λάμψη τους στην επιστήμη και την αδεξιότητά τους στην απλή συναναστροφή.","fact":"Τους τύπους στους πίνακες τους έγραφε για λόγους ακρίβειας προσκεκλημένος σύμβουλος, φυσικός από το Πανεπιστήμιο της Καλιφόρνιας.","wiki_en":"The Big Bang Theory"},{"name":"How I Met Your Mother","emoji":"☂️","meta":["σιτκόμ","2005–2014","ΗΠΑ"],"description":"Ο Τεντ Μόσμπι μιλά από το μέλλον και διηγείται στα παιδιά του τη μακριά και μπερδεμένη ιστορία του πώς γνώρισε τη μητέρα τους, θυμίζοντας χρόνια φιλίας, έρωτα και περιπετειών με τέσσερις στενούς φίλους στη Νέα Υόρκη. Κομβικός στην παρέα ο εκκεντρικός και γοητευτικός Μπάρνι.","fact":"Τη μητέρα ο θεατής τη βλέπει πρώτη φορά μόλις στο φινάλε της όγδοης σεζόν· ως τότε υπονοείται με λεπτομέρειες όπως μια κίτρινη ομπρέλα.","wiki_en":"How I Met Your Mother"},{"name":"Scrubs","emoji":"🏥","meta":["σιτκόμ","2001–2010","ΗΠΑ"],"description":"Κομεντί για την καθημερινότητα του νέου γιατρού Τζέι Ντι στο φανταστικό νοσοκομείο Sacred Heart, όπου το παράλογο χιούμορ συνυπάρχει με απρόσμενα σοβαρές και συγκινητικές ιατρικές ιστορίες. Μεγάλο μέρος των αστείων βγαίνει από τις φαντασιώσεις του ήρωα, που ο θεατής τις βλέπει στην οθόνη.","fact":"Πολλές ιστορίες της σειράς βασίστηκαν σε αληθινά περιστατικά που διηγούνταν στους σεναριογράφους ένας γιατρός-σύμβουλος από πραγματικό νοσοκομείο.","wiki_en":"Scrubs (TV series)"},{"name":"Sex and the City","emoji":"👠","meta":["κομεντί, δράμα","1998–2004","ΗΠΑ"],"description":"Η αρθρογράφος Κάρι Μπράντσο και τρεις στενές της φίλες ζουν έντονα στη Νέα Υόρκη, συζητώντας για έρωτα, καριέρα και σεξ πάνω από ένα κοκτέιλ Cosmopolitan. Κάθε επεισόδιο στήνεται γύρω από τη στήλη που γράφει η Κάρι για τις σύγχρονες σχέσεις.","fact":"Η γκαρνταρόμπα των ηρωίδων, με τα περίφημα παπούτσια Manolo Blahnik, έγινε από μόνη της κομμάτι της πολιτιστικής κληρονομιάς της σειράς.","wiki_en":"Sex and the City"},{"name":"Desperate Housewives","emoji":"🏡","meta":["δράμα, κομεντί","2004–2012","ΗΠΑ"],"description":"Η ζωή μερικών νοικοκυρών στον ήσυχο δρόμο Γουιστίρια Λέιν, γεμάτη μυστικά, απιστίες και εγκλήματα, μέσα από τα μάτια της γειτόνισσας που αυτοκτονεί στο πρώτο επεισόδιο και σχολιάζει τα γεγονότα εκτός κάδρου. Η σειρά ανακατεύει σαπουνόπερα με μαύρο χιούμορ και αστυνομική ίντριγκα.","fact":"Η ιδέα ήρθε στον δημιουργό αφού είδε ένα δελτίο ειδήσεων για μια μητέρα που έπνιξε τα παιδιά της.","wiki_en":"Desperate Housewives"},{"name":"Gossip Girl","emoji":"💌","meta":["δράμα","2007–2012","ΗΠΑ"],"description":"Η ζωή των καλομαθημένων εφήβων του Άπερ Ιστ Σάιντ του Μανχάταν, όπως τη λένε τα ανώνυμα μηνύματα μιας μυστηριώδους μπλόγκερ του κουτσομπολιού, που ξέρει όλα τα μυστικά, τις απιστίες και τα σκάνδαλα των προνομιούχων. Κάθε επεισόδιο συνοδεύεται από τα σχόλιά της εκτός κάδρου.","fact":"Τη φωνή της Gossip Girl δίνει η ηθοποιός Κρίστεν Μπελ, και η ταυτότητα της μπλόγκερ αποκαλύπτεται μόνο στο τελευταίο επεισόδιο.","wiki_en":"Gossip Girl"},{"name":"Grey's Anatomy","emoji":"❤️‍🩹","meta":["δράμα","από το 2005","ΗΠΑ"],"description":"Ιατρικό δράμα για τους ειδικευόμενους χειρουργούς του νοσοκομείου Seattle Grace, που η επαγγελματική τους ζωή είναι αδιαχώριστη από τις μπερδεμένες προσωπικές σχέσεις και τους έρωτες μεταξύ τους. Γνωστή για τους μονολόγους της Μέρεντιθ Γκρέι, έγινε μια από τις πιο μακρόβιες αμερικανικές σειρές.","fact":"Ο τίτλος παίζει με ένα παλιό εγχειρίδιο ανατομίας, από το οποίο έμαθαν γενιές και γενιές γιατρών.","wiki_en":"Grey's Anatomy"},{"name":"The X-Files","emoji":"👽","meta":["επιστημονική φαντασία, αστυνομικό","1993–2018","ΗΠΑ"],"description":"Οι πράκτορες του FBI Μαλντέρ και Σκάλι ερευνούν υποθέσεις με παραφυσικά φαινόμενα, εξωγήινους και κυβερνητικές συνωμοσίες: αυτός πιστεύει στο ανεξήγητο, η σκεπτικίστρια συνεργάτιδά του ψάχνει λογικές εξηγήσεις. Η σειρά καθόρισε σε μεγάλο βαθμό το τηλεοπτικό μυστήριο της δεκαετίας του 1990.","fact":"Το σλόγκαν «Η αλήθεια είναι εκεί έξω» έγινε παροιμιώδης φράση πολύ πιο πέρα από την τηλεόραση.","wiki_en":"The X-Files"},{"name":"Twin Peaks","emoji":"🪵","meta":["αστυνομικό, μυστηρίου","1990–1991","ΗΠΑ"],"description":"Η έρευνα για τον φόνο της μαθήτριας Λόρα Πάλμερ φέρνει τον πράκτορα του FBI Ντέιλ Κούπερ στη μικρή πόλη Τουίν Πικς, όπου πίσω από τη βιτρίνα της ήσυχης επαρχίας κρύβονται σουρεαλιστικά μυστικά και υπερκόσμιες δυνάμεις. Ο Ντέιβιντ Λιντς ένωσε την αστυνομική πλοκή με ατμόσφαιρα ονείρου.","fact":"Η περίφημη φράση «Οι κουκουβάγιες δεν είναι αυτό που φαίνονται» έγινε ένα από τα κύρια σύμβολα της αινιγματικής μυθολογίας της σειράς.","wiki_en":"Twin Peaks"},{"name":"True Detective","emoji":"🥃","meta":["αστυνομικό, δράμα","από το 2014","ΗΠΑ"],"description":"Ανθολογία όπου κάθε σεζόν διηγείται μια ξεχωριστή, σκοτεινή αστυνομική ιστορία με νέους ήρωες και νέους ηθοποιούς. Η πρώτη και πιο γνωστή παρακολουθεί δύο ντετέκτιβ που για σχεδόν είκοσι χρόνια ερευνούν μια σειρά τελετουργικών φόνων στη Λουιζιάνα.","fact":"Μια σκηνή έξι λεπτών στο τέταρτο επεισόδιο της πρώτης σεζόν γυρίστηκε σε ένα αδιάκοπο πλάνο και έγινε από τις πιο συζητημένες στην τηλεόραση.","wiki_en":"True Detective"},{"name":"Black Mirror","emoji":"📱","meta":["επιστημονική φαντασία, δράμα","από το 2011","Ηνωμένο Βασίλειο"],"description":"Ανθολογία όπου σχεδόν κάθε επεισόδιο είναι μια αυτοτελής, σκοτεινή παραβολή για το πώς η σύγχρονη τεχνολογία στραβώνει τις ανθρώπινες σχέσεις και τις κοινωνίες. Ο τίτλος παραπέμπει στη σβηστή οθόνη της συσκευής, στην οποία κοιτάμε σαν σε καθρέφτη.","fact":"Ένα από τα επεισόδια, το «Bandersnatch», ήταν διαδραστική ταινία, όπου ο θεατής διάλεγε μόνος την εξέλιξη της πλοκής.","wiki_en":"Black Mirror"},{"name":"Peaky Blinders","emoji":"🎩","meta":["δράμα, αστυνομικό","2013–2022","Ηνωμένο Βασίλειο"],"description":"Η ιστορία της εγκληματικής οικογένειας Σέλμπι στο Μπέρμιγχαμ, που μετά τον Α΄ Παγκόσμιο Πόλεμο στήνει τη δική της αυτοκρατορία υπό τον χαρισματικό και ψύχραιμο Τόμας Σέλμπι. Ο τίτλος παραπέμπει στη θρυλούμενη συνήθεια της συμμορίας να κρύβει ξυραφάκια στα γείσα των κασκέτων.","fact":"Παρότι η δράση τοποθετείται στις αρχές του 20ού αιώνα, η μουσική της σειράς είναι σχεδόν εξ ολοκλήρου σύγχρονη ροκ και ηλεκτρονική.","wiki_en":"Peaky Blinders"},{"name":"Vikings","emoji":"⚔️","meta":["δράμα, ιστορικό","2013–2020","Καναδάς"],"description":"Η ημιθρυλική ιστορία του σκανδιναβού αρχηγού Ράγκναρ Λόντμπροκ, που ξεσηκώνει τους δικούς του για τολμηρές θαλάσσιες επιδρομές στη Δυτική Ευρώπη. Η σειρά στηρίζεται ελεύθερα στις σκανδιναβικές σάγκες και τα χρονικά, ανακατεύοντας ιστορικά γεγονότα με μυθολογία.","fact":"Πολλοί διάλογοι ακούγονται στα παλαιά σκανδιναβικά και τα παλαιά αγγλικά, με υπότιτλους, για πιστότητα στην εποχή.","wiki_en":"Vikings (2013 TV series)"},{"name":"The Witcher","emoji":"🐺","meta":["φαντασίας, δράμα","από το 2019","ΗΠΑ"],"description":"Μεταφορά της σειράς βιβλίων του Άντζεϊ Σαπκόφσκι για τον γητευτή Γκέραλτ της Ρίβια, κυνηγό τεράτων επί πληρωμή, που ο δρόμος του μπλέκεται με τις μοίρες της μάγισσας Γιένεφερ και της πριγκίπισσας Σίρι. Σκοτεινό φανταστικό με πολιτικές ίντριγκες αντίπαλων βασιλείων.","fact":"Ο Χένρι Κάβιλ είναι μεγάλος φαν των βιβλίων και των παιχνιδιών, και για τον ρόλο γυρίστηκε με λευκή περούκα και κίτρινους φακούς επαφής.","wiki_en":"The Witcher (TV series)"},{"name":"The Mandalorian","emoji":"🪖","meta":["επιστημονική φαντασία","από το 2019","ΗΠΑ"],"description":"Ένας μοναχικός κυνηγός επικηρυγμένων με ατσάλινη πανοπλία, από το σύμπαν του «Πολέμου των Άστρων», παίρνει υπό την προστασία του ένα μυστηριώδες μωρό του δικού του είδους και ξεκινά επικίνδυνο ταξίδι στα άκρα του γαλαξία. Η σειρά ξανάφερε το πνεύμα του γουέστερν στην παλιά σάγκα.","fact":"Το χαριτωμένο πράσινο μωρό, που οι φαν βάφτισαν «Baby Yoda», το στούντιο δεν το ονομάτισε επίσημα μέχρι τη δεύτερη σεζόν.","wiki_en":"The Mandalorian"},{"name":"The Last of Us","emoji":"🍄","meta":["δράμα, τρόμου","από το 2023","ΗΠΑ"],"description":"Μεταφορά του βιντεοπαιχνιδιού: ο λαθρέμπορος Τζόελ αναλαμβάνει να περάσει μέσα από μια Αμερική ρημαγμένη από πανδημία μύκητα την έφηβη Έλι, που ίσως κρατά το κλειδί για τη σωτηρία της ανθρωπότητας. Η σειρά δίνει στη σχέση των δύο ηρώων τόσο βάρος όσο και στην επιβίωση.","fact":"Μεγάλο μέρος του σεναρίου το έγραψαν οι δημιουργοί του αρχικού παιχνιδιού, κι έτσι πλοκή και χαρακτήρες πέρασαν σχεδόν αναλλοίωτοι.","wiki_en":"The Last of Us (TV series)"},{"name":"Τσερνόμπιλ","emoji":"☢️","meta":["δράμα, ιστορικό","2019","ΗΠΑ, Ηνωμένο Βασίλειο"],"description":"Μίνι σειρά για την καταστροφή στον πυρηνικό σταθμό του Τσερνόμπιλ το 1986 και τις συνέπειές της για τους εκκαθαριστές, τους επιστήμονες και τους κατοίκους των γειτονικών πόλεων. Οι δημιουργοί ανασύνθεσαν τη σοβιετική καθημερινότητα και το κλίμα της εποχής με εμμονή στη λεπτομέρεια.","fact":"Πολλοί εσωτερικοί χώροι και δρόμοι ξαναχτίστηκαν στη Λιθουανία, όπου σώζεται σοβιετική αρχιτεκτονική παρόμοιου ύφους.","wiki_en":"Chernobyl (miniseries)"},{"name":"The Crown","emoji":"👑","meta":["δράμα, ιστορικό","2016–2023","Ηνωμένο Βασίλειο"],"description":"Η σειρά παρακολουθεί τη ζωή της βασίλισσας Ελισάβετ Β΄ και της οικογένειάς της, από την άνοδό της στον θρόνο στις αρχές του 1950 μέχρι τις πρόσφατες δεκαετίες, δείχνοντας τα παρασκήνια της μοναρχίας πάνω σε μεγάλα ιστορικά γεγονότα. Κάθε λίγες σεζόν οι πρωταγωνιστές αλλάζουν, για να ταιριάζουν στην ηλικία των ηρώων.","fact":"Για ιστορική πιστότητα, κοστούμια και εσωτερικά ανασυνθέτονταν από αρχειακές φωτογραφίες και από αυθεντικά βασιλικά ενδύματα.","wiki_en":"The Crown (TV series)"},{"name":"La Casa de Papel","emoji":"🎭","meta":["δράμα, αστυνομικό","2017–2021","Ισπανία"],"description":"Μια ομάδα ληστών με επικεφαλής τον μυστηριώδη Καθηγητή καταλαμβάνει το Βασιλικό Νομισματοκοπείο της Ισπανίας, για να τυπώσει δισεκατομμύρια ευρώ από μέσα αντί να τα κλέψει. Όλοι παίρνουν ως όνομα μια πόλη, και οι μάσκες αλά Σαλβαδόρ Νταλί έγιναν το σήμα της σειράς.","fact":"Η ισπανική σειρά έγινε από τις πιο πολυπροβεβλημένες μη αγγλόφωνες παραγωγές του Netflix σε όλο τον κόσμο.","wiki_en":"Money Heist"},{"name":"Squid Game","emoji":"🦑","meta":["δράμα, θρίλερ","2021","Νότια Κορέα"],"description":"Εκατοντάδες άνθρωποι βουτηγμένοι στα χρέη δέχονται να πάρουν μέρος σε μια σειρά θανάσιμων παιδικών παιχνιδιών, για ένα τεράστιο χρηματικό έπαθλο. Τον αγώνα παρακολουθούν κρυφά πλούσιοι θεατές, για τους οποίους η απελπισία των άλλων είναι διασκέδαση.","fact":"Όταν βγήκε, έγινε η πιο πολυπροβεβλημένη παραγωγή σε όλη την ιστορία του Netflix.","wiki_en":"Squid Game"},{"name":"Narcos","emoji":"🌿","meta":["δράμα, αστυνομικό","2015–2017","ΗΠΑ"],"description":"Η σειρά ανασυνθέτει την αναμέτρηση των κολομβιανών καρτέλ ναρκωτικών με τους αμερικανούς κυβερνητικούς πράκτορες, με κέντρο την άνοδο και την πτώση του διαβόητου βαρόνου Πάμπλο Εσκομπάρ. Η αφήγηση μπλέκει αρχειακό ντοκιμαντερίστικο υλικό με δραματοποιημένες σκηνές.","fact":"Μέρος της σειράς γυρίστηκε στην ίδια την Κολομβία, και κάποιες τοποθεσίες συνδέονται με αληθινά γεγονότα της ιστορίας του καρτέλ.","wiki_en":"Narcos"},{"name":"Ozark","emoji":"💵","meta":["δράμα, αστυνομικό","2017–2022","ΗΠΑ"],"description":"Ο οικονομικός σύμβουλος Μάρτι Μπερντ αναγκάζεται να μετακομίσει με την οικογένειά του στην παραθεριστική περιοχή Όζαρκ, για να ξεπλένει χρήματα ενός μεξικανικού καρτέλ και να ξεχρεώσει. Η σειρά δείχνει πώς μια φαινομενικά τακτική οικογένεια βουλιάζει σιγά σιγά στο έγκλημα.","fact":"Ο τίτλος παραπέμπει στην πραγματική περιοχή Όζαρκ, στα σύνορα Μιζούρι και Αρκάνσας, όπου εξελίσσεται σχεδόν όλη η δράση.","wiki_en":"Ozark (TV series)"},{"name":"Better Call Saul","emoji":"⚖️","meta":["δράμα, αστυνομικό","2015–2022","ΗΠΑ"],"description":"Το πρίκουελ του «Breaking Bad» διηγείται την ιστορία του δικηγόρου Τζίμι ΜακΓκιλ, που σιγά σιγά μεταμορφώνεται στον πανούργο απατεώνα Σολ Γκούντμαν. Η σειρά δείχνει με κάθε λεπτομέρεια την ηθική κατάρρευση του ήρωα, χρόνια πριν από τα γεγονότα της βασικής σειράς.","fact":"Πολλοί κριτικοί θεωρούν το πρίκουελ ισάξιο, αν όχι δραματουργικά ανώτερο, από το αρχικό «Breaking Bad».","wiki_en":"Better Call Saul"},{"name":"Mad Men","emoji":"🥃","meta":["δράμα","2007–2015","ΗΠΑ"],"description":"Δράμα για τους ανθρώπους μιας διαφημιστικής εταιρείας στη Μάντισον Άβενιου της Νέας Υόρκης στις αρχές του 1960, με κέντρο τον χαρισματικό αλλά κλειστό δημιουργικό διευθυντή Ντον Ντρέιπερ. Η σειρά φημίζεται για τη σχολαστική ανασύνθεση της μόδας, των χώρων και των ηθών της εποχής.","fact":"Κατά τους δημιουργούς, «mad men» ήταν το αργκό παρατσούκλι που έδιναν στον εαυτό τους οι διαφημιστές της Μάντισον Άβενιου.","wiki_en":"Mad Men"},{"name":"House of Cards","emoji":"🃏","meta":["δράμα","2013–2018","ΗΠΑ"],"description":"Ο κυνικός βουλευτής Φρανκ Άντεργουντ, αφού τον προσπερνούν για τη θέση που του είχαν τάξει, ξεκινά ένα αδίστακτο παιχνίδι ίντριγκας για να φτάσει στην κορυφή της αμερικανικής εξουσίας, μιλώντας κάθε τόσο απευθείας στον θεατή. Ήταν από τις πρώτες μεγάλες παραγωγές του Netflix.","fact":"Η αμερικανική εκδοχή είναι ριμέικ βρετανικής μίνι σειράς του 1990, βασισμένης στο μυθιστόρημα του Μάικλ Ντομπς.","wiki_en":"House of Cards (American TV series)"},{"name":"Succession","emoji":"💼","meta":["δράμα, μαύρη κομεντί","2018–2023","ΗΠΑ"],"description":"Σατιρικό δράμα για τον μεγιστάνα των μέσων Λόγκαν Ρόι και τα ενήλικα παιδιά του, που στήνουν ίντριγκες και τρώγονται μεταξύ τους για το δικαίωμα να κληρονομήσουν την παγκόσμια αυτοκρατορία του. Η σειρά σατιρίζει ανελέητα τα ήθη των υπερπλούσιων και τον εταιρικό πόλεμο εξουσίας.","fact":"Το σενάριο εμπνέεται σε μεγάλο βαθμό από αληθινές δυναστείες των μέσων, αν και οι δημιουργοί τόνιζαν πάντα ότι οι ήρωες είναι φανταστικοί.","wiki_en":"Succession (TV series)"},{"name":"The White Lotus","emoji":"🌺","meta":["μαύρη κομεντί, δράμα","από το 2021","ΗΠΑ"],"description":"Ανθολογία που κάθε σεζόν μεταφέρεται σε ένα άλλο πολυτελές ξενοδοχείο της αλυσίδας White Lotus και παρακολουθεί πελάτες και προσωπικό, με τα κρυμμένα πάθη και τις συγκρούσεις τους να βγαίνουν σιγά σιγά στην επιφάνεια. Από τα πρώτα λεπτά κάθε σεζόν ο θεατής ξέρει ότι κάποιος θα πεθάνει.","fact":"Η πρώτη σεζόν γυρίστηκε στη Χαβάη, σε ξενοδοχείο που λειτουργούσε κανονικά και όπου έμενε και όλο το συνεργείο.","wiki_en":"The White Lotus"},{"name":"Euphoria","emoji":"💊","meta":["δράμα","από το 2019","ΗΠΑ"],"description":"Η σειρά δείχνει τη ζωή μιας παρέας αμερικανών μαθητών λυκείου μέσα από τους εθισμούς, την αναζήτηση ταυτότητας και τον πρώτο έρωτα, με τολμηρά εικαστικά τεχνάσματα και τους μονολόγους της ηρωίδας Ρου. Το θέμα της εξάρτησης από ναρκωτικά μπαίνει χωρίς εξωραϊσμούς.","fact":"Το έντονο μακιγιάζ με γκλίτερ που φορούν οι ηρωίδες γέννησε μια ξεχωριστή τάση στη μόδα, με δικό της όνομα.","wiki_en":"Euphoria (American TV series)"},{"name":"Wednesday","emoji":"🖤","meta":["κομεντί, τρόμου","από το 2022","ΗΠΑ"],"description":"Η Γουένσντεϊ, κόρη της οικογένειας Άνταμς, μπαίνει στη σκοτεινή ακαδημία για απόβλητους Nevermore, όπου πρέπει να λύσει ένα υπερφυσικό μυστήριο, να κάνει τους πρώτους φίλους της ζωής της και να τα βρει με τις δικές της παραφυσικές ικανότητες. Γοτθική αισθητική με εφηβική κομεντί.","fact":"Τον χορό που κάνει η ηρωίδα στον σχολικό χορό τον επινόησε σε μεγάλο βαθμό η ίδια η ηθοποιός, και έγινε viral σε όλο τον κόσμο.","wiki_en":"Wednesday (TV series)"},{"name":"Bridgerton","emoji":"💍","meta":["δράμα, ρομαντικό","από το 2020","ΗΠΑ"],"description":"Μεταφορά των μυθιστορημάτων της Τζούλια Κουίν για την πολυμελή οικογένεια Μπρίτζερτον στην υψηλή κοινωνία του Λονδίνου της Αντιβασιλείας, με κάθε σεζόν να στήνεται γύρω από τον έρωτα ενός από τα αδέλφια. Τα σκάνδαλα του κόσμου τους παρακολουθεί αόρατη η ανώνυμη κυρία Ουίσλνταουν.","fact":"Σε αντίθεση με τα κλασικά δράματα εποχής, η σειρά έχει εμφατικά πολυφυλετικό καστ, επιλογή που συζητήθηκε πολύ.","wiki_en":"Bridgerton"},{"name":"The Queen's Gambit","emoji":"♟️","meta":["δράμα","2020","ΗΠΑ"],"description":"Μίνι σειρά για τη νεαρή ιδιοφυΐα του σκακιού Μπεθ Χάρμον, που μεγαλώνει σε ορφανοτροφείο, παλεύει με την εξάρτηση από τα ηρεμιστικά και σιγά σιγά ανεβαίνει στην κορυφή ενός κατά βάση αντρικού κόσμου. Οι παρτίδες σκακιού παίζονται με την αγωνία αθλητικών αναμετρήσεων.","fact":"Μετά την προβολή της, το ενδιαφέρον για το σκάκι εκτοξεύτηκε παγκοσμίως, από τις πωλήσεις σκακιέρων ως τις εγγραφές σε μαθήματα.","wiki_en":"The Queen's Gambit (miniseries)"},{"name":"Ted Lasso","emoji":"⚽","meta":["κομεντί, αθλητικό","2020–2023","ΗΠΑ"],"description":"Ένας αμερικανός προπονητής του αμερικανικού ποδοσφαίρου, χωρίς καμία εμπειρία από το ευρωπαϊκό, αναλαμβάνει απρόσμενα μια αγγλική ομάδα και κερδίζει τους δυσπίστους παίκτες με ακλόνητη αισιοδοξία και καλοσύνη. Η σειρά ξεχώρισε για τον ζεστό, σχεδόν θεραπευτικό τόνο της.","fact":"Ο Τεντ Λάσο εμφανίστηκε πρώτη φορά χρόνια πριν από τη σειρά, σε διαφημιστικά σποτ του NBC για την αγγλική Πρέμιερ Λιγκ.","wiki_en":"Ted Lasso"},{"name":"The Bear","emoji":"🐻","meta":["δράμα, κομεντί","από το 2022","ΗΠΑ"],"description":"Ένας νέος σεφ της υψηλής γαστρονομίας επιστρέφει στο Σικάγο για να αναλάβει το οικογενειακό σνακ μπαρ μετά τον θάνατο του αδελφού του, και προσπαθεί να βάλει σε τάξη το χάος της κουζίνας και των δικών του τραυμάτων. Ξεχωρίζει για τις σφιχτές, σχεδόν ντοκιμαντερίστικες σκηνές στην κουζίνα.","fact":"Ένα από τα πιο συζητημένα επεισόδια είναι φτιαγμένο σαν ένα αδιάκοπο πλάνο, κάτι που εντείνει στο έπακρο την αίσθηση του χάους.","wiki_en":"The Bear (TV series)"},{"name":"Severance","emoji":"🧠","meta":["επιστημονική φαντασία, θρίλερ","από το 2022","ΗΠΑ"],"description":"Οι εργαζόμενοι μιας μυστηριώδους εταιρείας περνούν τη διαδικασία του «διαχωρισμού», που κυριολεκτικά σπάει τη συνείδησή τους σε εργασιακή και καθημερινή προσωπικότητα, που δεν θυμούνται η μία την άλλη. Μια αγωνιώδης δυστοπία για την ταυτότητα και τον έλεγχο της εταιρείας πάνω στη ζωή.","fact":"Οι εξωτερικοί χώροι και το λόμπι της εταιρείας γυρίστηκαν σε αληθινό μοντερνιστικό κτίριο, παλιά ερευνητικά εργαστήρια στο Νιου Τζέρσεϊ.","wiki_en":"Severance (TV series)"},{"name":"The Boys","emoji":"🦸","meta":["επιστημονική φαντασία, μαύρη κομεντί","από το 2019","ΗΠΑ"],"description":"Σε έναν κόσμο όπου οι υπερήρωες είναι προϊόν μιας εταιρείας που βγάζει λεφτά από τη λατρεία τους, μια ομάδα απλών ανθρώπων παίρνει εκδίκηση από τους διεφθαρμένους και βάναυσους «ήρωες» για το κακό που έχουν κάνει. Ανελέητη παρωδία του υπερηρωικού είδους και της βιομηχανίας των ειδώλων.","fact":"Πολλοί ήρωες της σειράς είναι αναγνωρίσιμες παρωδίες διάσημων υπερηρώων των κόμικς.","wiki_en":"The Boys (TV series)"},{"name":"House of the Dragon","emoji":"🐲","meta":["φαντασίας, δράμα","από το 2022","ΗΠΑ"],"description":"Το πρίκουελ του «Game of Thrones» τοποθετείται σχεδόν διακόσια χρόνια πριν και διηγείται τον αιματηρό εμφύλιο πόλεμο για τον θρόνο μέσα στον οίκο Ταργκάριεν, γνωστό ως «Χορός των Δράκων». Οι δράκοι εδώ είναι πολύ περισσότεροι, και ο καθένας έχει τον δικό του Ταργκάριεν αναβάτη.","fact":"Βασίστηκε στο βιβλίο του Τζορτζ Μάρτιν «Φωτιά και Αίμα», γραμμένο σαν ψευδοϊστορικό χρονικό της δυναστείας των Ταργκάριεν.","wiki_en":"House of the Dragon"},{"name":"Loki","emoji":"⚡","meta":["επιστημονική φαντασία","από το 2021","ΗΠΑ"],"description":"Μετά τα γεγονότα των ταινιών των Εκδικητών, ο θεός της απάτης Λόκι καταλήγει στη μυστηριώδη Υπηρεσία Χρονικών Παραλλαγών, που φυλάει την ακεραιότητα του χρόνου, και αναγκάζεται να συνεργαστεί με τους πράκτορές της. Ήταν η πρώτη σειρά της Marvel που έπιασε σοβαρά το πολυσύμπαν.","fact":"Ο Τομ Χίντλστον παίζει τον Λόκι από τον πρώτο «Θορ» του 2011, έναν από τους πιο μακρόβιους ρόλους του σύμπαντος της Marvel.","wiki_en":"Loki (TV series)"},{"name":"Arcane","emoji":"💜","meta":["κινούμενα σχέδια, φαντασίας","2021–2024","ΗΠΑ"],"description":"Σειρά κινουμένων σχεδίων στο σύμπαν του παιχνιδιού League of Legends, για δύο αδελφές από το Πίλτοβερ και το Ζάουν, τη πλούσια και τη φτωχή πλευρά της ίδιας πόλης, που οι δρόμοι τους χωρίζουν μετά από μια τραγωδία των παιδικών τους χρόνων. Ξεχωρίζει για το σχεδόν ζωγραφικό ύφος της.","fact":"Η παραγωγή κράτησε περίπου έξι χρόνια και υπήρξε από τις πιο ακριβές και τεχνικά απαιτητικές δουλειές κινουμένων σχεδίων της εποχής της.","wiki_en":"Arcane (TV series)"},{"name":"Avatar: The Last Airbender","emoji":"🌊","meta":["κινούμενα σχέδια, φαντασίας","2005–2008","ΗΠΑ"],"description":"Σειρά κινουμένων σχεδίων για έναν κόσμο χωρισμένο σε τέσσερις λαούς, που ο καθένας δαμάζει ένα από τα στοιχεία, και για τον νεαρό Άβαταρ Ανγκ, που πρέπει να μάθει και τα τέσσερα και να σταματήσει τον πόλεμο του Έθνους της Φωτιάς. Ανατολίτικη αισθητική με δουλεμένη, ενήλικη πλοκή.","fact":"Οι δημιουργοί συμβουλεύτηκαν δασκάλους πολεμικών τεχνών, ώστε κάθε στιλ δαμασμού στοιχείου να βασίζεται σε αληθινή τεχνική.","wiki_en":"Avatar: The Last Airbender"},{"name":"Μπομπ Σφουγγαράκης","emoji":"🧽","meta":["κινούμενα σχέδια, κομεντί","από το 1999","ΗΠΑ"],"description":"Σειρά κινουμένων σχεδίων για ένα ακατάβλητο κίτρινο θαλασσινό σφουγγάρι με τετράγωνο παντελόνι, που ζει στην υποβρύχια πόλη Μπικίνι Μπότομ, δουλεύει μάγειρας στο σνακ μπαρ Krusty Krab και μπλέκει διαρκώς σε παράλογες καταστάσεις με τους φίλους του. Έγινε παγκόσμιο σήμα των κινουμένων σχεδίων.","fact":"Ο δημιουργός Στίβεν Χίλενμπεργκ δούλευε θαλάσσιος βιολόγος πριν στραφεί στην κινούμενη εικόνα, κάτι που φαίνεται στο υποβρύχιο σκηνικό.","wiki_en":"SpongeBob SquarePants"},{"name":"Naruto","emoji":"🍥","meta":["άνιμε","2002–2007","Ιαπωνία"],"description":"Άνιμε για τον νεαρό νίντζα Ναρούτο Ουζουμάκι, που ονειρεύεται να γίνει ο πιο δυνατός αρχηγός του χωριού του, παρότι μέσα του είναι σφραγισμένο ένα πανίσχυρο δαιμονικό πνεύμα αλεπούς. Η σειρά παρακολουθεί την ενηλικίωσή του, τις φιλίες και τους ανταγωνισμούς με τους συντρόφους του.","fact":"Ναρούτο λέγονται και οι σπειροειδείς ροδέλες από πάστα ψαριού που μπαίνουν στο ράμεν, και το ράμεν είναι το αγαπημένο φαγητό του ήρωα.","wiki_en":"Naruto"},{"name":"One Piece","emoji":"🏴‍☠️","meta":["άνιμε","από το 1999","Ιαπωνία"],"description":"Άνιμε για τον νεαρό πειρατή Μόνκι Ντι Λούφι, που από ένα διαβολικό φρούτο που έφαγε κατά λάθος απέκτησε λαστιχένιο σώμα και ξεκίνησε με το πλήρωμά του να βρει τον θρυλικό θησαυρό One Piece. Μια από τις πιο μακρόβιες και εμπορικά επιτυχημένες σειρές άνιμε όλων των εποχών.","fact":"Το μάνγκα από το οποίο προέρχεται αναγνωρίζεται επίσημα ως η πιο πολυπουλημένη σειρά κόμικς ενός δημιουργού στην ιστορία.","wiki_en":"One Piece"},{"name":"Attack on Titan","emoji":"🗡️","meta":["άνιμε","2013–2023","Ιαπωνία"],"description":"Η ανθρωπότητα κρύβεται πίσω από γιγάντια τείχη από τους ανθρωπόμορφους Τιτάνες που τρώνε ανθρώπους, ώσπου μια μέρα το τείχος γκρεμίζεται από το χτύπημα του Κολοσσιαίου Τιτάνα. Η σειρά αποκαλύπτει σιγά σιγά το πολύπλοκο πολιτικό και ιστορικό βάθος της σύγκρουσης.","fact":"Κατά τον δημιουργό του μάνγκα Χατζίμε Ισαγιάμα, η ιδέα γεννήθηκε εν μέρει από τη δουλειά του σε ίντερνετ καφέ και τους απρόβλεπτους πελάτες.","wiki_en":"Attack on Titan"},{"name":"Death Note","emoji":"📓","meta":["άνιμε","2006–2007","Ιαπωνία"],"description":"Ο μαθητής λυκείου Λάιτ Γιαγκάμι βρίσκει ένα τετράδιο που σκοτώνει όποιον γραφτεί μέσα του και αποφασίζει να καθαρίσει τον κόσμο από τους εγκληματίες, γινόμενος ο μυστηριώδης τιμωρός με το προσωνύμιο Κίρα. Εναντίον του ξεκινά έρευνα ο ιδιοφυής ντετέκτιβ L.","fact":"Οι κανόνες χρήσης του τετραδίου είναι τόσο λεπτομερείς, που οι φαν ξεψαχνίζουν χρόνια τα λογικά τους κενά και τις αντιφάσεις.","wiki_en":"Death Note"},{"name":"Pokémon","emoji":"⚡","meta":["άνιμε","από το 1997","Ιαπωνία"],"description":"Άνιμε για τον νεαρό εκπαιδευτή Ας Κέτσαμ και το ηλεκτρικό του Πόκεμον, τον Πίκατσου, που γυρίζουν διάφορες περιοχές, πιάνουν και εκπαιδεύουν άλλα Πόκεμον και μπαίνουν σε τουρνουά για να γίνουν πρωταθλητές. Βασίστηκε στα λατρεμένα βιντεοπαιχνίδια και γέννησε μια από τις μεγαλύτερες φραντσάιζ στον κόσμο.","fact":"Ένα επεισόδιο του 1997 προκάλεσε κρίσεις σε ιάπωνες θεατές με τα γρήγορα αναβοσβήνοντα καρέ και δεν ξαναπροβλήθηκε ποτέ.","wiki_en":"Pokémon (TV series)"},{"name":"Sailor Moon","emoji":"🌙","meta":["άνιμε","1992–1997","Ιαπωνία"],"description":"Η απλή ιαπωνέζα μαθήτρια Ουσάγκι Τσουκίνο μεταμορφώνεται στην πολεμίστρια με τη ναυτική στολή Σέιλορ Μουν και μαζί με τις άλλες πολεμίστριες προστατεύει τη Γη από σκοτεινές δυνάμεις. Ένα από τα πρώτα άνιμε με μάγισσες πολεμίστριες που έγινε μαζικά δημοφιλές έξω από την Ιαπωνία.","fact":"Η σειρά έπαιξε καθοριστικό ρόλο στη διάδοση του είδους μάχο σότζο, και του άνιμε γενικά, στο δυτικό κοινό της δεκαετίας του 1990.","wiki_en":"Sailor Moon (TV series)"},{"name":"Mr. Bean","emoji":"🧸","meta":["κομεντί","1990–1995","Ηνωμένο Βασίλειο"],"description":"Κομική σειρά σχεδόν χωρίς διαλόγους για τον αστείο και εκκεντρικό Άγγλο κύριο Μπιν, που οι πιο απλές καθημερινές δουλειές του καταλήγουν πάντα σε αλυσίδα παράλογων παρεξηγήσεων. Το σωματικό, οπτικό χιούμορ την έκανε κατανοητή σε κάθε γλώσσα.","fact":"Με ελάχιστα λόγια, η σειρά ταξίδεψε σε όλο τον κόσμο σχεδόν χωρίς προσαρμογή και μεταγλώττιση.","wiki_en":"Mr. Bean"},{"name":"Doctor Who","emoji":"📞","meta":["επιστημονική φαντασία","από το 1963","Ηνωμένο Βασίλειο"],"description":"Πολυετής βρετανική σειρά για τον Δόκτορα, ένα εξωγήινο ον που ταξιδεύει στον χρόνο και τον χώρο με μια χρονομηχανή σε σχήμα μπλε αστυνομικού θαλάμου και κάθε τόσο «αναγεννιέται» σε νέο σώμα. Μια από τις πιο μακρόβιες σειρές επιστημονικής φαντασίας στην τηλεόραση.","fact":"Η ικανότητα του Δόκτορα να «αναγεννιέται» επινοήθηκε εξαρχής ως σεναριακό τέχνασμα, για να αλλάζει πρωταγωνιστής χωρίς να σταματά η σειρά.","wiki_en":"Doctor Who"},{"name":"Charmed","emoji":"🔮","meta":["φαντασίας, δράμα","1998–2006","ΗΠΑ"],"description":"Οι τρεις αδελφές Χάλιγουελ ανακαλύπτουν ότι κατάγονται από ισχυρή γενιά μαγισσών και πρέπει να χρησιμοποιήσουν την κληρονομική μαγεία τους για να προστατεύουν τους αθώους από δαίμονες και σκοτεινές δυνάμεις. Οικογενειακό δράμα με μια μαγική αναμέτρηση κάθε βδομάδα.","fact":"Έγινε μια από τις πιο μακρόβιες σειρές φαντασίας με γυναίκες πρωταγωνίστριες στην αμερικανική τηλεόραση.","wiki_en":"Charmed"},{"name":"Baywatch","emoji":"🏖️","meta":["δράμα, δράσης","1989–2001","ΗΠΑ"],"description":"Σειρά για την καθημερινότητα των ναυαγοσωστών στις παραλίες του Μαλιμπού, που δεν βγάζουν μόνο λουόμενους από το νερό αλλά ξεμπερδεύουν και προσωπικά δράματα και εγκληματικές υποθέσεις. Στη δεκαετία του 1990 θεωρούνταν από τις πιο πολυπροβεβλημένες σειρές στον κόσμο.","fact":"Στην ακμή της, κατά διάφορες εκτιμήσεις, τη σειρά έβλεπαν κάθε εβδομάδα πάνω από ένα δισεκατομμύριο θεατές σε όλο τον κόσμο.","wiki_en":"Baywatch"},{"name":"ALF","emoji":"👽","meta":["κομεντί","1986–1990","ΗΠΑ"],"description":"Μετά τη συντριβή του εξωγήινου σκάφους του στη Γη, ένα χνουδωτό πλάσμα με το όνομα ALF εγκαθίσταται στο σπίτι μιας απλής αμερικανικής οικογένειας, κρύβεται από τις αρχές και σπέρνει διαρκώς χάος. Ο ALF είναι κούκλα-ανιματρόνικ, που τη δουλεύει μαριονετίστας από κάτω.","fact":"Λόγω του μηχανισμού της κούκλας, ο ALF σπάνια φαινόταν ολόσωμος, και τα σκηνικά υψώθηκαν από το πάτωμα για να δουλεύουν οι μαριονετίστες.","wiki_en":"ALF (TV series)"},{"name":"Σάντα Μπάρμπαρα","emoji":"🌴","meta":["σαπουνόπερα","1984–1993","ΗΠΑ"],"description":"Πολυετής αμερικανική σαπουνόπερα για τη ζωή, τους έρωτες και τις ίντριγκες μερικών πλούσιων οικογενειών στην καλιφορνέζικη πόλη Σάντα Μπάρμπαρα. Πουλήθηκε παντού και έγινε μια από τις πιο δημοφιλείς αμερικανικές σαπουνόπερες στο εξωτερικό τη δεκαετία του 1990.","fact":"Κράτησε σχεδόν δέκα χρόνια και αριθμεί πάνω από δύο χιλιάδες επεισόδια, ένα περίπου για κάθε εργάσιμη μέρα.","wiki_en":"Santa Barbara (TV series)"},{"name":"The Mentalist","emoji":"🎯","meta":["αστυνομικό, δράμα","2008–2015","ΗΠΑ"],"description":"Ο Πάτρικ Τζέιν, πρώην ψευτομέντιουμ, βοηθά το γραφείο ερευνών της Καλιφόρνιας να εξιχνιάζει εγκλήματα, χωρίς υπερφυσικές ικανότητες αλλά με οξεία παρατηρητικότητα και γνώση της ψυχολογίας. Παράλληλα κυνηγά μόνος τον κατά συρροή δολοφόνο που αφάνισε την οικογένειά του.","fact":"Ο ήρωας βασίστηκε σε μεγάλο βαθμό σε αληθινούς μενταλίστες και «ψυχρούς αναγνώστες», που δημιουργούν την ψευδαίσθηση της τηλεπάθειας χωρίς τίποτα μυστικιστικό.","wiki_en":"The Mentalist"},{"name":"Suits","emoji":"👔","meta":["δράμα","2011–2019","ΗΠΑ"],"description":"Ένας ταλαντούχος νέος χωρίς πτυχίο νομικής πιάνει δουλειά σε φημισμένο δικηγορικό γραφείο της Νέας Υόρκης, χάρη σε απίστευτη μνήμη και πονηριά, κρύβοντας την απάτη από συναδέλφους και πελάτες. Δικαστικό δράμα δεμένο με μια ιστορία φιλίας και μαθητείας.","fact":"Ο αγγλικός τίτλος παίζει με δύο πράγματα μαζί: τα κοστούμια των δικηγόρων και τις αγωγές που χειρίζονται.","wiki_en":"Suits (American TV series)"},{"name":"Lucifer","emoji":"😈","meta":["φαντασίας, αστυνομικό","2016–2021","ΗΠΑ"],"description":"Ο Διάβολος κουράζεται να κυβερνά αιώνια την Κόλαση και μετακομίζει στο Λος Άντζελες, όπου ανοίγει νυχτερινό κλαμπ και παράλληλα βοηθά την αστυνομία να λύνει φόνους, χάρη στο χάρισμά του να κάνει τους ανθρώπους να ομολογούν τις επιθυμίες τους. Βασίζεται σε ήρωα των κόμικς της Vertigo.","fact":"Ο Λούσιφερ πρωτοεμφανίστηκε στα κόμικς «Sandman» του Νιλ Γκέιμαν, πριν αποκτήσει δική του σειρά κόμικς και τηλεοπτική σειρά.","wiki_en":"Lucifer (TV series)"},{"name":"Supernatural","emoji":"🔥","meta":["φαντασίας, τρόμου","2005–2020","ΗΠΑ"],"description":"Τα αδέλφια Σαμ και Ντιν Γουίντσεστερ διασχίζουν την Αμερική με μια παλιά Chevrolet Impala, κυνηγώντας δαίμονες, φαντάσματα και κάθε λογής κακά πνεύματα, και καταλήγουν στο κέντρο της σύγκρουσης Παραδείσου και Κόλασης. Από τις πιο μακρόβιες σειρές τρόμου και φαντασίας της αμερικανικής τηλεόρασης.","fact":"Η μαύρη Chevrolet Impala του 1967 που οδηγούν οι ήρωες έγινε τόσο αναγνωρίσιμο σύμβολο της σειράς όσο και τα δύο αδέλφια.","wiki_en":"Supernatural (American TV series)"},{"name":"The Vampire Diaries","emoji":"🧛","meta":["φαντασίας, δράμα","2009–2017","ΗΠΑ"],"description":"Η μαθήτρια Έλενα Γκίλμπερτ ερωτεύεται τον ευγενικό βαμπίρ Στέφαν Σαλβατόρε, όμως σύντομα εμφανίζεται στη ζωή της ο απρόβλεπτος αδελφός του Ντέιμον, και οι δύο αδελφοί μπλέκουν σε έναν αιώνιο ανταγωνισμό για την καρδιά της. Όλα γίνονται στη μικρή πόλη Μίστικ Φολς, γεμάτη υπερφυσικά όντα.","fact":"Τα γυρίσματα έγιναν στην αληθινή κωμόπολη Κόβινγκτον της Τζόρτζια, που έγινε δημοφιλής προορισμός προσκυνήματος για τους φαν.","wiki_en":"The Vampire Diaries"},{"name":"Westworld","emoji":"🤖","meta":["επιστημονική φαντασία, δράμα","2016–2022","ΗΠΑ"],"description":"Ένα τεράστιο θεματικό πάρκο κατοικείται από ανθρωποειδή ανδροειδή, που κάθε μέρα παίζουν σενάρια γουέστερν για πλούσιους επισκέπτες, ώσπου μέσα στον προγραμματισμό τους αρχίζουν να διαφαίνονται σημάδια αληθινής συνείδησης. Η σειρά θέτει ερωτήματα για τη συνείδηση και την ελεύθερη βούληση.","fact":"Βασίζεται στην ομώνυμη ταινία επιστημονικής φαντασίας του 1973, από τις πρώτες του Χόλιγουντ με ψηφιακά κινούμενη εικόνα.","wiki_en":"Westworld (TV series)"},{"name":"Fargo","emoji":"❄️","meta":["μαύρη κομεντί, αστυνομικό","από το 2014","ΗΠΑ"],"description":"Ανθολογία εμπνευσμένη από την ομώνυμη ταινία των αδελφών Κοέν, με κάθε σεζόν να διηγείται μια ξεχωριστή ιστορία παράλογων και αιματηρών εγκλημάτων στα χιονισμένα τοπία του αμερικανικού Μεσοδυτικού. Κρατά το σήμα κατατεθέν των Κοέν: μαύρο χιούμορ και ξαφνική βία.","fact":"Παρότι είναι ανθολογία με νέους ήρωες κάθε σεζόν, κάποιες μικρές λεπτομέρειες της πλοκής συνδέουν διακριτικά όλες τις σεζόν μεταξύ τους.","wiki_en":"Fargo (TV series)"},{"name":"Mr. Robot","emoji":"💻","meta":["δράμα, θρίλερ","2015–2019","ΗΠΑ"],"description":"Ένας ταλαντούχος αλλά ψυχικά εύθραυστος προγραμματιστής και χάκερ περνά τις νύχτες του σε μια υπόγεια ομάδα αναρχικών, που σχεδιάζει να σβήσει τα αρχεία χρέους της μεγαλύτερης εταιρείας του κόσμου. Ξεχωρίζει για την ακριβή απόδοση του αληθινού χακαρίσματος και την ιδιαίτερη φωτογραφία.","fact":"Ο δημιουργός Σαμ Εσμέιλ ασχολείται με τον προγραμματισμό από έφηβος και κρατούσε στα γυρίσματα συμβούλους κυβερνοασφάλειας για πιστότητα.","wiki_en":"Mr. Robot"},{"name":"Brooklyn Nine-Nine","emoji":"👮","meta":["σιτκόμ","2013–2021","ΗΠΑ"],"description":"Κομική σειρά για την καθημερινότητα των εκκεντρικών ντετέκτιβ του 99ου αστυνομικού τμήματος του Μπρούκλιν, με επικεφαλής τον αυστηρό αλλά δίκαιο αστυνόμο Ρέιμοντ Χολτ. Οι αστυνομικές έρευνες πάνε μαζί με ατέλειωτες φάρσες και πειράγματα μεταξύ των συνεργατών.","fact":"Ο αστυνόμος Χολτ ήταν από τους πρώτους ανοιχτά ομοφυλόφιλους μαύρους πρωταγωνιστές κομικής σειράς στην αμερικανική τηλεόραση.","wiki_en":"Brooklyn Nine-Nine"},{"name":"Seinfeld","emoji":"🥨","meta":["σιτκόμ","1989–1998","ΗΠΑ"],"description":"Σιτκόμ για τον νεοϋορκέζο κομίκο Τζέρι Σάινφελντ και τρεις παράξενους φίλους του, με επεισόδια που στήνονται γύρω από εντελώς καθημερινές ασημαντότητες και παράλογες μικροδιαφορές. Τη χαρακτήριζαν αστειευόμενοι «η σειρά για το τίποτα», αφού δεν είχε συνεχόμενη πλοκή.","fact":"Το φινάλε του 1998 μάζεψε δεκάδες εκατομμύρια Αμερικανούς και έγινε ένα από τα πιο πολυπαρακολουθημένα στην ιστορία της τηλεόρασης.","wiki_en":"Seinfeld"},{"name":"Μπριγάδα","emoji":"🔫","meta":["δράμα, αστυνομικό","2002","Ρωσία"],"description":"Τέσσερις φίλοι από τα παιδικά τους χρόνια, στη Μόσχα της δεκαετίας του 1990, μετατρέπονται σιγά σιγά από απλά παιδιά σε αρχηγούς μιας μεγάλης εγκληματικής συμμορίας. Η σειρά παρακολουθεί την άνοδο και την αναπόφευκτη πτώση τους πάνω σε μια ταραγμένη εποχή.","fact":"Ο ηθοποιός Σεργκέι Μπεζρούκοφ, που έπαιξε τον αρχηγό της συμμορίας Σάσα Μπέλι, ταυτίστηκε για χρόνια με αυτόν τον ρόλο.","wiki_en":"Brigada"},{"name":"Δεκαεπτά Στιγμές της Άνοιξης","emoji":"🕵️","meta":["δράμα, κατασκοπικό","1973","ΕΣΣΔ"],"description":"Ο σοβιετικός πράκτορας Μαξίμ Ισάγιεφ, που δρα μέσα στη ναζιστική Γερμανία με το όνομα του σταντάρτενφύρερ Στίρλιτς, προσπαθεί να εμποδίσει χωριστές διαπραγματεύσεις των Γερμανών με τους δυτικούς συμμάχους τους τελευταίους μήνες του πολέμου. Από τις πιο λατρεμένες σοβιετικές σειρές.","fact":"Φράσεις και σκηνές της σειράς μπήκαν τόσο βαθιά στην κουλτούρα, που γέννησαν ένα ολόκληρο είδος ανεκδότων για τον Στίρλιτς.","wiki_en":"Seventeen Moments of Spring"},{"name":"Ο Τόπος Συνάντησης Δεν Αλλάζει","emoji":"🚔","meta":["αστυνομικό, δράμα","1979","ΕΣΣΔ"],"description":"Μεταφορά του μυθιστορήματος των αδελφών Βάινερ για τη δίωξη εγκλήματος της Μόσχας τα πρώτα μεταπολεμικά χρόνια, όπου ο πεπειραμένος αστυνομικός Γκλεμπ Ζεγκλόφ και ο νεαρός Βλαντίμιρ Σαράποφ διαφωνούν για τις μεθόδους καταπολέμησης του εγκλήματος. Θεωρείται από τα καλύτερα σοβιετικά αστυνομικά.","fact":"Ο ρόλος του Γκλεμπ Ζεγκλόφ, τον οποίο έπαιξε ο Βλαντίμιρ Βισότσκι, ήταν από τις τελευταίες μεγάλες δουλειές του ηθοποιού πριν τον θάνατό του.","wiki_en":"The Meeting Place Cannot Be Changed"},{"name":"Η Εκκαθάριση","emoji":"🕶️","meta":["αστυνομικό, δράμα","2007","Ρωσία, Ουκρανία"],"description":"Η δράση τοποθετείται στη μεταπολεμική Οδησσό του 1946, όπου οι άνδρες της δίωξης εγκλήματος προσπαθούν να αντιμετωπίσουν το όργιο της συμμοριτοκρατίας, με επικεφαλής έναν μυστηριώδη αρχιεγκληματία με το παρατσούκλι Ακαδημαϊκός. Η σειρά ξαναζωντανεύει το χρώμα και τη λαλιά της μεταπολεμικής Οδησσού.","fact":"Η διάλεκτος της Οδησσού και οι χαρακτηριστικές εκφράσεις των ηρώων έγιναν γρήγορα παροιμιώδεις πολύ πιο πέρα από την πόλη.","wiki_en":"Liquidation (TV series)","wiki_ru":"Ликвидация (телесериал)"},{"name":"Οι Δρόμοι με τα Σπασμένα Φανάρια","emoji":"🌃","meta":["αστυνομικό","από το 1997","Ρωσία"],"description":"Μια από τις πρώτες και πιο μακρόβιες ρωσικές αστυνομικές σειρές, για την καθημερινότητα των αστυνομικών της δίωξης εγκλήματος της Πετρούπολης, που σε κάθε επεισόδιο ερευνούν νέα υπόθεση. Ξεσήκωσε ένα ολόκληρο κύμα παρόμοιων εγχώριων αστυνομικών σειρών.","fact":"Βασίστηκε στα βιβλία του Αντρέι Κιβίνοφ, που είχε υπηρετήσει ο ίδιος στη δίωξη εγκλήματος της Πετρούπολης.","wiki_en":"Streets of Broken Lights"},{"name":"Οι Ειδικευόμενοι","emoji":"🩺","meta":["σιτκόμ","2010–2016","Ρωσία"],"description":"Κομική σειρά για την καθημερινότητα των νέων ειδικευόμενων γιατρών ενός νοσοκομείου της Μόσχας, υπό τον καυστικό και απαιτητικό δόκτορα Μπίκοφ. Το φορμά πατάει σε μεγάλο βαθμό στα δημοφιλή αμερικανικά ιατρικά σιτκόμ, προσαρμοσμένο στη ρωσική πραγματικότητα.","fact":"Τον καυστικό δόκτορα Μπίκοφ έπαιξε ο Ιβάν Οχλομπίστιν, γνωστός ως τότε περισσότερο ως ηθοποιός του σινεμά δημιουργών και σεναριογράφος.","wiki_en":"Interny (TV series)","wiki_ru":"Интерны"},{"name":"Η Κουζίνα","emoji":"🍳","meta":["σιτκόμ","2012–2016","Ρωσία"],"description":"Σιτκόμ για τους μάγειρες και το προσωπικό ενός ακριβού εστιατορίου, όπου ένας ταλαντούχος αλλά άπειρος νέος μάγειρας προσπαθεί να ανοίξει δρόμο υπό τις εντολές ενός ευέξαπτου και απαιτητικού σεφ. Η σειρά γέννησε αρκετές ταινίες συνέχειες και σπιν οφ.","fact":"Τον ευέξαπτο σεφ Βίκτορ Μπαρίνοφ έπαιξε ο Ντμίτρι Ναζάροφ, και αυτή η φιγούρα έμεινε η πιο αναγνωρίσιμη της σειράς.","wiki_en":"Kitchen (Russian TV series)","wiki_ru":"Кухня (телесериал)"},{"name":"Η Σχολή","emoji":"🎓","meta":["σιτκόμ","2007–2011","Ρωσία"],"description":"Νεανικό σιτκόμ για τη ζωή φοιτητών που μένουν στην εστία ενός πανεπιστημίου της Μόσχας, γυρισμένο με πολλές κάμερες και γέλια κοινού εκτός κάδρου. Έγινε μια από τις πιο εμφανείς νεανικές παραγωγές της ρωσικής τηλεόρασης των χρόνων του 2000.","fact":"Η σειρά απέκτησε συνέχεια, «Η Σχολή: Νέα Εστία», όπου η δράση συνεχίστηκε στην ίδια εστία με νέους ήρωες.","wiki_en":"Univer (TV series)","wiki_ru":"Универ (телесериал)"},{"name":"Ο Γυμναστής","emoji":"🏋️","meta":["σιτκόμ","2014–2018","Ρωσία"],"description":"Ένας πρώην αρχιεγκληματίας με το παρατσούκλι Φομά βγαίνει από τη φυλακή και πιάνει δουλειά ως γυμναστής σε ένα απλό σχολείο, φέρνοντας στη στρωτή σχολική ζωή τις συνήθειες του υποκόσμου και το ιδιότυπο χιούμορ του. Τον πρωταγωνιστή έπαιξε ο Ντμίτρι Ναγκίεφ.","fact":"Ο Φομά δεν πάει στο σχολείο από κλίση: χρειάζεται να πλησιάσει την κόρη του παλιού αρχηγού του.","wiki_en":"Fizruk"},{"name":"Οι Συμπέθεροι","emoji":"🍷","meta":["κομεντί","2008–2019","Ουκρανία, Ρωσία"],"description":"Κομική σειρά για δύο οικογένειες συμπεθέρων με διαφορετική οικονομική άνεση και διαφορετική ματιά στη ζωή, που τα παιδιά τους παντρεύτηκαν και οι γονείς αναγκάζονται να τα βρίσκουν και να ανέχονται τους χαρακτήρες τους. Η δράση γίνεται κυρίως στο εξοχικό σπίτι της μιας οικογένειας.","fact":"Γυρίστηκε στην Ουκρανία, και το καστ της ένωσε γνωστούς ηθοποιούς από αρκετές μετασοβιετικές χώρες μαζί.","wiki_en":"Svaty (TV series)","wiki_ru":"Сваты"},{"name":"Τα Κορίτσια του Μπαμπά","emoji":"👧","meta":["σιτκόμ","2007–2013","Ρωσία"],"description":"Σιτκόμ για έναν ψυχολόγο που, μετά τη φυγή της γυναίκας του, μεγαλώνει μόνος πέντε κόρες με εντελώς διαφορετικούς χαρακτήρες και δύσκολα προλαβαίνει τις τρέλες τους. Γυρισμένο με πολλές κάμερες και γέλια κοινού εκτός κάδρου.","fact":"Χρόνια μετά το φινάλε, η σειρά απέκτησε συνέχεια, όπου οι ηρωίδες επέστρεψαν μεγάλες, μαζί με μια νέα γενιά παιδιών.","wiki_en":"Daddy's Daughters"},{"name":"Η Υπέροχη Νταντά μου","emoji":"🧹","meta":["σιτκόμ","2004–2009","Ρωσία"],"description":"Σιτκόμ για μια αφελή αλλά γοητευτική κοπέλα από την επαρχία, που γίνεται απρόσμενα νταντά στο σπίτι ενός πλούσιου παραγωγού της πρωτεύουσας και σιγά σιγά κερδίζει τις καρδιές όλης της οικογένειας. Είναι η ρωσική εκδοχή της αμερικανικής σειράς «The Nanny».","fact":"Η ηρωίδα έρχεται στη Μόσχα από τη Μαριούπολη, και η βαριά προφορά της με τις χαρακτηριστικές πινελιές έγινε το σήμα της σειράς.","wiki_en":"My Fair Nanny","wiki_ru":"Моя прекрасная няня"},{"name":"Μη Γεννηθείς Όμορφη","emoji":"👓","meta":["μελόδραμα","2005–2006","Ρωσία"],"description":"Μελόδραμα για μια σεμνή κοπέλα, όχι ιδιαίτερα ελκυστική με τα μέτρα των περιοδικών μόδας, που πιάνει δουλειά σε οίκο μόδας και, παρά τα πειράγματα των συναδέλφων, κερδίζει σιγά σιγά επιτυχία και αγάπη. Είναι η ρωσική εκδοχή ενός δημοφιλούς λατινοαμερικανικού φορμά για ένα ασχημόπαπο που κατακτά τη μόδα.","fact":"Το αρχικό φορμά, μια κολομβιανή τελενοβέλα, προσαρμόστηκε σε δεκάδες χώρες, και η ρωσική εκδοχή ήταν από τις πιο επιτυχημένες.","wiki_en":"Not Born Beautiful","wiki_ru":"Не родись красивой"},{"name":"Ο Λόγος του Μάγκα: Αίμα στην Άσφαλτο","emoji":"🥊","meta":["δράμα, αστυνομικό","2023","Ρωσία"],"description":"Δράμα για τις εφηβικές συμμορίες του δρόμου στο Καζάν στα τέλη της δεκαετίας του 1980, όπου τα παιδιά από διαφορετικές γειτονιές ζουν με τους σκληρούς άγραφους νόμους του δρόμου. Με την προβολή της, η σειρά άνοιξε ευρεία δημόσια συζήτηση για τη νεανική παραβατικότητα.","fact":"Μετά την πρεμιέρα, σε αρκετές ρωσικές περιφέρειες έγιναν ειδικές συζητήσεις και μέτρα πρόληψης, από φόβο μήπως οι έφηβοι μιμηθούν τους ήρωες.","wiki_en":"The Boy's Word: Blood on the Asphalt"},{"name":"To the Lake","emoji":"❄️","meta":["δράμα, θρίλερ","2019–2022","Ρωσία"],"description":"Μετά το ξέσπασμα ενός θανατηφόρου ιού στη Ρωσία, μια ομάδα τυχαίων συνοδοιπόρων προσπαθεί να διασχίσει με αυτοκίνητο μια ερημωμένη χώρα βυθισμένη στο χάος, για να φτάσει σε ασφαλές καταφύγιο σε μια απομακρυσμένη λίμνη. Βασίζεται στο μυθιστόρημα «Βονγκοζερό» της Γιάνα Βάγκνερ.","fact":"Η ρωσική πρεμιέρα έγινε λίγο πριν ξεσπάσει η πανδημία COVID-19· ο αρχικός ρωσικός τίτλος σημαίνει απλώς «Επιδημία».","wiki_en":"To the Lake"},{"name":"Το Μπαμπαδοπαίδι","emoji":"🚓","meta":["δράμα, αστυνομικό","2014–2019","Ρωσία"],"description":"Ο καλομαθημένος γιος ενός υψηλόβαθμου αξιωματούχου, μετά από ένα σοβαρό παράπτωμα, στέλνεται από τον πατέρα του να υπηρετήσει ως απλός αστυνομικός στη Μόσχα, όπου πρέπει να κερδίσει από το μηδέν τον σεβασμό των συναδέλφων. Αστυνομικές υποθέσεις μαζί με μια ιστορία ενηλικίωσης.","fact":"Μετά τις τηλεοπτικές σεζόν, η ιστορία του ήρωα συνεχίστηκε σε ταινία μεγάλου μήκους που βγήκε στις αίθουσες.","wiki_en":"Mazhor","wiki_ru":"Мажор (телесериал)"},{"name":"Η Μέθοδος","emoji":"🔦","meta":["αστυνομικό, θρίλερ","2015–2018","Ρωσία"],"description":"Ένας εκκεντρικός ανακριτής με ανορθόδοξες, σχεδόν τρομακτικές μεθόδους παίρνει ως συνεργάτιδα μια νέα αστυνομικό, για να κυνηγήσουν μαζί μανιακούς και κατά συρροή δολοφόνους. Η σειρά ξεχωρίζει για τη σκοτεινή ατμόσφαιρα και την ιδιαίτερη φωτογραφία της.","fact":"Τον πρωταγωνιστή έπαιξε ο ηθοποιός Κονσταντίν Χαμπένσκι, και η σειρά συγκρίθηκε στο ύφος με ξένα θρίλερ για κατά συρροή δολοφόνους.","wiki_en":"The Method (TV series)"},{"name":"Ένας Αστυνομικός στη Ρουμπλιόβκα","emoji":"🚨","meta":["κομεντί","2016–2019","Ρωσία"],"description":"Ένας απλοϊκός αστυνομικός της γειτονιάς μετατίθεται σε έναν κλειστό οικισμό υπερπλούσιων στη Ρουμπλιόβκα, όπου πρέπει να βγάζει πέρα τις ιδιοτροπίες των εύπορων κατοίκων, μένοντας κατά βάθος έντιμος και αθώος άνθρωπος. Αστυνομικές υποθέσεις μαζί με κομεντί ηθών.","fact":"Η σειρά απέκτησε συνέχεια σε ταινία μεγάλου μήκους, «Ένας Αστυνομικός στη Ρουμπλιόβκα: Πρωτοχρονιάτικο Χάος», που έγινε επιτυχία στις ρωσικές αίθουσες.","wiki_en":"A Cop from Rublyovka","wiki_ru":"Полицейский с Рублёвки"},{"name":"Λοιπόν, Θα Δεις!","emoji":"🐺","meta":["κινούμενα σχέδια","από το 1969","ΕΣΣΔ"],"description":"Σοβιετική σειρά κινουμένων σχεδίων για έναν αδέξιο αλλά πεισματάρη Λύκο, που σε δεκάδες σύντομα επεισόδια προσπαθεί ανεπιτυχώς να πιάσει έναν χαρούμενο και πολυμήχανο Λαγό. Σχεδόν χωρίς διαλόγους, στηρίζεται στην εκφραστική παντομίμα και σε μουσικά νούμερα.","fact":"Η φράση του Λύκου «Λοιπόν, λαγέ, θα δεις!», που ακούγεται σχεδόν σε κάθε επεισόδιο, έμεινε τόσο, που έδωσε τον τίτλο σε όλη τη σειρά.","wiki_en":"Well, Just You Wait!"},{"name":"Smeshariki","emoji":"🐰","meta":["κινούμενα σχέδια","από το 2004","Ρωσία"],"description":"Ρωσική σειρά κινουμένων σχεδίων για στρουμπουλά, αστεία πλάσματα σαν μπαλάκια, που ζουν σε ένα φανταστικό δάσος και μέσα από απλές καθημερινές ιστορίες μαθαίνουν στους μικρούς θεατές τη φιλία, την επιστήμη και την αλληλοβοήθεια. Πουλήθηκε και προσαρμόστηκε σε πολλές χώρες.","fact":"Στο εξωτερικό προβλήθηκε με άλλους τίτλους, ανάμεσά τους οι εκδοχές GoGoRiki και KikoRiki για διαφορετικές αγορές.","wiki_en":"Smeshariki"},{"name":"Μάσα και Αρκούδος","emoji":"🐻","meta":["κινούμενα σχέδια","από το 2009","Ρωσία"],"description":"Σειρά κινουμένων σχεδίων για την ακούραστη μικρή Μάσα, που με τις ατέλειωτες σκανταλιές της δοκιμάζει διαρκώς την υπομονή του καλού αρκούδου που τη φιλοξενεί και έχει κουραστεί από την ενέργειά της. Από τις πιο επιτυχημένες ρωσικές παραγωγές κινουμένων σχεδίων παγκοσμίως.","fact":"Το επεισόδιο «Η Μάσα και ο χυλός» μάζεψε δισεκατομμύρια προβολές στο YouTube και είναι από τα πιο δημοφιλή βίντεο στην ιστορία της υπηρεσίας.","wiki_en":"Masha and the Bear"},{"name":"Homeland","emoji":"🎯","meta":["πολιτικό θρίλερ","2011–2020","ΗΠΑ"],"description":"Η αξιωματικός της CIA Κάρι Μάθισον, που ζει με διπολική διαταραχή, υποψιάζεται έναν πεζοναύτη μόλις επέστρεψε από την αιχμαλωσία ότι συνεργάζεται με τρομοκράτες. Βασισμένη στην ισραηλινή σειρά «Hatufim», κρατά τον θεατή με την πολιτική ίντριγκα και το παίξιμο της Κλερ Ντέινς.","fact":"Η σειρά βασίζεται στην ισραηλινή παραγωγή «Hatufim» του Γκιντεόν Ραφ.","wiki_en":"Homeland (TV series)"},{"name":"Lie to Me","emoji":"👁️","meta":["αστυνομικό δράμα","2009–2011","ΗΠΑ"],"description":"Ο ψυχολόγος Καλ Λάιτμαν και οι συνεργάτες του εξιχνιάζουν εγκλήματα διαβάζοντας τις μικροεκφράσεις του προσώπου και τη γλώσσα του σώματος. Κάθε επεισόδιο δένει μια υπόθεση με σχεδόν ντοκιμαντερίστικες παρενθέσεις για τη φύση του ψέματος και των συναισθημάτων.","fact":"Ο πρωταγωνιστής βασίστηκε στον αληθινό ψυχολόγο Πολ Έκμαν, που ήταν σύμβουλος των δημιουργών.","wiki_en":"Lie to Me","wiki_ru":"Обмани меня (телесериал, 2009)"},{"name":"Criminal Minds","emoji":"🧠","meta":["αστυνομικό δράμα","2005–2020","ΗΠΑ"],"description":"Οι πράκτορες του τμήματος ανάλυσης συμπεριφοράς του FBI φτιάχνουν ψυχολογικά πορτρέτα κατά συρροή εγκληματιών, για να προβλέψουν την επόμενη κίνησή τους. Η σειρά έκανε το προφάιλινγκ ένα από τα πιο αναγνωρίσιμα θέματα της αστυνομικής τηλεόρασης.","fact":"Το τμήμα ανάλυσης συμπεριφοράς της σειράς είναι αντιγραμμένο από υπαρκτή υπηρεσία του FBI στο Κουάντικο.","wiki_en":"Criminal Minds","wiki_ru":"Мыслить как преступник"},{"name":"Gotham","emoji":"🦇","meta":["αστυνομικό δράμα","2014–2019","ΗΠΑ"],"description":"Η δράση τοποθετείται στο Γκόθαμ Σίτι, χρόνια πριν ο Μπρους Γουέιν γίνει ο Μπάτμαν, όταν ο νέος αστυνομικός Τζέιμς Γκόρντον μόλις αρχίζει να παλεύει με το έγκλημα. Στην πορεία ο θεατής βλέπει τους μελλοντικούς κακούς των κόμικς της DC να παίρνουν τη γνωστή τους μορφή.","fact":"Οι δημιουργοί υποσχέθηκαν να δείξουν τη γέννηση σχεδόν όλων των κλασικών αντιπάλων του Μπάτμαν, πριν καν εμφανιστεί ο ίδιος.","wiki_en":"Gotham (TV series)","wiki_ru":"Готэм (телесериал)"},{"name":"The Flash","emoji":"⚡","meta":["υπερηρωικό","2014–2023","ΗΠΑ"],"description":"Ο εγκληματολόγος Μπάρι Άλεν αποκτά υπερταχύτητα μετά από χτύπημα κεραυνού και γίνεται ο υπερήρωας που προστατεύει το Σέντραλ Σίτι. Η σειρά ανήκει στο λεγόμενο Arrowverse, το κοινό σύμπαν του τηλεοπτικού δικτύου The CW με το «Arrow» και το «Supergirl».","fact":"Τον Μπάρι Άλεν έπαιξε ο Γκραντ Γκάστιν, που πρωτοεμφανίστηκε σε αυτόν τον ρόλο σε επεισόδια του «Arrow».","wiki_en":"The Flash (2014 TV series)","wiki_ru":"Флэш (фильм)"},{"name":"Arrow","emoji":"🏹","meta":["υπερηρωικό","2012–2020","ΗΠΑ"],"description":"Ο δισεκατομμυριούχος Όλιβερ Κουίν επιστρέφει μετά από πέντε χρόνια σε ένα ακατοίκητο νησί και αρχίζει να παλεύει με το έγκλημα του Σταρ Σίτι, με τη μάσκα ενός τοξότη τιμωρού. Η σειρά ξεκίνησε ένα ολόκληρο δίκτυο συνδεδεμένων υπερηρωικών σειρών του The CW.","fact":"Το «Arrow» άνοιξε το λεγόμενο Arrowverse, το κοινό σύμπαν πολλών υπερηρωικών σειρών του CW.","wiki_en":"Arrow (TV series)"},{"name":"Supergirl","emoji":"🦸‍♀️","meta":["υπερηρωικό","2015–2021","ΗΠΑ"],"description":"Η Κάρα Ντάνβερς, ξαδέλφη του Σούπερμαν, έκρυβε για χρόνια τις ικανότητές της, ώσπου αποφάσισε να υπερασπιστεί ανοιχτά το Νάσιοναλ Σίτι. Η σειρά συνδυάζει την υπερηρωική δράση με θέματα διαμόρφωσης της προσωπικότητας και αυτοπεποίθησης.","fact":"Η Κάρα Ντάνβερς γεννήθηκε στον Κρύπτον πριν από τον Σούπερμαν, αλλά λόγω καθυστέρησης στο ταξίδι έφτασε στη Γη μετά από αυτόν.","wiki_en":"Supergirl (TV series)"},{"name":"Altered Carbon","emoji":"🧬","meta":["σάιμπερπανκ","2018–2020","ΗΠΑ"],"description":"Σε ένα μακρινό μέλλον η ανθρώπινη συνείδηση μεταφέρεται από σώμα σε σώμα, σε «κελύφη», και ο πρώην επαναστάτης στρατιώτης Τακέσι Κόβατς ερευνά τη δολοφονία ενός από τους πλουσιότερους ανθρώπους του πλανήτη. Μεταφορά του μυθιστορήματος του Ρίτσαρντ Μόργκαν, με σκοτεινή σάιμπερπανκ αισθητική.","fact":"Το κέλυφος του πρωταγωνιστή το παίζουν διαφορετικοί ηθοποιοί σε διαφορετικές σεζόν — είναι μέρος της μηχανικής της πλοκής.","wiki_en":"Altered Carbon (TV series)"},{"name":"The Umbrella Academy","emoji":"☂️","meta":["υπερηρωικό","2019–2024","ΗΠΑ"],"description":"Επτά θετά παιδιά με ασυνήθιστες ικανότητες, που τα υιοθέτησε ένας εκκεντρικός δισεκατομμυριούχος, αναγκάζονται να μαζευτούν ξανά για να αποτρέψουν το τέλος του κόσμου. Η σειρά βασίζεται στα κόμικς του Τζέραρντ Γουέι, τραγουδιστή των My Chemical Romance.","fact":"Ένας από τους αδελφούς, ο Νούμερο Πέντε, έμεινε κολλημένος στο μέλλον για δεκαετίες και επέστρεψε σε σώμα εφήβου.","wiki_en":"The Umbrella Academy (TV series)"},{"name":"You","emoji":"📚","meta":["ψυχολογικό θρίλερ","2018–2025","ΗΠΑ"],"description":"Ο γοητευτικός υπάλληλος βιβλιοπωλείου Τζο Γκόλντμπεργκ ερωτεύεται εμμονικά γυναίκες και είναι έτοιμος για κάθε χειραγώγηση, αρκεί να βρεθεί κοντά στο αντικείμενο του πόθου του. Μεταφορά του μυθιστορήματος της Κάρολαϊν Κέπνες, στημένη στον εσωτερικό μονόλογο του ήρωα.","fact":"Η σειρά πρωτοβγήκε στο κανάλι Lifetime και έγινε επιτυχία μόνο αφού τα δικαιώματα τα αγόρασε το Netflix.","wiki_en":"You (TV series)","wiki_ru":"Ты (телесериал)"},{"name":"Sex Education","emoji":"🎓","meta":["εφηβικό δράμα","2019–2023","Ηνωμένο Βασίλειο"],"description":"Ο ντροπαλός μαθητής Ότις, που η μητέρα του δουλεύει σεξοθεραπεύτρια, ανοίγει χωρίς να το σχεδιάσει μια ανεπίσημη συμβουλευτική για σχέσεις και σεξουαλικότητα μέσα στο σχολείο. Η σειρά δένει το ξεκάθαρο χιούμορ με μια ζεστή ιστορία ενηλικίωσης.","fact":"Τα γυρίσματα έγιναν στην Ουαλία, παρότι η ιστορία τοποθετείται σε μια φανταστική αγγλική κωμόπολη.","wiki_en":"Sex Education (TV series)"},{"name":"Killing Eve","emoji":"🔪","meta":["αστυνομικό θρίλερ","2018–2022","Ηνωμένο Βασίλειο"],"description":"Η βαριεστημένη αξιωματικός των μυστικών υπηρεσιών Ιβ Πολάστρι παίρνει εντολή να εντοπίσει την άπιαστη και εκκεντρική πληρωμένη δολοφόνο Βιλανέλ, και ανάμεσα στις δύο γυναίκες γεννιέται μια επικίνδυνη αμοιβαία έλξη. Μεταφορά των νουβελών του Λουκ Τζένινγκς.","fact":"Κάθε σεζόν είχε δική της γυναίκα σεναριογράφο-υπεύθυνη: την πρώτη έγραψε η Φίμπι Γουόλερ-Μπριτζ, τις επόμενες άλλες δημιουργοί.","wiki_en":"Killing Eve"},{"name":"True Blood","emoji":"🩸","meta":["δράμα τρόμου","2008–2014","ΗΠΑ"],"description":"Μετά την εφεύρεση του συνθετικού αίματος, τα βαμπίρ βγαίνουν από τη σκιά και προσπαθούν να ενταχθούν στη ζωή μιας μικρής πόλης της Λουιζιάνα, όπου η σερβιτόρα Σούκι Στάκχαους έχει το δικό της ασυνήθιστο χάρισμα. Μεταφορά των μυθιστορημάτων της Σαρλέιν Χάρις.","fact":"Ο τίτλος παίζει με την αντίθεση ανάμεσα στο αληθινό αίμα και στο συνθετικό υποκατάστατο που πίνουν τα βαμπίρ.","wiki_en":"True Blood","wiki_ru":"Настоящая кровь"},{"name":"Oz","emoji":"🔒","meta":["δράμα φυλακής","1997–2003","ΗΠΑ"],"description":"Η ζωή των κρατουμένων στην πειραματική πτέρυγα υψίστης ασφαλείας «Emerald City» δίνεται χωρίς εξωραϊσμούς: βία, συμμορίες και αγώνας για επιβίωση. Ήταν μια από τις πρώτες δραματικές παραγωγές του HBO και άνοιξε στο κανάλι τον δρόμο για την «ενήλικη» τηλεόραση.","fact":"Θεωρείται ο πρόδρομος παραγωγών του HBO όπως το «The Sopranos» και το «The Wire».","wiki_en":"Oz (TV series)"},{"name":"24","emoji":"⏱️","meta":["κατασκοπικό θρίλερ","2001–2010","ΗΠΑ"],"description":"Κάθε σεζόν καλύπτει ένα εικοσιτετράωρο από τη ζωή του Τζακ Μπάουερ, πράκτορα μονάδας αντιτρομοκρατικής δράσης, σε πραγματικό χρόνο, επεισόδιο με επεισόδιο, ώρα με την ώρα. Το φορμά του πραγματικού χρόνου με την αντίστροφη μέτρηση έγινε το σήμα της σειράς.","fact":"Το ρολόι στην οθόνη τρέχει ασταμάτητα ακόμη και στα διαφημιστικά διαλείμματα — είναι κομμάτι του ύφους της σειράς.","wiki_en":"24 (TV series)"},{"name":"CSI: Crime Scene Investigation","emoji":"🔬","meta":["αστυνομικό δράμα","2000–2015","ΗΠΑ"],"description":"Μια ομάδα εγκληματολόγων του Λας Βέγκας εξιχνιάζει εγκλήματα με ιατροδικαστική: αποτυπώματα, ανάλυση αίματος και βαλλιστική. Η σειρά έφερε την εγκληματολογία στο μεγάλο κοινό και γέννησε αρκετά σπιν οφ σε όλο τον κόσμο.","fact":"Η επιτυχία της γέννησε το λεγόμενο «φαινόμενο CSI»: ενόρκους που περιμένουν από την αληθινή ιατροδικαστική πολύ περισσότερα από όσα μπορεί.","wiki_en":"CSI: Crime Scene Investigation"},{"name":"CSI: Miami","emoji":"🕶️","meta":["αστυνομικό δράμα","2002–2012","ΗΠΑ"],"description":"Σπιν οφ για την ομάδα εγκληματολόγων του ηλιόλουστου Μαϊάμι, με επικεφαλής τον υπαστυνόμο Οράτιο Κέιν, γνωστό για τις εντυπωσιακές ατάκες του πριν από τους τίτλους. Κράτησε το φορμά του πρωτότυπου και πρόσθεσε πιο λαμπερή, κινηματογραφική εικόνα.","fact":"Το «Yeah» του Οράτιο Κέιν και η χαρακτηριστική παύση πριν την αλλαγή σκηνής έγιναν μιμίδιο στο διαδίκτυο.","wiki_en":"CSI: Miami"},{"name":"Law & Order","emoji":"⚖️","meta":["αστυνομικό δράμα","1990–2010","ΗΠΑ"],"description":"Κάθε επεισόδιο χωρίζεται σε δύο μέρη: πρώτα η αστυνομία ερευνά το έγκλημα, μετά οι εισαγγελείς πάνε την υπόθεση στο δικαστήριο. Το φορμά «μια υπόθεση ανά επεισόδιο» και το αναγνωρίσιμο ηχητικό σήμα την έκαναν από τις πιο μακρόβιες σειρές της αμερικανικής τηλεόρασης.","fact":"Η φραντσάιζ «Law & Order» γέννησε αρκετά σπιν οφ και ξανάρχισε το 2022, μετά από μεγάλο διάλειμμα.","wiki_en":"Law & Order","wiki_ru":"Закон и порядок"},{"name":"Law & Order: Special Victims Unit","emoji":"🛡️","meta":["αστυνομικό δράμα","από το 1999","ΗΠΑ"],"description":"Το σπιν οφ του «Law & Order» παρακολουθεί τη μονάδα της αστυνομίας της Νέας Υόρκης που ερευνά εγκλήματα με σεξουαλικό κίνητρο, με επικεφαλής την ντετέκτιβ Ολίβια Μπένσον. Είναι από τις πιο μακρόβιες σειρές πρώτης ζώνης στις ΗΠΑ.","fact":"Η Μαρίσκα Χαρτζιτέι παίζει την Ολίβια Μπένσον από την πρώτη σεζόν του 1999, περισσότερο από κάθε άλλο πρόσωπο της φραντσάιζ.","wiki_en":"Law & Order: Special Victims Unit","wiki_ru":"Закон и порядок: Специальный корпус"},{"name":"Bones","emoji":"🦴","meta":["αστυνομικό δράμα","2005–2017","ΗΠΑ"],"description":"Η ιατροδικαστική ανθρωπολόγος Τεμπερανς Μπρέναν, μαζί με τον πράκτορα του FBI Σίλι Μπουθ, εξιχνιάζει εγκλήματα από τα οστά των θυμάτων. Η σειρά βασίζεται στα βιβλία της συγγραφέως και ανθρωπολόγου Κάθι Ράικς, που ήταν σύμβουλος στα γυρίσματα.","fact":"Μέσα στη σειρά η Μπρέναν γράφει η ίδια αστυνομικά, και η ηρωίδα των βιβλίων της λέγεται Κάθι Ράικς, προς τιμήν της αληθινής.","wiki_en":"Bones (TV series)"},{"name":"Castle","emoji":"🖋️","meta":["αστυνομικό","2009–2016","ΗΠΑ"],"description":"Ο δημοφιλής συγγραφέας αστυνομικών Ρίτσαρντ Καστλ παίρνει άδεια να συνοδεύει τη ντετέκτιβ της Νέας Υόρκης Κέιτ Μπέκετ στις έρευνές της, για να βρίσκει έμπνευση για νέα μυθιστορήματα. Η σειρά στηρίζεται στη χημεία των δύο πρωταγωνιστών και στους πνευματώδεις διαλόγους.","fact":"Τα βιβλία που «γράφει» ο Καστλ κυκλοφόρησαν στ' αλήθεια, ως πραγματικά μπεστ σέλερ με το όνομά του.","wiki_en":"Castle (TV series)"},{"name":"NCIS","emoji":"⚓","meta":["αστυνομικό δράμα","από το 2003","ΗΠΑ"],"description":"Μια ειδική μονάδα της ανακριτικής υπηρεσίας του Ναυτικού ερευνά εγκλήματα που αφορούν ναύτες και πεζοναύτες των ΗΠΑ. Ξεκίνησε ως σπιν οφ του «JAG» και έγινε μια από τις πιο μακρόβιες δραματικές σειρές της αμερικανικής τηλεόρασης.","fact":"Το NCIS σημαίνει Naval Criminal Investigative Service, μια υπαρκτή υπηρεσία υπό το Ναυτικό των ΗΠΑ.","wiki_en":"NCIS (TV series)","wiki_ru":"Морская полиция: Спецотдел"},{"name":"ER","emoji":"🏥","meta":["ιατρικό δράμα","1994–2009","ΗΠΑ"],"description":"Η ζωή των γιατρών στο τμήμα επειγόντων ενός νοσοκομείου του Σικάγο, σε ιλιγγιώδη, σχεδόν ντοκιμαντερίστικο ρυθμό βαρδιών και ζωών που σώζονται ή χάνονται. Τη σκέφτηκε ο Μάικλ Κράιτον και καθόρισε σε μεγάλο βαθμό το ιατρικό δράμα για δεκαετίες.","fact":"Από τους πρώτους σταθερούς ηθοποιούς της σειράς ήταν ο Τζορτζ Κλούνεϊ, στον ρόλο του παιδιάτρου Νταγκ Ρος.","wiki_en":"ER (TV series)"},{"name":"The West Wing","emoji":"🏛️","meta":["πολιτικό δράμα","1999–2006","ΗΠΑ"],"description":"Η σειρά δείχνει την καθημερινότητα μιας φανταστικής αμερικανικής προεδρικής κυβέρνησης, από τους λογογράφους ως τον σύμβουλο εθνικής ασφάλειας, μέσα από τα μάτια της ομάδας του Λευκού Οίκου. Ο δημιουργός Άαρον Σόρκιν έγινε γνωστός για τους ατέλειωτους διαλόγους εν κινήσει.","fact":"Το τέχνασμα του μεγάλου διαλόγου γυρισμένου εν κινήσει το ονόμασαν οι θαυμαστές «walk and talk» και έγινε το σήμα της σειράς.","wiki_en":"The West Wing","wiki_ru":"Западное крыло (телесериал)"},{"name":"American Horror Story","emoji":"👻","meta":["ανθολογία τρόμου","από το 2011","ΗΠΑ"],"description":"Κάθε σεζόν διηγείται μια ξεχωριστή, ολοκληρωμένη ιστορία τρόμου, από ένα στοιχειωμένο σπίτι ως ένα ψυχιατρείο, όμως οι ηθοποιοί περνούν από σεζόν σε σεζόν σε νέους ρόλους. Η μορφή της ανθολογίας επέτρεψε στους Ράιαν Μέρφι και Μπραντ Φάλτσακ να πειραματιστούν με ύφη.","fact":"Πολλοί ηθοποιοί, όπως η Τζέσικα Λανγκ και η Σάρα Πόλσον, έπαιξαν εντελώς διαφορετικά πρόσωπα σε διαφορετικές σεζόν.","wiki_en":"American Horror Story"},{"name":"Grimm","emoji":"📖","meta":["αστυνομικό φαντασίας","2011–2017","ΗΠΑ"],"description":"Ο αστυνομικός του Πόρτλαντ Νικ Μπέρκχαρντ μαθαίνει ότι κατάγεται από γενιά κυνηγών των όντων που περιγράφουν τα παραμύθια των αδελφών Γκριμ, και πρέπει να συνδυάζει την κανονική δουλειά του με ένα κρυφό κυνήγι τεράτων. Αστυνομικό «μια υπόθεση ανά επεισόδιο» πάνω στη μυθολογία ενός κρυμμένου κόσμου.","fact":"Ο τίτλος παραπέμπει ευθέως στους αδελφούς Γκριμ, που τα παραμύθια τους διαβάζονται εδώ ως αφηγήσεις για υπαρκτά όντα.","wiki_en":"Grimm (TV series)","wiki_ru":"Гримм"},{"name":"Smallville","emoji":"🌽","meta":["υπερηρωικό","2001–2011","ΗΠΑ"],"description":"Η σειρά δείχνει τον Κλαρκ Κεντ να μεγαλώνει στη μικρή πόλη Σμόλβιλ, πολύ πριν γίνει ο Σούπερμαν, με τον πρώτο έρωτα, τα σχολικά προβλήματα και τη σταδιακή συνειδητοποίηση των δυνάμεών του. Για χρόνια κρατούσε τον άγραφο κανόνα: ούτε στολή ούτε πτήσεις.","fact":"Οι δημιουργοί απέφευγαν επί χρόνια να δείξουν τον ήρωα με την κλασική στολή του Σούπερμαν· έγινε μόνο στο τελευταίο επεισόδιο.","wiki_en":"Smallville","wiki_ru":"Тайны Смолвиля"},{"name":"Star Trek: The Original Series","emoji":"🖖","meta":["επιστημονική φαντασία","1966–1969","ΗΠΑ"],"description":"Το πλήρωμα του διαστημόπλοιου «Εντερπράιζ», με τον κυβερνήτη Κερκ, εξερευνά το βαθύ διάστημα, συναντά νέους πολιτισμούς και τηρεί την αρχή της μη επέμβασης. Η σειρά του Τζιν Ροντενμπέρι έβαλε τα θεμέλια μιας από τις μεγαλύτερες φραντσάιζ επιστημονικής φαντασίας.","fact":"Τον βουλκανικό χαιρετισμό του Σποκ «ζήσε πολύ και ευημέρησε» τον επινόησε ο ηθοποιός Λέοναρντ Νίμοϊ, πάνω στην εβραϊκή ιερατική ευλογία.","wiki_en":"Star Trek: The Original Series","wiki_ru":"Звёздный путь"},{"name":"Battlestar Galactica","emoji":"🌌","meta":["επιστημονική φαντασία","2004–2009","ΗΠΑ"],"description":"Μετά την ξαφνική εξόντωση του ανθρώπινου πολιτισμού από τα ρομπότ Σάιλον, ένας μικρός στόλος επιζώντων με επικεφαλής το πολεμικό σκάφος «Γκαλάκτικα» ψάχνει στο διάστημα τον θρυλικό πλανήτη Γη. Το σκοτεινό ριμέικ της σειράς του 1978 επαινέθηκε για το βάθος των πολιτικών και θρησκευτικών θεμάτων του.","fact":"Κάποιοι Σάιλον δεν ξεχωρίζουν εξωτερικά από τους ανθρώπους, κάτι που κρατά την πλοκή σε διαρκή ένταση.","wiki_en":"Battlestar Galactica (2004 TV series)"},{"name":"Hannibal","emoji":"🍽️","meta":["ψυχολογικό θρίλερ","2013–2015","ΗΠΑ"],"description":"Ο νέος προφάιλερ του FBI Γουίλ Γκράχαμ δένεται με τον λαμπρό ψυχίατρο Χάνιμπαλ Λέκτερ, χωρίς να υποψιάζεται το σκοτεινό μυστικό του. Βασισμένη στους ήρωες του Τόμας Χάρις, ξεχωρίζει για την περίτεχνη, σχεδόν ζωγραφική αισθητική της.","fact":"Παρά το λατρευτικό της κοινό, η σειρά έκλεισε μετά από τρεις σεζόν, εξαιτίας των μέτριων ποσοστών.","wiki_en":"Hannibal (TV series)","wiki_ru":"Ганнибал"},{"name":"Riverdale","emoji":"🍒","meta":["εφηβικό δράμα","2017–2023","ΗΠΑ"],"description":"Οι ήρωες των κλασικών κόμικς για τον Άρτσι Άντριους βρίσκονται σε μια πολύ πιο σκοτεινή εκδοχή της κωμόπολης Ρίβερντεϊλ, όπου πίσω από τη γαλήνια βιτρίνα κρύβονται μυστικά και εγκλήματα. Ξεκινά ως αστυνομικό για έναν φόνο και μετατοπίζεται όλο και πιο πολύ στο πείραμα με τα είδη.","fact":"Βασίζεται στα Archie Comics, που ξεκίνησαν ως ελαφρές εφηβικές ιστορίες, χωρίς ίχνος νουάρ.","wiki_en":"Riverdale (2017 TV series)"},{"name":"Teen Wolf","emoji":"🐺","meta":["εφηβικό τρόμου","2011–2017","ΗΠΑ"],"description":"Ο απλός μαθητής Σκοτ ΜακΚολ γίνεται λυκάνθρωπος μετά την επίθεση ενός μυστηριώδους θηρίου και πρέπει να μάθει να ζει με τη νέα του φύση, χωρίς να χάσει τον εαυτό του και τους φίλους του. Εμπνεύστηκε από την ομώνυμη ταινία του 1985, αλλά χτίζει εντελώς δική της πλοκή.","fact":"Παρά τον τίτλο που παραπέμπει στην κομεντί του 1985 με τον Μάικλ Τζέι Φοξ, ο τόνος της σειράς είναι πολύ πιο σκοτεινός.","wiki_en":"Teen Wolf (TV series)","wiki_ru":"Волчонок (телесериал)"},{"name":"13 Reasons Why","emoji":"🎧","meta":["δράμα","2017–2020","ΗΠΑ"],"description":"Μετά τον τραγικό θάνατο μιας συμμαθήτριάς του, ο μαθητής Κλέι Τζένσεν παραλαμβάνει μια σειρά κασετών, όπου εκείνη εξηγεί ποια γεγονότα την έφεραν σε αυτή την απόφαση. Μεταφορά του μυθιστορήματος του Τζέι Άσερ, άνοιξε ευρεία συζήτηση για το πώς μιλά η τηλεόραση για τα εφηβικά τραύματα.","fact":"Μετά την πρώτη σεζόν, οι δημιουργοί άλλαξαν ορισμένες σκηνές στις μεταγενέστερες εκδόσεις, με τη σύσταση ψυχολόγων.","wiki_en":"13 Reasons Why","wiki_ru":"13 причин почему"},{"name":"Misfits","emoji":"🌩️","meta":["κομεντί επιστημονικής φαντασίας","2009–2013","Ηνωμένο Βασίλειο"],"description":"Μια ομάδα νέων που εκτίουν ποινή κοινωφελούς εργασίας αποκτά ασυνήθιστες ικανότητες μετά από μια παράξενη καταιγίδα και πρέπει να μάθει να ζει με αυτές, χωρίς να πάψει να είναι το ίδιο μπουλούκι αλητών. Ξεχωρίζει για το μαύρο χιούμορ και τον εμφατικά αντιηρωικό τόνο.","fact":"Ο ηθοποιός Ρόμπερτ Σίαν, που έπαιξε έναν από τους βασικούς ρόλους, άφησε την παραγωγή μετά τη δεύτερη σεζόν.","wiki_en":"Misfits (TV series)"},{"name":"Skins","emoji":"🎉","meta":["εφηβικό δράμα","2007–2013","Ηνωμένο Βασίλειο"],"description":"Η σειρά δείχνει τη ζωή μιας παρέας βρετανών εφήβων — πάρτι, πρώτους έρωτες, εξαρτήσεις και οικογενειακά προβλήματα — χωρίς λογοκρισία και χωρίς διδακτισμό. Κάθε δύο σεζόν το σύνολο των ηρώων ανανεώνεται εντελώς και μεγαλώνει μαζί με μια νέα γενιά ηθοποιών.","fact":"Σχεδόν όλο το καστ κάθε γενιάς επιλέχθηκε από ερασιτέχνες νέους ηθοποιούς, σε ανοιχτές ακροάσεις.","wiki_en":"Skins (British TV series)"},{"name":"Will & Grace","emoji":"🏙️","meta":["σιτκόμ","1998–2006","ΗΠΑ"],"description":"Ο γκέι δικηγόρος Γουίλ και η καλύτερή του φίλη Γκρέις μοιράζονται διαμέρισμα στη Νέα Υόρκη, και οι εκκεντρικοί φίλοι τους Τζακ και Κάρεν προσθέτουν κωμική οξύτητα. Ήταν από τις πρώτες σειρές της αμερικανικής μεϊνστριμ τηλεόρασης που έκανε έναν γκέι κεντρικό θετικό ήρωα σιτκόμ.","fact":"Μετά από οκτώ σεζόν, η σειρά αναβίωσε το 2017 και έβγαλε άλλες τρεις σεζόν.","wiki_en":"Will & Grace","wiki_ru":"Уилл и Грейс"},{"name":"Young Sheldon","emoji":"🧪","meta":["σιτκόμ","2017–2024","ΗΠΑ"],"description":"Το πρίκουελ του «The Big Bang Theory» διηγείται τα παιδικά χρόνια της ιδιοφυΐας Σέλντον Κούπερ σε μια μικρή πόλη του Τέξας, όπου η εξαιρετική ευφυΐα του δεν βρίσκει πάντα κατανόηση στην οικογένεια και στο σχολείο. Είναι σιτκόμ με μία κάμερα και αφηγητή.","fact":"Τον αφηγητή κάνει ο Τζιμ Πάρσονς, ο ίδιος ηθοποιός που έπαιζε τον ενήλικο Σέλντον στην αρχική σειρά.","wiki_en":"Young Sheldon"},{"name":"Parks and Recreation","emoji":"🌳","meta":["σιτκόμ ψευδοντοκιμαντέρ","2009–2015","ΗΠΑ"],"description":"Η ακούραστη υπάλληλος του τμήματος πάρκων της μικρής πόλης Πόνι, Λέσλι Νόουπ, προσπαθεί με σχεδόν αφελή ενθουσιασμό να κάνει τη ζωή των πολιτών καλύτερη, σκοντάφτοντας στη γραφειοκρατία και στην αδιαφορία των συναδέλφων. Ψευδοντοκιμαντέρ από τους παραγωγούς του «The Office».","fact":"Αρχικά σχεδιάστηκε ως ευθύ σπιν οφ του «The Office», αλλά με τον καιρό έγινε αυτοτελής παραγωγή.","wiki_en":"Parks and Recreation","wiki_ru":"Парки и зоны отдыха"},{"name":"30 Rock","emoji":"📺","meta":["σιτκόμ","2006–2013","ΗΠΑ"],"description":"Η Λιζ Λέμον, σεναριογράφος και υπεύθυνη ενός φανταστικού σόου με σκετς, ισορροπεί ανάμεσα σε ιδιότροπους αστέρες, έναν εκκεντρικό διευθυντή και το χάος μέσα στο τηλεοπτικό δίκτυο NBC. Η Τίνα Φέι τη στήριξε στη δική της εμπειρία από το «Saturday Night Live».","fact":"Τον εκκεντρικό διευθυντή του δικτύου έπαιξε ο Άλεκ Μπάλντουιν, που κέρδισε γι' αυτόν τον ρόλο αρκετά βραβεία Έμι.","wiki_en":"30 Rock","wiki_ru":"Студия 30"},{"name":"Everybody Hates Chris","emoji":"🎒","meta":["σιτκόμ","2005–2009","ΗΠΑ"],"description":"Η σειρά διηγείται σε ημιαυτοβιογραφική μορφή τα παιδικά και εφηβικά χρόνια του κομίκου Κρις Ροκ σε μια φτωχή συνοικία του Μπρούκλιν της δεκαετίας του 1980. Ο ενήλικος Κρις, στη φωνή του ίδιου του Ροκ, σχολιάζει τα γεγονότα εκτός κάδρου, με ειρωνική απόσταση.","fact":"Στην ιστορία τον Κρις τον στέλνουν σε σχολείο στην άλλη άκρη της πόλης, όπου είναι ο μόνος μαύρος μαθητής.","wiki_en":"Everybody Hates Chris"},{"name":"Married... with Children","emoji":"🛋️","meta":["σιτκόμ","1987–1997","ΗΠΑ"],"description":"Ο άτυχος πωλητής παπουτσιών Αλ Μπάντι, η τεμπέλα οικογένειά του και ο διαρκώς ειρωνικός τόνος της σειράς έγιναν το αντίδοτο στα γλυκερά οικογενειακά σιτκόμ της δεκαετίας του 1980. Ήταν από τις πρώτες σειρές που έδειξαν μια ξεκάθαρα δυσλειτουργική, αλλά με τον τρόπο της αγαπημένη οικογένεια.","fact":"Ήταν από τις πρώτες σειρές του νεοσύστατου δικτύου Fox και από τις μεγαλύτερες επιτυχίες του πρώτου προγράμματός του.","wiki_en":"Married... with Children"},{"name":"King of the Hill","emoji":"🍖","meta":["σιτκόμ κινουμένων σχεδίων","1997–2010","ΗΠΑ"],"description":"Ο συντηρητικός τεξανός Χανκ Χιλ πουλάει προπάνιο και εξαρτήματα προπανίου, μεγαλώνει έναν ιδιόμορφο γιο και προσπαθεί να κρατήσει τον γνώριμο τρόπο ζωής σε έναν κόσμο που αλλάζει. Η σειρά του Μάικ Τζαντζ ξεχωρίζει για το ήρεμο, σχεδόν ρεαλιστικό χιούμορ της.","fact":"Ο δημιουργός Μάικ Τζαντζ δανείζει τη φωνή του σε αρκετούς ήρωες: στον ίδιο τον Χανκ Χιλ και στον Μπούμχαουερ, τον γείτονα που μιλάει ακατάληπτα.","wiki_en":"King of the Hill","wiki_ru":"Царь горы"},{"name":"American Dad!","emoji":"🦅","meta":["σιτκόμ κινουμένων σχεδίων","από το 2005","ΗΠΑ"],"description":"Ο πράκτορας της CIA Σταν Σμιθ προσπαθεί να κρατήσει μια φαινομενικά ιδανική οικογένεια, πολεμώντας παράλληλα τρομοκράτες και εξωγήινους, ενώ το κατοικίδιό του, ο εξωγήινος Ρότζερ που μιλάει, σπέρνει διαρκώς χάος. Ο Σεθ ΜακΦάρλαν τη δημιούργησε ως πιο σουρεαλιστικό αντίστοιχο του «Family Guy».","fact":"Ο εξωγήινος Ρότζερ μπορεί να πάρει άπειρες μορφές και επαγγέλματα, για χάρη της κάθε καινούριας περιπέτειας.","wiki_en":"American Dad!"},{"name":"Beavis and Butt-Head","emoji":"🤘","meta":["κομεντί κινουμένων σχεδίων","1993–1997","ΗΠΑ"],"description":"Δύο ανεγκέφαλοι έφηβοι μεταλλάδες σχολιάζουν μουσικά βίντεο και μπλέκουν σε γελοίες καταστάσεις, σαν καρικατούρα της εφηβικής τεμπελιάς και αμάθειας. Η σειρά του Μάικ Τζαντζ έγινε ένα από τα σύμβολα του MTV της δεκαετίας του 1990.","fact":"Μετά από μερικές περιπτώσεις μίμησης των επικίνδυνων κατορθωμάτων των ηρώων, η σειρά δέχτηκε κριτική και λογοκρισία στις ΗΠΑ.","wiki_en":"Beavis and Butt-Head","wiki_ru":"Бивис и Баттхед"},{"name":"Daria","emoji":"📓","meta":["κομεντί κινουμένων σχεδίων","1997–2002","ΗΠΑ"],"description":"Η σαρκαστική Ντάρια Μόργκεντορφερ, μαθήτρια εντελώς αδιάφορη για τις σχολικές συμβάσεις, κοιτάζει τις ανοησίες των γύρω της με ειρωνική απόσταση. Το σπιν οφ του «Beavis and Butt-Head» βγήκε πολύ πιο ομιλητικό και παρατηρητικό από τη μητρική σειρά.","fact":"Η Ντάρια πρωτοεμφανίστηκε στο «Beavis and Butt-Head» ως δευτερεύων χαρακτήρας, πριν αποκτήσει δική της σειρά.","wiki_en":"Daria (TV series)"},{"name":"Adventure Time","emoji":"🍦","meta":["φαντασίας, κινούμενα σχέδια","2010–2018","ΗΠΑ"],"description":"Ο Φιν και ο καλύτερός του φίλος Τζέικ, ένας μαγικός σκύλος με σώμα που τεντώνεται, ταξιδεύουν στη μεταποκαλυπτική χώρα Ooo, γεμάτη παράξενα όντα και βασίλεια. Κάτω από την παιδική εικόνα κρύβονται απρόσμενα βαθιά θέματα ενηλικίωσης και απώλειας.","fact":"Η χώρα Ooo της σειράς αποδεικνύεται ότι είναι η Γη του μακρινού μέλλοντος, μετά από μια ανώνυμη παγκόσμια καταστροφή.","wiki_en":"Adventure Time"},{"name":"Gravity Falls","emoji":"🌲","meta":["μυστηρίου, κινούμενα σχέδια","2012–2016","ΗΠΑ"],"description":"Τα δίδυμα αδέλφια Ντίπερ και Μέιμπελ περνούν το καλοκαίρι στον εκκεντρικό θείο του παππού τους, στην κωμόπολη Γκράβιτι Φολς, γεμάτη αινιγματικά όντα και μυστικά. Ο Άλεξ Χερς τη στήνει ως ένα μεγάλο παζλ, με κρυπτογραφημένα μηνύματα στους τίτλους κάθε επεισοδίου.","fact":"Ο δημιουργός Άλεξ Χερς δανείζει τη φωνή του και στον θείο Σταν και στον βασικό κακό, τον Μπιλ Σάιφερ.","wiki_en":"Gravity Falls"},{"name":"Οι Μπαρμπόσκιν","emoji":"🐶","meta":["κινούμενα σχέδια","Ρωσία"],"description":"Μια πολυμελής οικογένεια σκυλόμορφων πλασμάτων, οι Μπαρμπόσκιν, λύνει καθημερινά οικιακά και πρακτικά ζητήματα, και κάθε επεισόδιο διδάσκει στον θεατή ένα απλό ηθικό μάθημα. Είναι από τις πιο δημοφιλείς ρωσικές σειρές κινουμένων σχεδίων της τελευταίας δεκαετίας.","fact":"Κάθε παιδί των Μπαρμπόσκιν έχει ένα σταθερά καθορισμένο γνώρισμα, από την εφευρετικότητα ως την αφόρητη σχολαστικότητα.","wiki_en":"Barboskins","wiki_ru":"Барбоскины"},{"name":"Τα Φίξικι","emoji":"🔧","meta":["κινούμενα σχέδια","από το 2010","Ρωσία"],"description":"Τα Φίξικι είναι μικροσκοπικά ανθρωπάκια που ζουν μέσα στις οικιακές συσκευές και τις επισκευάζουν από μέσα, εξηγώντας παράλληλα στα παιδιά, με απλά λόγια, πώς δουλεύουν τα πράγματα γύρω τους. Εκπαιδευτικό υλικό με ζεστό χιούμορ και ένα αναγνωρίσιμο μουσικό σήμα.","fact":"Η ιδέα βγήκε από το παιδικό βιβλίο του Εντουάρντ Ουσπένσκι για τα ανθρωπάκια που έρχονται μαζί με την εγγύηση.","wiki_en":"Fixiki","wiki_ru":"Фиксики"},{"name":"Τα Τρία Γατάκια","emoji":"🐱","meta":["κινούμενα σχέδια","από το 2015","Ρωσία"],"description":"Τρία γατάκια, ο Κορζίκ, η Καραμέλκα και ο Κομπότ, εξερευνούν τον κόσμο γύρω τους και μπλέκουν σε αστείες και διδακτικές ιστορίες μαζί με τους γάτους γονείς τους. Ένα από τα πιο αναγνωρίσιμα ρωσικά σήματα κινουμένων σχεδίων για παιδιά προσχολικής ηλικίας.","fact":"Τα ονόματα των τριών γατιών παραπέμπουν σε σπιτικά φαγητά και γλυκά: ένα κουλουράκι, μια καραμέλα και ένα κομπόστο.","wiki_en":"Three Cats","wiki_ru":"Три кота"},{"name":"Λούντικ","emoji":"🌙","meta":["κινούμενα σχέδια","2006–2019","Ρωσία"],"description":"Ένα παράξενο πλάσμα, που γεννήθηκε από μια σταγόνα φεγγαρίσιου γάλακτος και έπεσε στη Γη, γνωρίζει τον κόσμο της φύσης και μαθαίνει τη φιλία, την καλοσύνη και την αλληλοβοήθεια μαζί με τα έντομα, τους γείτονές του. Από τις πιο αναγνωρίσιμες και μακρόβιες ρωσικές σειρές για νήπια.","fact":"Το όνομα του ήρωα βγαίνει από τη ρωσική λέξη για τη Σελήνη: εκεί γεννήθηκε, πριν πέσει στη Γη.","wiki_en":"Luntik and His Friends","wiki_ru":"Лунтик и его друзья"},{"name":"Χελωνονιντζάκια","emoji":"🐢","meta":["δράσης, κινούμενα σχέδια","1987–1996","ΗΠΑ"],"description":"Τέσσερις μεταλλαγμένες χελώνες νίντζα — ο Λεονάρντο, ο Ντονατέλο, ο Ραφαέλ και ο Μιχαήλ Άγγελος — παλεύουν με το έγκλημα της Νέας Υόρκης από τα υπόγεια της πόλης, μαζί με τον δάσκαλό τους, έναν αρουραίο. Η αρχική σειρά του 1987 έκανε ένα ανεξάρτητο κόμικ παγκόσμιο φαινόμενο.","fact":"Κάθε χελώνα φοράει μάσκα σε δικό της χρώμα και έχει το όνομα ενός καλλιτέχνη της Αναγέννησης.","wiki_en":"Teenage Mutant Ninja Turtles (1987 TV series)"},{"name":"DuckTales","emoji":"🦆","meta":["περιπέτειας, κινούμενα σχέδια","1987–1990","ΗΠΑ"],"description":"Ο τσιγκούνης δισεκατομμυριούχος πάπιος Σκρουτζ ΜακΝτακ ξεκινά με τα τρία ανίψια του επικίνδυνες αποστολές για θησαυρούς σε όλο τον κόσμο. Κλασική σειρά της Disney, που καθόρισε σε μεγάλο βαθμό το πρόσωπο των κινουμένων σχεδίων περιπέτειας στα τέλη της δεκαετίας του 1980.","fact":"Ο Σκρουτζ ΜακΝτακ πρωτοεμφανίστηκε στα κόμικς του σχεδιαστή Καρλ Μπαρκς το 1947, πολύ πριν από τη σειρά.","wiki_en":"DuckTales (1987 TV series)"},{"name":"Chip 'n Dale: Rescue Rangers","emoji":"🐿️","meta":["περιπέτειας, κινούμενα σχέδια","1989–1990","ΗΠΑ"],"description":"Οι ντετέκτιβ σκίουροι Τσιπ και Ντέιλ, μαζί με την ομάδα τους — την εφευρέτρια ποντικίνα Γκάτζετ, τον δυνατό Μοντερέι Τζακ και τη μύγα Ζίπερ — αναλαμβάνουν υποθέσεις πολύ μικρές για τους μεγάλους ερευνητές. Έγινε από τις πιο δημοφιλείς παραγωγές της Disney στα τέλη της δεκαετίας του 1980.","fact":"Το όνομα του πρακτορείου των ηρώων παίζει με την αντίθεση ανάμεσα σε ελάχιστους ντετέκτιβ και πολύ μεγάλα προβλήματα.","wiki_en":"Chip 'n Dale: Rescue Rangers","wiki_ru":"Чип и Дейл спешат на помощь"},{"name":"Darkwing Duck","emoji":"🦆","meta":["υπερηρωικό, κινούμενα σχέδια","1991–1992","ΗΠΑ"],"description":"Ένας μυστηριώδης υπερήρωας πάπιος με το προσωνύμιο Darkwing Duck προστατεύει την πόλη Σεντ Κάναρντ από μια συμμορία γελοίων αλλά επικίνδυνων κακών, μεγαλώνοντας παράλληλα μια θετή κόρη. Παρωδεί κλασικούς υπερήρωες σαν τον Μπάτμαν, με το χιούμορ της Disney.","fact":"Η ατάκα του ήρωα, «Είμαι ο τρόμος που φτεροκοπά στη νύχτα», έχει γίνει από καιρό μιμίδιο.","wiki_en":"Darkwing Duck"},{"name":"Τομ και Τζέρι","emoji":"🐭","meta":["κομεντί κινουμένων σχεδίων","1940–1958","ΗΠΑ"],"description":"Ο γάτος Τομ προσπαθεί ατέλειωτα και ανεπιτυχώς να πιάσει τον πανούργο ποντικό Τζέρι, σε μια σειρά σύντομων, βουβών ή σχεδόν βουβών επεισοδίων με γκαγκ. Ένα από τα πιο αναγνωρίσιμα και μακρόβια δίδυμα στην ιστορία του σινεμά, βραβευμένο και με Όσκαρ.","fact":"Αρκετές ταινίες μικρού μήκους της σειράς κέρδισαν το Όσκαρ καλύτερης ταινίας κινουμένων σχεδίων μικρού μήκους.","wiki_en":"Tom and Jerry","wiki_ru":"Том и Джерри"},{"name":"Looney Tunes","emoji":"🐰","meta":["κομεντί κινουμένων σχεδίων","1930–1969","ΗΠΑ"],"description":"Η ανθολογία σύντομων κινουμένων σχεδίων της Warner Bros. χάρισε στον κόσμο τον Μπαγκς Μπάνι, τον Ντάφι Ντακ, τον Πόρκι Πιγκ και δεκάδες άλλους ήρωες με τα σήματα κατατεθέν κωμικά νούμερά τους. Καθόρισε σε μεγάλο βαθμό τη γλώσσα της αμερικανικής κωμωδίας κινουμένων σχεδίων του 20ού αιώνα.","fact":"Η φράση του Μπαγκς Μπάνι «What's up, doc?» είναι από τις πιο αναγνωρίσιμες ατάκες στην ιστορία της αμερικανικής κινούμενης εικόνας.","wiki_en":"Looney Tunes"},{"name":"Οι Φλίντστοουνς","emoji":"🦕","meta":["σιτκόμ κινουμένων σχεδίων","1960–1966","ΗΠΑ"],"description":"Η οικογένεια Φλίντστοουν ζει στη λίθινη εποχή, όμως η καθημερινότητά της παρωδεί τον τυπικό αμερικανικό προαστιακό τρόπο ζωής των μέσων του 20ού αιώνα, με αυτοκίνητα που πάνε με τα πόδια και συσκευές από δεινόσαυρους. Είναι η πρώτη σειρά κινουμένων σχεδίων που βγήκε σε πρώτη ζώνη στην αμερικανική τηλεόραση.","fact":"Η πολεμική κραυγή του Φρεντ Φλίντστοουν «Γιάμπα-ντάμπα-ντου!» έγινε από τις πιο γνωστές φράσεις στην ιστορία της κινούμενης εικόνας.","wiki_en":"The Flintstones"},{"name":"Οι Τζέτσονς","emoji":"🚀","meta":["σιτκόμ κινουμένων σχεδίων","1962–1963","ΗΠΑ"],"description":"Η οικογένεια Τζέτσον ζει σε μια φουτουριστική πόλη του μέλλοντος, με ιπτάμενα αυτοκίνητα, ρομπότ βοηθούς και κινούμενα πεζοδρόμια. Η σειρά της Hanna-Barbera σχεδιάστηκε ως το καθρέφτισμα των «Φλίντστοουνς»: στη θέση της λίθινης εποχής, ο κόσμος του μακρινού μέλλοντος.","fact":"Παρότι έβγαλε μόνο μία αρχική σεζόν, οι Τζέτσονς μένουν μια από τις πιο αναγνωρίσιμες εικόνες του μέλλοντος στην ποπ κουλτούρα του 20ού αιώνα.","wiki_en":"The Jetsons"},{"name":"Σκούμπι Ντου","emoji":"🐕","meta":["αστυνομικό, κινούμενα σχέδια","1969–1970","ΗΠΑ"],"description":"Ο δειλός σκύλος Σκούμπι Ντου και τέσσερις έφηβοι φίλοι του γυρίζουν με ένα βαν, τη «Μυστηριομηχανή», και ξεσκεπάζουν υποτιθέμενα φαντάσματα και τέρατα, που σχεδόν πάντα αποδεικνύονται κοινοί απατεώνες. Το φορμά «μια υπόθεση ανά επεισόδιο» και η ατάκα του κακού για τα ενοχλητικά παιδιά έγιναν κλασικά.","fact":"Σχεδόν σε κάθε επεισόδιο της αρχικής σειράς το μυστηριώδες τέρας αποδεικνυόταν ένας απλός άνθρωπος με στολή.","wiki_en":"Scooby-Doo, Where Are You!"},{"name":"Winx Club","emoji":"🧚‍♀️","meta":["φαντασίας, κινούμενα σχέδια","2004–2019","Ιταλία"],"description":"Έξι κοπέλες νεράιδες μαθαίνουν να χειρίζονται τη μαγεία στην Άλφεα, μια σχολή μαγείας, και προστατεύουν τη Μαγική Διάσταση από σκοτεινές δυνάμεις. Η ιταλική σειρά έγινε μια από τις πιο αναγνωρίσιμες ευρωπαϊκές παραγωγές κινουμένων σχεδίων για κορίτσια.","fact":"Ο δημιουργός Ιτζίνιο Στράφι εμπνεύστηκε από το ιαπωνικό είδος μάχο σότζο, τις ιστορίες με κοριτσάκια μάγισσες.","wiki_en":"Winx Club"},{"name":"Samurai Jack","emoji":"⏳","meta":["δράσης, κινούμενα σχέδια","2001–2017","ΗΠΑ"],"description":"Ένας ιάπωνας σαμουράι, που ο κακός δαίμονας Άκου τον πετά σε ένα μακρινό δυστοπικό μέλλον, ψάχνει τρόπο να γυρίσει στην εποχή του και να σταματήσει το κακό στη ρίζα του. Η σειρά του Τζέντι Ταρτακόφσκι ξεχωρίζει για το μινιμαλιστικό ύφος και τη σχεδόν βουβή αφήγηση.","fact":"Μετά από μεγάλο διάλειμμα, η σειρά πήρε την τελευταία, πέμπτη σεζόν της το 2017, πάνω από δέκα χρόνια μετά την τέταρτη.","wiki_en":"Samurai Jack","wiki_ru":"Самурай Джек"},{"name":"Dragon Ball Z","emoji":"🐉","meta":["σόνεν άνιμε","1989–1996","Ιαπωνία"],"description":"Ο πολεμιστής Σαϊγιάν Σον Γκόκου και οι φίλοι του προστατεύουν τη Γη από όλο και πιο ισχυρούς αντιπάλους, μαζεύοντας παράλληλα τις μαγικές Σφαίρες του Δράκου, που εκπληρώνουν κάθε ευχή. Έγινε μια από τις πιο επιδραστικές φραντσάιζ άνιμε, με τις ατέλειωτες μάχες και τους ήρωες που δυναμώνουν σταδιακά.","fact":"Είναι η άμεση συνέχεια του παλιότερου άνιμε «Dragon Ball», από το μάνγκα του Ακίρα Τοριγιάμα.","wiki_en":"Dragon Ball Z"},{"name":"Fullmetal Alchemist: Brotherhood","emoji":"⚗️","meta":["σόνεν άνιμε","2009–2010","Ιαπωνία"],"description":"Τα αδέλφια Έντουαρντ και Αλφόνς Έλρικ, που έχασαν μέρη του σώματός τους προσπαθώντας να αναστήσουν τη μητέρα τους με απαγορευμένη αλχημεία, ψάχνουν τη φιλοσοφική λίθο που θα τους τα επέστρεφε. Η εκδοχή «Brotherhood» είναι πιο κοντά στο μάνγκα της Χιρόμου Αρακάουα από την παλιότερη του 2003.","fact":"Η πρώτη μεταφορά του 2003 απομακρύνθηκε από την πλοκή του μάνγκα, κι έτσι χρόνια μετά το στούντιο γύρισε δεύτερη, πιο πιστή σειρά.","wiki_en":"Fullmetal Alchemist: Brotherhood","wiki_ru":"Стальной алхимик"},{"name":"Neon Genesis Evangelion","emoji":"🤖","meta":["μέκα άνιμε","1995–1996","Ιαπωνία"],"description":"Έφηβοι επιλέγονται να χειριστούν γιγάντια βιο-μηχανικά «Ευαγγέλια», για να αντιμετωπίσουν τα μυστηριώδη όντα που λέγονται Άγγελοι και απειλούν την ανθρωπότητα. Κάτω από το κέλυφος του μέκα άνιμε κρύβεται ένα πυκνό ψυχολογικό δράμα για τα τραύματα, τη μοναξιά και τον φόβο της εγγύτητας.","fact":"Το φινάλε της αρχικής σειράς ήταν τόσο αντισυμβατικό και αφαιρετικό, που αργότερα το στούντιο έβγαλε εναλλακτική εκδοχή σε ταινίες.","wiki_en":"Neon Genesis Evangelion"},{"name":"Inuyasha","emoji":"🏹","meta":["σόνεν άνιμε","2000–2004","Ιαπωνία"],"description":"Η μαθήτρια Καγκόμε πέφτει μέσα από ένα πηγάδι στην εποχή Σενγκόκου και ενώνει τις δυνάμεις της με τον ημιδαίμονα Ινουγιάσα, για να μαζέψουν τα κομμάτια του σπασμένου μαγικού πετραδιού των Τεσσάρων Ψυχών. Από το μάνγκα της Ρουμίκο Τακαχάσι, δένει την περιπέτεια με το ρομάντζο.","fact":"Η Ρουμίκο Τακαχάσι είναι γνωστή και ως δημιουργός άλλων λατρεμένων μάνγκα, ανάμεσά τους το «Ranma ½».","wiki_en":"Inuyasha"},{"name":"Cowboy Bebop","emoji":"🎷","meta":["νεο-νουάρ άνιμε","1998–1999","Ιαπωνία"],"description":"Ένα πλήρωμα κυνηγών επικηρυγμένων πάνω στο ταλαιπωρημένο διαστημόπλοιο «Bebop» γυρίζει το ηλιακό σύστημα ψάχνοντας μεροκάματο, και το παρελθόν του κάθε ήρωα αποκαλύπτεται σιγά σιγά μέσα από ξεχωριστά, σχεδόν αυτοτελή επεισόδια. Ξεχωρίζει για την τζαζ μουσική και την κινηματογραφική σκηνοθεσία.","fact":"Τη μουσική έγραψε η συνθέτρια Γιόκο Κάνο, και το τζαζ ύφος της είναι αναπόσπαστο κομμάτι της λατρευτικής φήμης της σειράς.","wiki_en":"Cowboy Bebop"},{"name":"Hunter × Hunter","emoji":"🎣","meta":["σόνεν άνιμε","2011–2014","Ιαπωνία"],"description":"Ο μικρός Γκον Φρικς δίνει εξετάσεις για τον τίτλο του χάντερ, ώστε να βρει τον χαμένο πατέρα του, και στον δρόμο κάνει φίλους και συναντά αντιπάλους με ικανότητες που υπακούουν σε μια περίπλοκη εσωτερική λογική. Η σειρά του 2011 είναι η πιο πιστή και πλήρης μεταφορά του μάνγκα του Γιοσιχίρο Τογκάσι.","fact":"Το μάνγκα από το οποίο προέρχεται εκδίδεται με μεγάλα διαλείμματα εδώ και δεκαετίες, λόγω προβλημάτων υγείας του δημιουργού.","wiki_en":"Hunter × Hunter (2011 TV series)"},{"name":"Jujutsu Kaisen","emoji":"🌀","meta":["σόνεν άνιμε","από το 2020","Ιαπωνία"],"description":"Ο μαθητής λυκείου Γιούτζι Ιταντόρι καταπίνει το καταραμένο δάχτυλο ενός θρυλικού δαίμονα και βρίσκεται μπλεγμένος σε έναν κρυφό πόλεμο μάγων εξορκιστών εναντίον καταρών που γεννιούνται από τα αρνητικά ανθρώπινα συναισθήματα. Από το μάνγκα του Γκέγκε Ακουτάμι, έγινε γρήγορα από τα πιο προβεβλημένα άνιμε της εποχής του.","fact":"Το μάνγκα έχει πρίκουελ: μια σύντομη σειρά κεφαλαίων που ο Γκέγκε Ακουτάμι σχεδίασε πριν από την κύρια ιστορία.","wiki_en":"Jujutsu Kaisen"},{"name":"Demon Slayer: Kimetsu no Yaiba","emoji":"🗡️","meta":["σόνεν άνιμε","από το 2019","Ιαπωνία"],"description":"Αφού ένας δαίμονας αφανίζει όλη την οικογένειά του, ο Τανζίρο Καμάντο γίνεται κυνηγός δαιμόνων, ψάχνοντας τρόπο να ξαναδώσει ανθρώπινη μορφή στην αδελφή του Νεζούκο. Από το μάνγκα του Κογιοχάρου Γκοτόγκε, φημίζεται για την εντυπωσιακή εικόνα του στούντιο ufotable και έγινε φαινόμενο εισπράξεων στην Ιαπωνία.","fact":"Οι ταινίες μεγάλου μήκους που βγήκαν από τη σειρά είναι από τις πιο εισπρακτικές στην ιστορία των ιαπωνικών αιθουσών.","wiki_en":"Demon Slayer: Kimetsu no Yaiba"},{"name":"My Hero Academia","emoji":"💥","meta":["σόνεν άνιμε","από το 2016","Ιαπωνία"],"description":"Σε έναν κόσμο όπου σχεδόν όλοι έχουν υπερδυνάμεις, ένα αγόρι χωρίς ούτε μία ονειρεύεται να γίνει ήρωας, και παίρνει την ευκαιρία του όταν ένας θρυλικός υπερήρωας του παραδίδει τη δύναμή του. Από το μάνγκα του Κόχεϊ Χορικόσι, είναι από τα πιο επιτυχημένα υπερηρωικά άνιμε.","fact":"Ο Κόχεϊ Χορικόσι έχει παραδεχτεί ότι για τη δημιουργία της σειράς τον ενέπνευσαν τα αμερικανικά υπερηρωικά κόμικς.","wiki_en":"My Hero Academia"},{"name":"Tokyo Ghoul","emoji":"👹","meta":["σέινεν άνιμε","2014–2018","Ιαπωνία"],"description":"Ο απλός φοιτητής Κεν Κανέκι, μετά από μια αποτυχημένη μεταμόσχευση οργάνων, μετατρέπεται σε μισό γκουλ και αναγκάζεται να ισορροπεί ανάμεσα στον κόσμο των ανθρώπων και στον κόσμο των όντων που τρέφονται με ανθρώπινη σάρκα. Από το μάνγκα του Σούι Ισίντα, μιλά για ταυτότητα και αποξένωση.","fact":"Οι μεταγενέστερες σεζόν απομακρύνθηκαν από το αρχικό μάνγκα και προκάλεσαν ανάμεικτες αντιδράσεις στους φαν του.","wiki_en":"Tokyo Ghoul"},{"name":"Berserk","emoji":"⚔️","meta":["σέινεν άνιμε","1997–1998","Ιαπωνία"],"description":"Ο μοναχικός μισθοφόρος Γκατς, που έχει επιβιώσει χάρη σε ένα τεράστιο σπαθί και στη δική του οργή, μπλέκει σε μια σκοτεινή ιστορία προδοσίας και εκδίκησης, σε έναν ζοφερό ψευδομεσαιωνικό κόσμο. Η αρχική σειρά του 1997, από το μάνγκα του Κεντάρο Μιούρα, μένει από τις πιο σεβαστές μεταφορές σκοτεινού φανταστικού.","fact":"Το μάνγκα του Κεντάρο Μιούρα έβγαινε πάνω από τριάντα χρόνια και έμεινε ημιτελές μετά τον θάνατό του, το 2021.","wiki_en":"Berserk (1997 TV series)"},{"name":"Ranma ½","emoji":"💧","meta":["κομεντί άνιμε","1989–1992","Ιαπωνία"],"description":"Ο νεαρός δεξιοτέχνης των πολεμικών τεχνών Ράνμα Σαοτόμε, αφού πέφτει σε μια καταραμένη πηγή, μετατρέπεται σε κοπέλα μόλις τον βρέξει κρύο νερό και ξαναγίνεται αγόρι με το ζεστό. Κομική σειρά από το μάνγκα της Ρουμίκο Τακαχάσι, στημένη στο ατέλειωτο μπέρδεμα της διπλής ταυτότητας.","fact":"Η κατάρα του πρωταγωνιστή είναι μόνο μία από πολλές: σχεδόν κάθε σημαντικός χαρακτήρας έχει τη δική του μεταμόρφωση.","wiki_en":"Ranma ½"},{"name":"Haikyu!!","emoji":"🏐","meta":["αθλητικό άνιμε","2014–2020","Ιαπωνία"],"description":"Ο κοντός αλλά πεισματάρης μαθητής Σόγιο Χινάτα ονειρεύεται να γίνει σπουδαίος παίκτης του βόλεϊ, παρά το ύψος του, και μπαίνει στην ομάδα του σχολείου Καρασούνο μαζί με τον Τόμπιο Καγκεγιάμα, αντίπαλο και συμπαίκτη του. Από το μάνγκα του Χαρουίτσι Φουρουντάτε, ξεχωρίζει για τη ζωντανή απόδοση των αγώνων.","fact":"Στη σειρά αποδίδεται μια αισθητή αναζωπύρωση του ενδιαφέροντος των ιαπώνων μαθητών για το βόλεϊ και τις σχολικές ομάδες.","wiki_en":"Haikyu!!"},{"name":"Ghost in the Shell: Stand Alone Complex","emoji":"🌐","meta":["σάιμπερπανκ άνιμε","2002–2005","Ιαπωνία"],"description":"Σε ένα μέλλον όπου η συνείδηση συνδέεται απευθείας με το δίκτυο, η ταγματάρχης Μοτόκο Κουσανάγκι και το Τμήμα Εννέα ερευνούν ηλεκτρονικά εγκλήματα στα όρια της φιλοσοφίας: πού τελειώνει ο άνθρωπος και πού αρχίζει η μηχανή. Η σειρά βαθαίνει τα θέματα της ομώνυμης ταινίας του 1995.","fact":"Ο υπότιτλος «Stand Alone Complex» δείχνει την κεντρική ιδέα: μιμητές αναπαράγουν ένα έγκλημα που δεν είχε ποτέ πρωτότυπο.","wiki_en":"Ghost in the Shell: Stand Alone Complex"},{"name":"Η Επισκέπτρια από το Μέλλον","emoji":"🛸","meta":["επιστημονική φαντασία","1985","ΕΣΣΔ"],"description":"Ο μαθητής Κόλια Γερασίμοφ βρίσκεται κατά λάθος στη Μόσχα του μέλλοντος και επιστρέφει μαζί με ένα κορίτσι, την Αλίσα Σελεζνιόβα, που την κυνηγούν από το μέλλον διαστημικοί πειρατές. Η πεντάμερη ταινία, από τη νουβέλα του Κιρ Μπουλίτσοφ, έγινε μια από τις πιο αγαπημένες σοβιετικές παραγωγές για παιδιά.","fact":"Την Αλίσα Σελεζνιόβα έπαιξε η μαθήτρια Ναταλία Γκούσεβα, που έγινε αμέσως είδωλο των σοβιετικών εφήβων και έπαιρνε σακιά με γράμματα.","wiki_en":"Guest from the Future","wiki_ru":"Гостья из будущего"},{"name":"Οι Περιπέτειες του Σέρλοκ Χολμς και του Δόκτορα Γουάτσον","emoji":"🎩","meta":["αστυνομικό","1979–1986","ΕΣΣΔ"],"description":"Ο σοβιετικός κύκλος ταινιών για τον ντετέκτιβ της Μπέικερ Στριτ και τον πιστό του φίλο γιατρό θεωρείται από τις πιο πιστές και σεβαστές μεταφορές του Άρθουρ Κόναν Ντόιλ. Ο Βασίλι Λιβάνοφ και ο Βιτάλι Σολόμιν έφτιαξαν έναν Χολμς και έναν Γουάτσον που έγιναν μέτρο για γενιές θεατών.","fact":"Ο Βασίλι Λιβάνοφ τιμήθηκε με παράσημο της Βρετανικής Αυτοκρατορίας για τον ρόλο του Σέρλοκ Χολμς — σπάνια αναγνώριση για ξένο ηθοποιό.","wiki_en":"The Adventures of Sherlock Holmes and Doctor Watson","wiki_ru":"Приключения Шерлока Холмса и доктора Ватсона"},{"name":"Οι Σκιές Χάνονται το Μεσημέρι","emoji":"🌾","meta":["δράμα","1971","ΕΣΣΔ"],"description":"Πολύμερη ταινία που παρακολουθεί τη μοίρα αρκετών γενεών ενός σιβηρικού χωριού σε όλη τη σοβιετική εποχή, από τον Εμφύλιο ως τα μεταπολεμικά χρόνια. Η μεταφορά του μυθιστορήματος του Ανατόλι Ιβανόφ έγινε μια από τις πρώτες πραγματικά μεγάλης κλίμακας σοβιετικές τηλεοπτικές σειρές.","fact":"Βασίστηκε σε μυθιστόρημα του Ανατόλι Ιβανόφ, που έγραψε και το βιβλίο πάνω στο οποίο στηρίχτηκε το μεταγενέστερο «Αιώνιο Κάλεσμα».","wiki_en":"Shadows Disappear at Noon","wiki_ru":"Тени исчезают в полдень"},{"name":"Το Αιώνιο Κάλεσμα","emoji":"🔔","meta":["δράμα","1973–1983","ΕΣΣΔ"],"description":"Πολύμερη σάγκα που παρακολουθεί τη μοίρα μιας μεγάλης σιβηρικής οικογένειας σε μισό αιώνα ρωσικής ιστορίας, από τις αρχές του αιώνα ως τον Β΄ Παγκόσμιο Πόλεμο. Η μεταφορά του μυθιστορήματος-έπους του Ανατόλι Ιβανόφ έγινε μια από τις πιο φιλόδοξες σοβιετικές σειρές της εποχής της.","fact":"Τα γυρίσματα κράτησαν πάνω από δέκα χρόνια, και η δράση καλύπτει αρκετές ιστορικές εποχές της Ρωσίας του 20ού αιώνα.","wiki_en":"The Eternal Call","wiki_ru":"Вечный зов"},{"name":"Οι Ειδικοί Ερευνούν","emoji":"🕵️","meta":["αστυνομικό","1971–1989","ΕΣΣΔ"],"description":"Κύκλος τηλεοπτικών ταινιών για τρεις ανακριτές — τον Ζναμένσκι, τον Τόμιν και την Κιμπρίτ, που τα αρχικά τους σχηματίζουν στα ρωσικά τη λέξη «ειδικοί» — οι οποίοι εξιχνιάζουν υποθέσεις της σοβιετικής αστυνομίας. Από τις πιο μακρόβιες και αγαπημένες αστυνομικές σειρές της σοβιετικής τηλεόρασης.","fact":"Το τραγούδι του κύκλου για μια υπηρεσία «επικίνδυνη και δύσκολη» έγινε από καιρό ο ανεπίσημος ύμνος της αστυνομίας.","wiki_en":"Sledstviye vedut ZnaToKi","wiki_ru":"Следствие ведут знатоки"},{"name":"Η Πετρούπολη των Γκάνγκστερ","emoji":"🏙️","meta":["αστυνομικό δράμα","2000–2007","Ρωσία"],"description":"Πολύμερη παραγωγή βασισμένη στα μυθιστορήματα του Αντρέι Κονσταντίνοφ, που δείχνει τη γέννηση και τον πόλεμο των εγκληματικών συμμοριών της Πετρούπολης στη δεκαετία του 1990, μέσα από τα μάτια κακοποιών, δημοσιογράφων και ανακριτών. Έγινε σημείο αναφοράς για το ρωσικό «συμμοριτικό» τηλεοπτικό είδος.","fact":"Αποτελείται από αρκετές ξεχωριστές πολύμερες ταινίες, που τις δένει ένας κοινός κόσμος και πρόσωπα που εν μέρει επανεμφανίζονται.","wiki_en":"Gangster Petersburg","wiki_ru":"Бандитский Петербург (телесериал)"},{"name":"La Piovra","emoji":"🐙","meta":["αστυνομικό δράμα","1984–2001","Ιταλία"],"description":"Ο αστυνομικός διευθυντής Κοράντο Κατάνι δίνει ασυμβίβαστη μάχη με τη σικελική μαφία, που τα πλοκάμια της, σαν χταποδιού, φτάνουν ως την κορυφή της εξουσίας. Η ιταλική σειρά έγινε λατρευτική πολύ πέρα από την Ιταλία, ιδίως στη Σοβιετική Ένωση των τελευταίων χρόνων της.","fact":"Ο ιταλικός τίτλος σημαίνει «το χταπόδι», ακριβώς λόγω αυτής της μεταφοράς της μαφίας ως τέρατος με πολλά πλοκάμια.","wiki_en":"La Piovra"},{"name":"O Clone","emoji":"👯","meta":["τηλεοπτική σειρά","2001–2002","Βραζιλία"],"description":"Η τελενοβέλα πλέκει τον απαγορευμένο έρωτα της μαροκινής Ζάντι και του βραζιλιάνου Λούκας με μια γραμμή επιστημονικής φαντασίας για την κρυφή κλωνοποίηση ενός ανθρώπου. Ο συνδυασμός ανατολίτικου χρώματος, μελοδράματος και επιστημονικής ίντριγκας την έκανε τεράστια επιτυχία πολύ πέρα από τη Βραζιλία.","fact":"Ο τίτλος βγαίνει από τη γραμμή της πλοκής για τη δημιουργία γενετικού αντιγράφου ενός προσώπου — σπάνιο θέμα για τελενοβέλα της εποχής.","wiki_en":"O Clone"},{"name":"Escrava Isaura","emoji":"⛓️","meta":["τηλεοπτική σειρά","1976","Βραζιλία"],"description":"Η δράση τοποθετείται σε μια βραζιλιάνικη φυτεία καφέ του 19ου αιώνα, όπου η πανέμορφη σκλάβα Ιζάουρα γίνεται στόχος του σκληρού αφέντη της, παρά τη μυστική αρχοντική καταγωγή της. Η μεταφορά του μυθιστορήματος του Μπερνάρντο Γκιμαράες ήταν από τις πρώτες βραζιλιάνικες τελενοβέλες που κατέκτησαν το κοινό στο εξωτερικό.","fact":"Η προβολή της στη Σοβιετική Ένωση στα τέλη της δεκαετίας του 1980 έγινε πολιτιστικό γεγονός και μία από τις πρώτες μαζικές γνωριμίες με το είδος.","wiki_en":"Escrava Isaura","wiki_ru":"Рабыня Изаура (телесериал)"},{"name":"Los Ricos También Lloran","emoji":"💔","meta":["τηλεοπτική σειρά","1979","Μεξικό"],"description":"Η φτωχή ορφανή Μαριάνα καταλήγει στο σπίτι μιας εύπορης μεξικανικής οικογένειας, ερωτεύεται τον κληρονόμο της και περνά σειρά μελοδραματικών δοκιμασιών για την ευτυχία της. Η μεξικανική τελενοβέλα ήταν από τις πρώτες ξένες σειρές που προβλήθηκαν στη ρωσική τηλεόραση στις αρχές του 1990 και προκάλεσε πραγματική μανία.","fact":"Η πρεμιέρα της στη Ρωσία, το 1991, μάζευε τεράστιο κοινό και έγινε ένα από τα πρώτα μαζικά τηλεοπτικά πάθη της μετασοβιετικής εποχής.","wiki_en":"Los Ricos También Lloran"},{"name":"Simplemente María","emoji":"🧵","meta":["τηλεοπτική σειρά","1989","Μεξικό"],"description":"Η σεμνή μοδίστρα Μαρία κάνει τον δρόμο από τη φτώχεια στην επιτυχία και στον έρωτα, σκοντάφτοντας σε ίντριγκες και προδοσίες. Η μεξικανική τελενοβέλα έγινε μια από τις λατρεμένες ξένες σειρές του ρωσικού κοινού στις αρχές του 1990, μαζί με το «Los Ricos También Lloran».","fact":"Για ένα διάστημα, το όνομα της ηρωίδας χρησιμοποιούνταν στη μετασοβιετική λαϊκή κουλτούρα ως συνώνυμο του είδους της λατινοαμερικανικής τελενοβέλας.","wiki_en":"Simplemente María (1989 telenovela)"},{"name":"Sesame Street","emoji":"🟡","meta":["παιδική εκπομπή","από το 1969","ΗΠΑ"],"description":"Εκπαιδευτική εκπομπή, όπου κούκλες μάπετ μαθαίνουν στους μικρούς θεατές γράμματα, αριθμούς και απλά μαθήματα ζωής, σε έναν φανταστικό δρόμο μιας πόλης. Μία από τις πιο μακρόβιες και επιδραστικές παιδικές τηλεοπτικές παραγωγές στον κόσμο, που γέννησε δεκάδες εθνικές προσαρμογές.","fact":"Τις κούκλες μάπετ τις έφτιαξε ο μαριονετίστας Τζιμ Χένσον, που έγινε γνωστός και από το «Muppet Show».","wiki_en":"Sesame Street"},{"name":"Άνω Κάτω","emoji":"🎬","meta":["κινηματογραφικό περιοδικό","από το 1974","ΕΣΣΔ/Ρωσία"],"description":"Κάθε τεύχος αυτού του κινηματογραφικού περιοδικού μαζεύει μερικά σύντομα χιουμοριστικά επεισόδια από τη σχολική και την παιδική ζωή, συχνά με μια απρόσμενη ατάκα στο τέλος. Από τις πιο μακρόβιες παραγωγές της ρωσικής οθόνης, απ' όπου πέρασαν δεκάδες μελλοντικοί γνωστοί ηθοποιοί ως παιδιά.","fact":"Από το καστ πέρασαν στη διάρκεια των δεκαετιών εκατοντάδες παιδιά, πολλά από τα οποία έγιναν αργότερα γνωστοί ενήλικοι ηθοποιοί.","wiki_en":"Yeralash","wiki_ru":"Ералаш (киножурнал)"},{"name":"Οι Ευέλπιδες","emoji":"🎖️","meta":["νεανικό δράμα","2006–2008","Ρωσία"],"description":"Η σειρά παρακολουθεί την καθημερινότητα εφήβων που σπουδάζουν σε στρατιωτική σχολή ευελπίδων: τις φιλίες τους, τους πρώτους έρωτες και τις προσπάθειές τους να σταθούν στην αυστηρή στρατιωτική πειθαρχία. Από τις πιο αξιοσημείωτες ρωσικές νεανικές σειρές των μέσων του 2000, στο κανάλι STS.","fact":"Στα γυρίσματα συμμετείχαν σύμβουλοι από αληθινές σχολές ευελπίδων, για να αποδοθεί πιο πιστά η ατμόσφαιρα του ιδρύματος.","wiki_en":"Kadetstvo","wiki_ru":"Кадетство"},{"name":"Πραγματικοί Μάγκες","emoji":"🎥","meta":["κομεντί ψευδοντοκιμαντέρ","από το 2010","Ρωσία"],"description":"Η σειρά είναι γυρισμένη ως ψευδοντοκιμαντέρ για την καθημερινότητα ενός απλού παιδιού από το Περμ, του Κόλιαν, και των φίλων του, με το ιδιότυπο χιούμορ τους, τις τυχαίες περιπέτειες και έναν σχεδόν ντοκιμαντερίστικο τόνο. Από τις πιο επιτυχημένες μακρόβιες παραγωγές του καναλιού TNT.","fact":"Η δράση τοποθετείται στο Περμ, και πολλές σκηνές γυρίστηκαν στους δρόμους και στις αυλές της αληθινής πόλης.","wiki_en":"Realnye Patsany","wiki_ru":"Реальные пацаны"},{"name":"Η Ομάδα Νέων","emoji":"🏒","meta":["αθλητικό δράμα","Ρωσία"],"description":"Σειρά για μια νεανική ομάδα χόκεϊ επί πάγου σε μια επαρχιακή πόλη, όπου οι αθλητικές φιλοδοξίες μπλέκονται με τα προσωπικά δράματα των παικτών και των προπονητών. Μια από τις λίγες ρωσικές σειρές που στήθηκαν γύρω από το χόκεϊ, και αξιοσημείωτη επιτυχία του καναλιού STS.","fact":"Οι σκηνές χόκεϊ γυρίστηκαν με τη συμμετοχή συμβούλων και κασκαντέρ από αληθινούς παίκτες.","wiki_en":"Molodyozhka","wiki_ru":"Молодёжка"},{"name":"Όλγα","emoji":"🍷","meta":["τραγικωμωδία","2016–2021","Ρωσία"],"description":"Η κοφτερή και καθόλου υποδειγματική μητέρα Όλγα προσπαθεί να βάλει σε τάξη τη ζωή της προβληματικής οικογένειάς της, με μαύρο χιούμορ και απρόσμενα ζεστές στιγμές. Η σειρά του TNT ξεχωρίζει από τα τυπικά σιτκόμ για τον πιο τολμηρό και ειλικρινή τόνο της.","fact":"Την κοφτερή και γλωσσού Όλγα έπαιξε η ηθοποιός Γιάνα Τρογιάνοβα.","wiki_en":"Olga (TV series)","wiki_ru":"Ольга (телесериал)"},{"name":"Τα Μυστικά της Ανάκρισης","emoji":"🔍","meta":["αστυνομικό","από το 2000","Ρωσία"],"description":"Η ανακρίτρια της εισαγγελίας Μαρία Σβετσόβα, σε δεκάδες σεζόν, ερευνά τα πιο διαφορετικά εγκλήματα της Πετρούπολης και έχει μείνει μια από τις πιο αναγνωρίσιμες φιγούρες της ρωσικής αστυνομικής τηλεόρασης. Η σειρά είναι στον αέρα πάνω από δύο δεκαετίες, από τις πιο μακρόβιες της ρωσικής τηλεόρασης.","fact":"Τη Μαρία Σβετσόβα παίζει από την πρώτη σεζόν και σε όλες τις συνέχειες η ηθοποιός Άννα Κοβαλτσούκ.","wiki_en":"Tayny sledstviya","wiki_ru":"Тайны следствия"},{"name":"Οι Συντηρούμενες","emoji":"💎","meta":["δράμα","από το 2019","Ρωσία"],"description":"Η σειρά δείχνει τη ζωή μερικών γυναικών της Μόσχας που έχουν σχέσεις με εύπορους προστάτες, και αποκαλύπτει σιγά σιγά την ανάποδη ενός φαινομενικά λαμπερού κόσμου με πολλά χρήματα. Αξιοσημείωτη παραγωγή της πλατφόρμας Start, έγινε γνωστή για την ευθύτητα και τα καυτά κοινωνικά θέματά της.","fact":"Ήταν από τις πρώτες μεγάλες πρωτότυπες παραγωγές ρωσικής πλατφόρμας που βγήκαν έξω από την τηλεόραση των καναλιών.","wiki_en":"Soderzhanki","wiki_ru":"Содержанки"},{"name":"Dom-2","emoji":"💒","meta":["ριάλιτι σόου","από το 2004","Ρωσία"],"description":"Οι παίκτες ζουν σε έναν κλειστό χώρο και προσπαθούν να χτίσουν σχέσεις και, τελικά, να κερδίσουν δικό τους σπίτι, ενώ οι θεατές παρακολουθούν την καθημερινότητα και τους καβγάδες τους σχεδόν όλο το εικοσιτετράωρο. Από τα πιο μακρόβια ριάλιτι στον κόσμο και φαινόμενο της ρωσικής μαζικής κουλτούρας.","fact":"Παρουσιάστριες του σόου κατά καιρούς ήταν η Ξένια Σομπτσάκ και η Ξένια Μποροντίνα, που ξεκίνησε η ίδια ως παίκτρια.","wiki_en":"Dom-2","wiki_ru":"Дом-2"},{"name":"Ο Τελευταίος Ήρωας","emoji":"🏝️","meta":["ριάλιτι σόου","από το 2001","Ρωσία"],"description":"Οι παίκτες ζουν σε ένα ακατοίκητο νησί, συναγωνίζονται σε αγωνίσματα και αποκλείουν ο ένας τον άλλον με ψηφοφορία, ώσπου να μείνει ένας νικητής. Η ρωσική εκδοχή του διεθνούς φορμά Survivor ήταν από τα πρώτα μεγάλα ριάλιτι της ρωσικής τηλεόρασης.","fact":"Τις πρώτες σεζόν της ρωσικής εκδοχής παρουσίασε ο ηθοποιός Σεργκέι Μπόντροφ ο νεότερος.","wiki_en":"Poslednyi Geroy","wiki_ru":"Последний герой (телепередача)"},{"name":"Οι Περιπέτειες του Καπετάνιου Βρούνγκελ","emoji":"⛵","meta":["κινούμενα σχέδια","1976–1979","ΕΣΣΔ"],"description":"Ο άτυχος αλλά γοητευτικός καπετάνιος Βρούνγκελ ξεκινά με το πλήρωμά του για έναν γύρο του κόσμου με ένα σκάφος που το όνομά του τα λέει όλα, μπλέκοντας στον δρόμο σε γελοίες και επικίνδυνες περιπέτειες. Σοβιετική σειρά από τη νουβέλα του Αντρέι Νεκράσοφ, κλασικό της ρωσικής κινούμενης εικόνας.","fact":"Η περίφημη φράση του ήρωα, ότι όπως βαφτίσεις το σκάφος έτσι θα αρμενίσει, έγινε παροιμιώδης στα ρωσικά.","wiki_en":"The Adventures of Captain Vrungel","wiki_ru":"Приключения капитана Врунгеля"},{"name":"iCarly","emoji":"💻","meta":["σιτκόμ","2007–2012","ΗΠΑ"],"description":"Η μαθήτρια Κάρλι Σέι, μαζί με τους φίλους της, φτιάχνει δική της διαδικτυακή εκπομπή μέσα από το υπνοδωμάτιό της, περνώντας παράλληλα τις τυπικές εφηβικές περιπέτειες και παρεξηγήσεις. Η σειρά του Nickelodeon ήταν από τις πρώτες στη μεγάλη τηλεόραση που έβαλε στο κέντρο της το ερασιτεχνικό βίντεο.","fact":"Σχεδόν δέκα χρόνια μετά το τέλος της αρχικής σειράς, βγήκε συνέχεια με τους ήρωες μεγαλωμένους.","wiki_en":"iCarly"},{"name":"Hannah Montana","emoji":"🎤","meta":["σιτκόμ","2006–2011","ΗΠΑ"],"description":"Η απλή μαθήτρια Μάιλι Στιούαρτ ζει διπλή ζωή, κρύβοντας από τους συμμαθητές της ότι στην πραγματικότητα είναι η δημοφιλής ποπ σταρ Χάνα Μοντάνα. Η σειρά έκανε αστέρι τη νεαρή Μάιλι Σάιρους και έγινε μια από τις ναυαρχίδες του Disney Channel των τελευταίων χρόνων του 2000.","fact":"Τον πρωταγωνιστικό ρόλο έπαιξε η Μάιλι Σάιρους, κόρη του τραγουδιστή της κάντρι Μπίλι Ρέι Σάιρους, που εμφανιζόταν κι εκείνος στη σειρά.","wiki_en":"Hannah Montana"},{"name":"Wizards of Waverly Place","emoji":"✨","meta":["σιτκόμ","2007–2012","ΗΠΑ"],"description":"Τρία παιδιά μάγοι από μια απλή οικογένεια της Νέας Υόρκης μαθαίνουν κρυφά μαγεία, ξέροντας ότι μόνο ένα από αυτά θα κρατήσει τις δυνάμεις του ως ενήλικο. Η σειρά του Disney Channel δένει το εφηβικό σιτκόμ με στοιχεία φαντασίας και οικογενειακού ανταγωνισμού.","fact":"Τον πρωταγωνιστικό ρόλο έπαιξε η Σελένα Γκόμεζ, για την οποία η σειρά ήταν μια από τις πρώτες μεγάλες υποκριτικές επιτυχίες.","wiki_en":"Wizards of Waverly Place"},{"name":"Zoey 101","emoji":"🏫","meta":["σιτκόμ","2005–2008","ΗΠΑ"],"description":"Η Ζόι Μπρουκς μπαίνει σε ένα φημισμένο οικοτροφείο που μόλις έχει γίνει μικτό, και μαζί με τους φίλους της περνά τις τυπικές εφηβικές περιπέτειες της ζωής στην εστία. Η σειρά του Nickelodeon ήταν από τις πρώτες μεγάλες υποκριτικές δουλειές της Τζέιμι Λιν Σπίαρς.","fact":"Τον πρωταγωνιστικό ρόλο έπαιξε η Τζέιμι Λιν Σπίαρς, μικρότερη αδελφή της τραγουδίστριας Μπρίτνεϊ Σπίαρς.","wiki_en":"Zoey 101"},{"name":"Drake & Josh","emoji":"🎸","meta":["σιτκόμ","2004–2007","ΗΠΑ"],"description":"Δύο εντελώς διαφορετικά ετεροθαλή αδέλφια — ο ξιπασμένος μουσικός Ντρέικ και ο άτυχος σπασίκλας Τζος — αναγκάζονται να μοιράζονται το ίδιο δωμάτιο και μπλέκουν διαρκώς σε κωμικές περιπέτειες. Η σειρά του Nickelodeon έγινε από τα πιο αναγνωρίσιμα εφηβικά σιτκόμ των μέσων του 2000.","fact":"Ο Ντρέικ Μπελ, που έπαιξε τον Ντρέικ, έγραψε και ερμήνευσε και το τραγούδι των τίτλων.","wiki_en":"Drake & Josh"},{"name":"Hey Arnold!","emoji":"🏈","meta":["κινούμενα σχέδια","1996–2004","ΗΠΑ"],"description":"Ο καλόκαρδος Άρνολντ, ένα αγόρι με παράξενο σχήμα κεφαλιού, ζει με τον παππού και τη γιαγιά του σε πολυκατοικία μιας μεγάλης πόλης και περνά μαζί με τους φίλους του τις ιστορίες της ενηλικίωσης, σε ένα απόλυτα αναγνωρίσιμο αστικό σκηνικό. Ξεχωρίζει για τη ρεαλιστική, ζεστή ματιά στα παιδιά της πόλης.","fact":"Το σχήμα του κεφαλιού του ήρωα ήταν για χρόνια τρέχον αστείο μέσα στη σειρά και δεν πήρε ποτέ μια σταθερή εξήγηση.","wiki_en":"Hey Arnold!","wiki_ru":"Эй, Арнольд!"},{"name":"Rugrats","emoji":"👶","meta":["κινούμενα σχέδια","1991–2004","ΗΠΑ"],"description":"Ο κόσμος μέσα από τα μάτια μιας παρέας μωρών, που βλέπουν τις καθημερινές οικιακές καταστάσεις σαν αληθινές περιπέτειες, γεμάτες φαντασία και μικρούς κινδύνους. Από τις πιο επιτυχημένες σειρές κινουμένων σχεδίων του Nickelodeon στη δεκαετία του 1990 και σήμα κατατεθέν του καναλιού.","fact":"Ο θεατής καταλαβαίνει άριστα τα μωρά, ενώ οι μεγάλοι ακούν μόνο μπουρμπουλήθρες — πάνω σε αυτό στήνονται τα μισά αστεία.","wiki_en":"Rugrats"},{"name":"The Wild Thornberrys","emoji":"🦁","meta":["κινούμενα σχέδια","1998–2004","ΗΠΑ"],"description":"Η Ελάιζα Θόρνμπερι, κόρη δημιουργών ντοκιμαντέρ που ταξιδεύουν συνεχώς, αποκτά τη μαγική ικανότητα να μιλάει με τα ζώα και τη χρησιμοποιεί για να βοηθά τη φύση στις οικογενειακές αποστολές σε όλο τον κόσμο. Η σειρά του Nickelodeon δένει την περιπέτεια με εκπαιδευτικά θέματα οικολογίας.","fact":"Το χάρισμα της ηρωίδας η σειρά το εξηγεί ως έργο ενός μυστηριώδους πνεύματος της φύσης, που συνάντησε στην Αφρική.","wiki_en":"The Wild Thornberrys"},{"name":"Phineas and Ferb","emoji":"🛠️","meta":["κινούμενα σχέδια","2007–2015","ΗΠΑ"],"description":"Δύο ακούραστα ετεροθαλή αδέλφια σκέφτονται και φτιάχνουν κάθε μέρα του καλοκαιριού μια απίστευτη εφεύρεση, ενώ η μεγάλη τους αδελφή προσπαθεί ανεπιτυχώς να τα ξεσκεπάσει στους γονείς. Η σειρά του Disney Channel στήνεται σε μια επαναλαμβανόμενη δομή επεισοδίων και έγινε από τις πιο αγαπημένες του καναλιού.","fact":"Σχεδόν σε κάθε επεισόδιο ακούγεται η ερώτηση πού πήγε ο Πέρι, το κατοικίδιο των ηρώων, που στην πραγματικότητα είναι μυστικός πράκτορας.","wiki_en":"Phineas and Ferb"},{"name":"Miraculous: Tales of Ladybug & Cat Noir","emoji":"🐞","meta":["υπερηρωικό, κινούμενα σχέδια","από το 2015","Γαλλία"],"description":"Οι παριζιάνοι μαθητές Μαρινέτ και Αντριάν μεταμορφώνονται κρυφά στους υπερήρωες Λέιντι Μπαγκ και Κατ Νουάρ, για να αντιμετωπίσουν έναν κακό που κυνηγά τα μαγικά τους αντικείμενα, χωρίς να ξέρουν ποιος κρύβεται πίσω από τη μάσκα του άλλου. Η γαλλική σειρά γνώρισε μεγάλη διεθνή επιτυχία.","fact":"Ο δημιουργός Τομά Αστρίκ έχει παραδεχτεί ότι εμπνεύστηκε ταυτόχρονα από τα κλασικά υπερηρωικά κόμικς και από τα ιαπωνικά μάχο σότζο.","wiki_en":"Miraculous: Tales of Ladybug & Cat Noir"},{"name":"Naruto: Shippuden","emoji":"🍥","meta":["σόνεν άνιμε","2007–2017","Ιαπωνία"],"description":"Η συνέχεια της ιστορίας του νίντζα Ναρούτο Ουζουμάκι δείχνει την ενηλικίωσή του και τον δρόμο του για να γίνει ο δυνατότερος και πιο σεβαστός νίντζα του χωριού του, παρά τη σφραγίδα του επικίνδυνου πνεύματος που κουβαλά από τη γέννησή του. Άμεση συνέχεια του αρχικού «Naruto» και από τα πιο γνωστά σόνεν παγκοσμίως.","fact":"Το «Naruto» μαζί με το «Shippuden» ξεπερνά συνολικά τα επτακόσια επεισόδια.","wiki_en":"Naruto: Shippuden"},{"name":"Bleach","emoji":"💀","meta":["σόνεν άνιμε","2004–2012","Ιαπωνία"],"description":"Ο απλός μαθητής Ιτσίγκο Κουροσάκι αποκτά τις δυνάμεις ενός σινιγκάμι, οδηγού των ψυχών, και αναλαμβάνει το καθήκον να προστατεύει ζωντανούς και νεκρούς από τα κακά πνεύματα. Από το μάνγκα του Τάιτο Κούμπο, ξεχωρίζει για τις εντυπωσιακές μάχες και το αξιομνημόνευτο σχέδιο των ηρώων.","fact":"Μετά από μεγάλο διάλειμμα, η σειρά πήρε συνέχεια το 2022, που μεταφέρει το τελευταίο μέρος του μάνγκα.","wiki_en":"Bleach (TV series)","wiki_ru":"Блич"},{"name":"One-Punch Man","emoji":"👊","meta":["παρωδιακό άνιμε","από το 2015","Ιαπωνία"],"description":"Ο ήρωας Σαϊτάμα είναι τόσο δυνατός, που νικά κάθε αντίπαλο με μια γροθιά, κι έτσι το βασικό του πρόβλημα δεν είναι η μάχη με το κακό αλλά η απλή βαρεμάρα. Από το γουεμπκόμικ του ΟΝΕ, παρωδεί τα κλισέ του υπερηρωικού είδους, μένοντας παράλληλα θεαματική ταινία δράσης.","fact":"Το «One-Punch Man» ξεκίνησε ως ερασιτεχνικό γουεμπκόμικ ενός δημιουργού με το ψευδώνυμο ΟΝΕ, που έγινε βάιραλ πριν καν εκδοθεί επαγγελματικά.","wiki_en":"One-Punch Man"},{"name":"The Expanse","emoji":"🛰️","meta":["επιστημονική φαντασία","2015–2022","ΗΠΑ"],"description":"Σε ένα μέλλον όπου η ανθρωπότητα έχει απλωθεί σε όλο το ηλιακό σύστημα, η πολιτική ένταση ανάμεσα στη Γη, τον Άρη και τη ζώνη των αστεροειδών εκτρέπεται σε ανοιχτή σύγκρουση μετά από ένα αινιγματικό εύρημα. Από τα μυθιστορήματα του Τζέιμς Κόρεϊ, φημίζεται για την προσεγμένη επιστημονική της ακρίβεια.","fact":"Το κανάλι SyFy έκλεισε τη σειρά μετά την τρίτη σεζόν, όμως συνεχίστηκε όταν τα δικαιώματα τα αγόρασε η Amazon.","wiki_en":"The Expanse (TV series)","wiki_ru":"Пространство"},{"name":"Dark","emoji":"🌑","meta":["δράμα επιστημονικής φαντασίας","2017–2020","Γερμανία"],"description":"Η εξαφάνιση παιδιών σε μια μικρή γερμανική πόλη οδηγεί στην αποκάλυψη ενός μυστικού που δένει αρκετές γενιές τοπικών οικογενειών μέσα από βρόχους του χρόνου. Η γερμανική σειρά του Netflix ξεχωρίζει για την πολύπλοκη, προσεκτικά χτισμένη δομή της και τη σκοτεινή ατμόσφαιρα.","fact":"Ήταν η πρώτη πρωτότυπη γερμανόφωνη σειρά που παρήγαγε το Netflix.","wiki_en":"Dark (TV series)","wiki_ru":"Тьма (телесериал)"},{"name":"See","emoji":"🌫️","meta":["επιστημονική φαντασία","2019–2022","ΗΠΑ"],"description":"Σε ένα μακρινό μέλλον, ένας ιός έχει στερήσει την όραση από σχεδόν όλη την ανθρωπότητα, και η γέννηση παιδιών που βλέπουν γίνεται πηγή φόβου και θρησκευτικού δέους. Η σειρά, με πρωταγωνιστή τον Τζέισον Μομόα, εξετάζει πώς λειτουργεί μια κοινωνία που έχει προσαρμοστεί πλήρως στη ζωή χωρίς όραση.","fact":"Για να αποδοθεί πιο πιστά η τύφλωση, οι δημιουργοί συνεργάστηκαν με ειδικούς και με τυφλούς συμβούλους.","wiki_en":"See (TV series)"},{"name":"The Good Wife","emoji":"👩‍⚖️","meta":["δικαστικό δράμα","2009–2016","ΗΠΑ"],"description":"Μετά από ένα δημόσιο σκάνδαλο με τον πολιτικό σύζυγό της, η Αλίσια Φλόρικ επιστρέφει στη δικηγορία για να συντηρήσει την οικογένειά της και να ξαναχτίσει τη ζωή και την καριέρα της. Η σειρά συνδυάζει το φορμά «μια υπόθεση ανά επεισόδιο» με ένα μακρόπνοο πολιτικό και προσωπικό δράμα.","fact":"Η πλοκή εμπνέεται σε μεγάλο βαθμό από αληθινά πολιτικά σκάνδαλα με απιστίες δημόσιων προσώπων.","wiki_en":"The Good Wife","wiki_ru":"Хорошая жена"},{"name":"How to Get Away with Murder","emoji":"🖤","meta":["δικαστικό θρίλερ","2014–2020","ΗΠΑ"],"description":"Η χαρισματική και αδίστακτη καθηγήτρια νομικής Ανάλιζ Κίτινγκ μπλέκει μια ομάδα φοιτητών της σε ένα κουβάρι από αληθινές δικαστικές υποθέσεις και δικά της σκοτεινά μυστικά. Η σειρά ξεχωρίζει για τη μη γραμμική αφήγηση, που ανακατεύει το παρόν με το μέλλον μέσα στην ίδια σεζόν.","fact":"Τον πρωταγωνιστικό ρόλο έπαιξε η Βαϊόλα Ντέιβις, η πρώτη μαύρη ηθοποιός που κέρδισε Έμι για πρώτο δραματικό ρόλο.","wiki_en":"How to Get Away with Murder"},{"name":"Billions","emoji":"💰","meta":["δράμα","2016–2023","ΗΠΑ"],"description":"Ο φιλόδοξος εισαγγελέας Τσακ Ρόουντς μπαίνει σε μακρόχρονη αναμέτρηση με τον ισχυρό διαχειριστή αμοιβαίου κεφαλαίου Μπόμπι Άξελροντ, μετατρέποντας τη δίωξη των χρηματοοικονομικών απατών σε προσωπική βεντέτα. Η σειρά δείχνει τον κόσμο της Wall Street από μέσα: εξουσία, χρήμα και ασυμβίβαστες φιλοδοξίες.","fact":"Τον εισαγγελέα Τσακ Ρόουντς παίζει ο Πολ Τζιαμάτι και τον δισεκατομμυριούχο Μπόμπι Άξελροντ ο Ντάμιαν Λιούις.","wiki_en":"Billions (TV series)"},{"name":"Τα Κρατικά Σύνορα","emoji":"🪖","meta":["πολεμικό δράμα","1980–1988","ΕΣΣΔ"],"description":"Κύκλος πολύμερων ταινιών για τους υπερασπιστές των σοβιετικών κρατικών συνόρων σε διαφορετικές ιστορικές περιόδους, από την επανάσταση ως τα μεταπολεμικά χρόνια. Μια από τις πιο φιλόδοξες σοβιετικές τηλεοπτικές παραγωγές για τους συνοριοφύλακες, γυρισμένη σε αρκετές χωριστές ταινίες του ίδιου κύκλου.","fact":"Όλες τις ταινίες του κύκλου τις γύρισε το λευκορωσικό στούντιο «Μπελαρούσφιλμ».","wiki_en":"State Border","wiki_ru":"Государственная граница (телесериал)"},{"name":"Καμένσκαγια","emoji":"🔎","meta":["αστυνομικό","1999–2011","Ρωσία"],"description":"Η Αναστασία Καμένσκαγια, έξυπνη και καθόλου εντυπωσιακή αξιωματικός της δίωξης εγκλήματος, εξιχνιάζει δύσκολα εγκλήματα περισσότερο με το μυαλό και την αναλυτική σκέψη της παρά με τη δύναμη. Από τα αστυνομικά μυθιστορήματα της Αλεξάντρα Μαρίνινα, έγινε σημείο αναφοράς της ρωσικής αστυνομικής τηλεόρασης.","fact":"Η Αλεξάντρα Μαρίνινα, που έγραψε τα βιβλία, είχε υπηρετήσει η ίδια πολλά χρόνια στην αστυνομία.","wiki_en":"Kamenskaya","wiki_ru":"Каменская (телесериал)"},{"name":"Τμήμα Ανθρωποκτονιών","emoji":"🔫","meta":["αστυνομικό δράμα","2000–2005","Ρωσία"],"description":"Η σειρά παρακολουθεί την καθημερινότητα των ανδρών του τμήματος ανθρωποκτονιών της αστυνομίας της Πετρούπολης, που ερευνούν τα βαρύτερα εγκλήματα της δεκαετίας του 1990 και του 2000. Μια από τις εμβληματικές ρωσικές αστυνομικές σειρές των αρχών του 2000.","fact":"Γυρίστηκε στην Αγία Πετρούπολη και στηρίχτηκε σε μεγάλο βαθμό στην πραγματική πρακτική της δίωξης εγκλήματος της εποχής.","wiki_en":"Uboynaya Sila","wiki_ru":"Убойная сила"},{"name":"Οι Βορονίν","emoji":"🏠","meta":["σιτκόμ","2009–2019","Ρωσία"],"description":"Η μεγάλη και φασαριόζικη οικογένεια Βορονίν, τρεις γενιές μαζί, μοιράζεται ένα διαμέρισμα και περνά τη μέρα της τσακωνόμενη και συμφιλιωνόμενη για ασήμαντες καθημερινές αφορμές. Η ρωσική εκδοχή του αμερικανικού σιτκόμ «Everybody Loves Raymond» έγινε από τις πιο μακρόβιες παραγωγές του καναλιού STS.","fact":"Τον Κόστια Βορονίν παίζει σε όλες τις σεζόν ο Γκεόργκι Ντρόνοφ και τη γυναίκα του Βέρα η Εκατερίνα Βόλκοβα.","wiki_en":"Voroniny","wiki_ru":"Воронины"},{"name":"Ευτυχισμένοι Μαζί","emoji":"👞","meta":["σιτκόμ","2006–2013","Ρωσία"],"description":"Ο πωλητής παπουτσιών Γκένα Μπούκιν ονειρεύεται μια καλύτερη ζωή, αλλά μένει κολλημένος σε μια φασαριόζικη οικογένεια που δεν τον καταλαβαίνει πάντα, σε μια μικρή επαρχιακή πόλη. Η ρωσική εκδοχή του αμερικανικού σιτκόμ «Married... with Children» έγινε από τις μεγάλες επιτυχίες του πρώτου προγράμματος του TNT.","fact":"Η σειρά είναι η επίσημη ρωσική εκδοχή του αμερικανικού σιτκόμ «Married... with Children».","wiki_en":"Schastlivy Vmeste","wiki_ru":"Счастливы вместе"},{"name":"6 Καρέ","emoji":"🎭","meta":["σόου με σκετς","2006–2014","Ρωσία"],"description":"Κάθε εκπομπή μαζεύει μερικά σύντομα κωμικά σκετς με σταθερό θίασο ηθοποιών, που παίρνουν αναγνωρίσιμες καθημερινές καταστάσεις και τις πάνε στο παράλογο. Από τα πιο αξιοσημείωτα σόου με σκετς της ρωσικής τηλεόρασης των χρόνων του 2000, στο κανάλι STS.","fact":"Ο τίτλος παραπέμπει στην ιδέα ότι ένα ολοκληρωμένο αστείο χωράει σε λίγα μόνο καρέ.","wiki_en":"6 Kadrov","wiki_ru":"6 кадров"},{"name":"Η Ρωσία μας","emoji":"🎪","meta":["σόου με σκετς","2006–2009","Ρωσία"],"description":"Σόου με σκετς που παρελαύνει μια γκαλερί γκροτέσκων τύπων από κάθε γωνιά της Ρωσίας, από μετανάστες εργάτες ως σεκιουριτάδες, σατιρίζοντας κοινωνικούς τύπους και στερεότυπα που όλοι αναγνωρίζουν. Έγινε από τις πιο προβεβλημένες ψυχαγωγικές παραγωγές του καναλιού TNT στα τέλη του 2000.","fact":"Το φορμά οφείλει πολλά στο βρετανικό «Little Britain», προσαρμοσμένο στη ρωσική πραγματικότητα.","wiki_en":"Nasha Russia","wiki_ru":"Наша Russia"},{"name":"Ζήτω η Νεολαία!","emoji":"🎊","meta":["σόου με σκετς","2006–2010","Ρωσία"],"description":"Σόου με σκετς, όπου ένας σταθερός θίασος νέων ηθοποιών παίζει σύντομα χιουμοριστικά στιγμιότυπα από τη φοιτητική και τη νεανική ζωή. Μια από τις αξιοσημείωτες ψυχαγωγικές παραγωγές του καναλιού STS στα τέλη της δεκαετίας του 2000.","fact":"Από τον θίασο πέρασαν αρκετοί ερμηνευτές που αργότερα έγιναν σημαντικές φιγούρες της ρωσικής χιουμοριστικής τηλεόρασης.","wiki_en":"Dayosh Molodyozh!","wiki_ru":"Даёшь молодёжь!"},{"name":"Τα Σκαθάρια","emoji":"🪲","meta":["κομεντί","2019–2023","Ρωσία"],"description":"Τρεις φίλοι από μια επαρχιακή πόλη κληρονομούν απρόσμενα ένα χρεοκοπημένο εργοστάσιο και προσπαθούν να το κάνουν κερδοφόρα επιχείρηση, χωρίς την παραμικρή εμπειρία. Η σειρά δένει την ελαφριά κομεντί με μια ζεστή ιστορία φιλίας και ενηλικίωσης.","fact":"Η πρώτη σεζόν βγήκε σε κανάλι του YouTube, πριν η σειρά εγκατασταθεί στην πλατφόρμα PREMIER.","wiki_en":"Zhuki (TV series)","wiki_ru":"Жуки (телесериал)"},{"name":"Trigger","emoji":"💢","meta":["δράμα","2018–2020","Ρωσία"],"description":"Ο ψυχοθεραπευτής Αρτιόμ Στρελέτσκι χρησιμοποιεί προκλητικές και ανορθόδοξες μεθόδους, βγάζοντας κυριολεκτικά τους ασθενείς του από τα νερά τους για το δικό τους καλό. Η σειρά του Πρώτου Καναλιού φέρνει θέματα ψυχολογίας και τραύματος στο ευρύ κοινό της κρατικής τηλεόρασης.","fact":"Οι μέθοδοι του ήρωα βασίζονται σε μια υπαρκτή σχολή ψυχοθεραπείας, την προκλητική θεραπεία, που δουλεύει με ανορθόδοξες τακτικές.","wiki_en":"Trigger (TV series)","wiki_ru":"Триггер (телесериал)"},{"name":"Twin Peaks: The Return","emoji":"🦉","meta":["δράμα μυστηρίου","2017","ΗΠΑ"],"description":"Ένα τέταρτο του αιώνα μετά την αρχική σειρά, ο Ντέιβιντ Λιντς επιστρέφει στην ιστορία της κωμόπολης Τουίν Πικς με μια νέα σεζόν, ακόμη πιο σουρεαλιστική και πειραματική. Η τρίτη σεζόν της λατρεμένης σειράς είναι γυρισμένη σαν μια ενιαία ταινία πολλών ωρών.","fact":"Και τα δεκαοκτώ επεισόδια της σεζόν τα σκηνοθέτησε ο ίδιος ο Ντέιβιντ Λιντς, σπάνιο για τηλεοπτική παραγωγή αυτού του μεγέθους.","wiki_en":"Twin Peaks: The Return"},{"name":"Everybody Loves Raymond","emoji":"🍝","meta":["σιτκόμ","1996–2005","ΗΠΑ"],"description":"Ο αθλητικογράφος Ρέιμοντ Μπαρόνε προσπαθεί να κρατήσει την ειρήνη στο σπίτι, ζώντας κυριολεκτικά απέναντι από τους γονείς του, που χώνονται στην κάθε λεπτομέρεια της ζωής του. Ένα από τα πιο επιτυχημένα αμερικανικά σιτκόμ της αλλαγής του αιώνα, με πάρα πολλά βραβεία Έμι.","fact":"Πάνω στη σειρά στηρίχτηκαν αρκετές διεθνείς εκδοχές, ανάμεσά τους και η ρωσική «Οι Βορονίν».","wiki_en":"Everybody Loves Raymond"},{"name":"Roseanne","emoji":"👩‍👧‍👦","meta":["σιτκόμ","1988–1997","ΗΠΑ"],"description":"Η σειρά δείχνει τη ζωή της εργατικής οικογένειας Κόνερ στην επαρχία του Ιλινόι χωρίς την εξιδανίκευση των συνηθισμένων σιτκόμ: με οικονομικές δυσκολίες και καθημερινούς τσακωμούς. Η σειρά της Ροζάν Μπαρ ήταν από τις πρώτες στην αμερικανική τηλεόραση που μίλησε ειλικρινά για τη ζωή με λίγα λεφτά.","fact":"Πάνω από είκοσι χρόνια μετά το φινάλε, η σειρά αναβίωσε το 2018 με τον ίδιο βασικό θίασο.","wiki_en":"Roseanne","wiki_ru":"Розанна"},{"name":"The Cosby Show","emoji":"👨‍👩‍👧‍👦","meta":["σιτκόμ","1984–1992","ΗΠΑ"],"description":"Μια άνετη μαύρη οικογένεια της μέσης τάξης — ο γυναικολόγος Κλιφ Χάξταμπλ, η δικηγόρος γυναίκα του και τα πέντε παιδιά τους — έκανε τη σειρά ένα από τα σιτκόμ με τα υψηλότερα ποσοστά στην Αμερική της δεκαετίας του 1980. Άλλαξε σε μεγάλο βαθμό την τηλεοπτική εικόνα της μαύρης οικογένειας.","fact":"Στην ακμή της, η σειρά έμεινε για αρκετές σεζόν στη σειρά η πρώτη σε ποσοστά στην αμερικανική τηλεόραση.","wiki_en":"The Cosby Show"},{"name":"Dallas","emoji":"🤠","meta":["δράμα","1978–1991","ΗΠΑ"],"description":"Οι ίντριγκες και οι οικογενειακές συγκρούσεις της πλούσιας τεξανής πετρελαϊκής δυναστείας των Γιούινγκ, με απιστίες, προδοσίες και πόλεμο για τον έλεγχο μιας επιχειρηματικής αυτοκρατορίας. Από τις πιο επιτυχημένες σειρές πρώτης ζώνης της δεκαετίας του 1980, που έβαλε τη μόδα των σαπουνόπερων για πλούσιες οικογένειες.","fact":"Η ανατροπή με την ανάσταση ενός ήρωα, που εξηγήθηκε ως όνειρο μιας ηρωίδας για μια ολόκληρη σεζόν, μένει από τις πιο συζητημένες στην ιστορία της τηλεόρασης.","wiki_en":"Dallas (1978 TV series)"},{"name":"Δυναστεία","emoji":"👑","meta":["δράμα","1981–1989","ΗΠΑ"],"description":"Σειρά για τους πλούσιους μεγιστάνες του πετρελαίου Κάρινγκτον στο Ντένβερ, που οι εσωτερικές τους διαμάχες και η πολυτελής ζωή τους έγιναν το πρότυπο του μελοδράματος πρώτης ζώνης της δεκαετίας του 1980. Έμεινε για τις εντυπωσιακές τουαλέτες και για μια από τις πιο γνωστές γυναικείες αναμετρήσεις της τηλεόρασης.","fact":"Τα κοστούμια της έβαλαν σε μεγάλο βαθμό τη μόδα των φαρδιών ώμων και της πολυτελούς γκαρνταρόμπας που ταυτίζεται με τη δεκαετία του 1980.","wiki_en":"Dynasty (1981 TV series)"},{"name":"Beverly Hills, 90210","emoji":"🌴","meta":["εφηβικό δράμα","1990–2000","ΗΠΑ"],"description":"Η σειρά παρακολουθεί τη ζωή μιας παρέας μαθητών σε προνομιακό σχολείο πλούσιας συνοικίας του Λος Άντζελες, με τους έρωτές τους, τις φιλίες και την ενηλικίωση μέσα στη χλιδή. Από τα πρώτα πραγματικά επιτυχημένα νεανικά δράματα, που έβαλε τη μόδα του είδους για δεκαετίες.","fact":"Ο τίτλος βγαίνει από τον αληθινό ταχυδρομικό κώδικα της συνοικίας Μπέβερλι Χιλς: 90210.","wiki_en":"Beverly Hills, 90210"},{"name":"Melrose Place","emoji":"🏢","meta":["δράμα","1992–1999","ΗΠΑ"],"description":"Το σπιν οφ του «Beverly Hills, 90210» δείχνει τη ζωή μιας ομάδας νέων ενηλίκων που νοικιάζουν διαμερίσματα στο ίδιο συγκρότημα του Λος Άντζελες, με έρωτες, απιστίες και επαγγελματικές φιλοδοξίες. Έγινε ένα από τα κύρια μελοδράματα πρώτης ζώνης της δεκαετίας του 1990.","fact":"Αρχικά σχεδιάστηκε ως πιο ήρεμο, ρεαλιστικό δράμα, αλλά με τον καιρό έγινε πολύ πιο μελοδραματικό και εξεζητημένο.","wiki_en":"Melrose Place"},{"name":"Muñeca Brava","emoji":"💃","meta":["τελενοβέλα","1998–1999","Αργεντινή"],"description":"Η σεμνή Μιλαγκρός, ένα κορίτσι από φτωχή συνοικία, βρίσκεται στον κόσμο μιας πλούσιας αργεντίνικης οικογένειας, όπου συναντά ίντριγκες και βρίσκει τον αληθινό έρωτα. Η αργεντίνικη τελενοβέλα, με τη νεαρή Ναταλία Ορέιρο στον πρωταγωνιστικό ρόλο, έγινε τρομερά δημοφιλής πολύ πέρα από τη Λατινική Αμερική.","fact":"Το τραγούδι της σειράς, στη φωνή της Ναταλίας Ορέιρο, έγινε πραγματική επιτυχία και έξω από την Αργεντινή.","wiki_en":"Muñeca Brava"},{"name":"The Seven Deadly Sins","emoji":"🍺","meta":["άνιμε φαντασίας","2014–2021","Ιαπωνία"],"description":"Μια ομάδα ιπποτών, κάποτε δοξασμένων και μετά συκοφαντημένων, με το προσωνύμιο «Επτά Θανάσιμα Αμαρτήματα», ξανασμίγει για να σώσει το βασίλειο από μια συνωμοσία και να αποκαταστήσει το όνομά της. Από το μάνγκα του Νακάμπα Σουζούκι, δένει το φανταστικό με χιούμορ και ρομάντζο.","fact":"Κάθε ένας από τους επτά πρωταγωνιστές συνδέεται με ένα από τα βιβλικά θανάσιμα αμαρτήματα, που αντανακλά ένα γνώρισμα του χαρακτήρα του.","wiki_en":"The Seven Deadly Sins (TV series)","wiki_ru":"Семь смертных грехов"},{"name":"What We Do in the Shadows","emoji":"🧛","meta":["κομεντί","2019–2024","ΗΠΑ"],"description":"Τέσσερα βαμπίρ που συγκατοικούν στο Στέιτεν Άιλαντ γυρίζονται για ένα ψεύτικο ντοκιμαντέρ σχετικά με την αιώνια, αλλά περιέργως βαρετή και καθημερινή αθανασία τους. Σπιν οφ της ομώνυμης νεοζηλανδικής ταινίας του 2014, κράτησε τη μορφή του ψευδοντοκιμαντέρ.","fact":"Βασίζεται στην ταινία του 2014 των Τάικα Γουαϊτίτι και Τζεμέιν Κλέμεντ, που ήταν και παραγωγοί της σειράς.","wiki_en":"What We Do in the Shadows (TV series)"},{"name":"Mighty Morphin Power Rangers","emoji":"🦸","meta":["υπερηρωική δράση","1993–1996","ΗΠΑ"],"description":"Πέντε απλοί έφηβοι παίρνουν από έναν εξωγήινο μέντορα την ικανότητα να μεταμορφώνονται σε πολύχρωμους υπερήρωες Ρέιντζερς, για να προστατεύουν τη Γη από διαστημικούς κακούς. Έγινε από τις πιο αναγνωρίσιμες φραντσάιζ της δεκαετίας του 1990, ενώνοντας αμερικανικές σκηνές με ιαπωνικά πλάνα μάχης από το «Super Sentai».","fact":"Οι σκηνές δράσης μοντάρονταν από υλικό της ιαπωνικής σειράς «Super Sentai», προσαρμοσμένο στην αμερικανική πλοκή.","wiki_en":"Mighty Morphin Power Rangers"},{"name":"Η Σχολή: Νέα Εστία","emoji":"🛏️","meta":["σιτκόμ","2011–2018","Ρωσία"],"description":"Το σπιν οφ της «Σχολής» μεταφέρει τον θεατή σε μια φοιτητική εστία, όπου μια νέα γενιά ηρώων περνά τις κωμικές καταστάσεις της φοιτητικής καθημερινότητας και των σχέσεων. Από τα μακρόβια ναυαρχιδικά σιτκόμ του καναλιού TNT.","fact":"Είναι η συνέχεια της παλιότερης παραγωγής «Η Σχολή», που η δράση της τοποθετούνταν μερικά χρόνια πριν.","wiki_en":"Univer. Novaya Obshchaga","wiki_ru":"Универ. Новая общага"},{"name":"Κατ' Οίκον Περιορισμός","emoji":"🏠","meta":["σατιρική κομεντί","2018","Ρωσία"],"description":"Ένας νέος μπλόγκερ της επαρχίας προκαλεί κατά λάθος πολιτικό σκάνδαλο με ένα κοφτό βίντεο για τη διαφθορά των τοπικών αρχών, και καταλήγει σε κατ' οίκον περιορισμό, από όπου παρακολουθεί την παράλογη αντίδραση των αξιωματούχων. Πολιτική σάτιρα δεμένη με κομεντί καταστάσεων.","fact":"Βγήκε σε πλατφόρμα και έγινε γνωστή για πολιτική σάτιρα ασυνήθιστα κοφτερή για τη ρωσική τηλεόραση.","wiki_en":"Domashny Arest","wiki_ru":"Домашний арест (телесериал)"},{"name":"Καλέστε τον ΝτιΚάπριο!","emoji":"📱","meta":["δράμα","2018","Ρωσία"],"description":"Ένας νέος ηθοποιός, που μόλις έχει πατήσει το πρώτο σκαλί της επιτυχίας, μαθαίνει ότι είναι οροθετικός και πρέπει να ξαναδεί από την αρχή τη σχέση του με την καριέρα, τους δικούς του και τον εαυτό του. Η ρωσική μίνι σειρά ήταν από τις πρώτες στην εγχώρια τηλεόραση που άνοιξε ανοιχτά και χωρίς στιγματισμό το θέμα της ζωής με HIV.","fact":"Επαινέθηκε γιατί χειρίστηκε το θέμα του HIV με λεπτότητα και χωρίς καταδίκη, σπάνιο για τη ρωσική τηλεόραση.","wiki_en":"Zvonite DiCaprio!","wiki_ru":"Звоните ДиКаприо!"},{"name":"Τα Κορίτσια","emoji":"👭","meta":["δράμα","2018–2021","Ουκρανία/Ρωσία"],"description":"Η σειρά δείχνει τη ζωή μιας ομάδας γυναικών σε γυναικείο σωφρονιστικό κατάστημα: τις φιλίες τους, τις συγκρούσεις και τις προσπάθειές τους να κρατήσουν τον εαυτό τους μέσα στις σκληρές συνθήκες του εγκλεισμού. Παραγωγή της πλατφόρμας Start, ξεχώρισε για την ειλικρινή, χωρίς εξωραϊσμούς ματιά της.","fact":"Στα γυρίσματα συμβουλεύτηκαν ανθρώπους που γνώριζαν την πραγματική καθημερινότητα των σωφρονιστικών ιδρυμάτων, για μεγαλύτερη πιστότητα.","wiki_en":"Chiki (TV series)","wiki_ru":"Чики (телесериал)"},{"name":"Emily in Paris","emoji":"🥐","meta":["ρομαντική κομεντί","από το 2020","ΗΠΑ"],"description":"Η αμερικανίδα ειδικός του μάρκετινγκ Έμιλι Κούπερ μετακομίζει απρόσμενα για δουλειά στο Παρίσι και προσπαθεί να συνδυάσει τη γαλλική φινέτσα με τον αμερικανικό εργασιακό ζήλο, περνώντας παράλληλα από σειρά ρομαντικών περιπετειών. Η σειρά του Netflix ξεχωρίζει για τη λαμπερή εικόνα και τα ρούχα της ηρωίδας.","fact":"Γυρίζεται κυρίως σε αληθινές, αναγνωρίσιμες τοποθεσίες του Παρισιού, κάτι που έχει γίνει μέρος της οπτικής της γοητείας.","wiki_en":"Emily in Paris"},{"name":"Hawaii Five-0","emoji":"🌺","meta":["αστυνομικό δράμα","2010–2020","ΗΠΑ"],"description":"Μια ειδική μονάδα της αστυνομίας της Χαβάης, με επικεφαλής τον ντετέκτιβ Στιβ ΜακΓκάρετ, ερευνά τις πιο δύσκολες υποθέσεις του νησιού, από το λαθρεμπόριο ως την τρομοκρατία. Η σύγχρονη σειρά είναι ριμέικ της ομώνυμης αστυνομικής σειράς των τελών του 1960 και κράτησε τους γνώριμους τίτλους και το μουσικό θέμα.","fact":"Το μουσικό θέμα, που κληρονομήθηκε σχεδόν αναλλοίωτο από την αρχική σειρά του 1968, θεωρείται από τα πιο αναγνωρίσιμα της τηλεόρασης.","wiki_en":"Hawaii Five-0 (2010 TV series)"},{"name":"CSI: NY","emoji":"🗽","meta":["αστυνομικό δράμα","2004–2013","ΗΠΑ"],"description":"Ακόμη ένα σπιν οφ του αρχικού «CSI» μεταφέρει μια ομάδα εγκληματολόγων στη Νέα Υόρκη, όπου τις έρευνες κατευθύνει ο ντετέκτιβ Μακ Τέιλορ, επιζών της επίθεσης της 11ης Σεπτεμβρίου. Κράτησε το φορμά της φραντσάιζ και πρόσθεσε νεοϋορκέζικο χρώμα και πιο προσωπικό δράμα για τον πρωταγωνιστή.","fact":"Το παρελθόν του πρωταγωνιστή συνδέεται με τον θάνατο της γυναίκας του στην επίθεση της 11ης Σεπτεμβρίου 2001.","wiki_en":"CSI: NY"},{"name":"Murder, She Wrote","emoji":"✍️","meta":["αστυνομικό","1984–1996","ΗΠΑ"],"description":"Η Τζέσικα Φλέτσερ, συγγραφέας αστυνομικών και ερασιτέχνης ντετέκτιβ, βρίσκεται με αξιοσημείωτη συχνότητα κοντά στον τόπο ενός εγκλήματος στην ήσυχη πόλη της και το εξιχνιάζει πιο γρήγορα από την επίσημη αστυνομία. Από τις πιο μακρόβιες αστυνομικές σειρές της αμερικανικής τηλεόρασης των δεκαετιών του 1980 και του 1990.","fact":"Παρά τον καλοσυνάτο χαρακτήρα της, σε όλη τη διάρκεια της σειράς βρέθηκε μάρτυρας σε αρκετές εκατοντάδες φόνους — παράδοξο που οι θεατές δεν έπαψαν να σχολιάζουν.","wiki_en":"Murder, She Wrote","wiki_ru":"Она написала убийство"},{"name":"MacGyver","emoji":"🧰","meta":["δράσης, περιπέτειας","1985–1992","ΗΠΑ"],"description":"Ο μυστικός πράκτορας Άνγκους ΜακΓκάιβερ βγαίνει από τις πιο επικίνδυνες καταστάσεις όχι με τη δύναμη των όπλων αλλά με εφευρετικότητα, φτιάχνοντας πανούργες κατασκευές από ό,τι βρει μπροστά του. Ο ήρωας έκανε το ίδιο του το όνομα συνώνυμο της πρόχειρης, έξυπνης λύσης.","fact":"Το επώνυμό του έγινε ρήμα, «to macgyver»: να λύνεις ένα πρόβλημα ευρηματικά με ό,τι έχεις πρόχειρο.","wiki_en":"MacGyver (1985 TV series)"},{"name":"Miami Vice","emoji":"🌴","meta":["αστυνομικό δράμα","1984–1990","ΗΠΑ"],"description":"Δύο ντετέκτιβ υπό κάλυψη στο ηλιόλουστο Μαϊάμι ερευνούν το εμπόριο ναρκωτικών και το οργανωμένο έγκλημα, συνδυάζοντας την επικίνδυνη δουλειά με το εκκωφαντικό οπτικό ύφος της δεκαετίας του 1980: παστέλ κοστούμια και ταχύτατα σκάφη. Η σειρά καθόρισε σε μεγάλο βαθμό την αισθητική μιας ολόκληρης δεκαετίας.","fact":"Το σήμα κατατεθέν της — παστέλ κοστούμια δίχως κάλτσες και νέον παντού — επηρέασε αισθητά τη μόδα της δεκαετίας του 1980.","wiki_en":"Miami Vice"},{"name":"Xena: Warrior Princess","emoji":"🗡️","meta":["δράσης, φαντασίας","1995–2001","ΗΠΑ"],"description":"Η Ζίνα, πρώην πολεμίστρια με σκοτεινό παρελθόν, περιπλανιέται σε μια μυθολογική αρχαία Ελλάδα μαζί με την πιστή της σύντροφο Γαβριέλα, παλεύοντας για να εξιλεωθεί για τα παλιά της κρίματα. Από τις εμβληματικές σειρές της αμερικανικής τηλεόρασης της δεκαετίας του 1990 και λατρευτική φιγούρα για γενιές γυναικών θεατών.","fact":"Η Ζίνα πρωτοεμφανίστηκε ως δευτερεύων χαρακτήρας στη σειρά «Hercules: The Legendary Journeys», πριν αποκτήσει δική της σειρά.","wiki_en":"Xena: Warrior Princess"}];
